/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150120-6","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"区民委員会","time":"午後 １時００分～午後 ４時４５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)「第４０回消費生活展・第７回社会貢献活動しながわ」の開催","agenda":"はじめに、(1)「第４０回消費生活展・第７回社会貢献活動しながわ」の開催","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"今回二つの開催ということですけれども、今お話をいただいていたら、相乗効果が上がるのではないかということですが、今年の取り組みであって、来年はまた検討するというニュアンスなのか、その辺と、あと開催日時が近かったというのが一番なのか、一緒にした一番のところというのは、区の投げかけなのか、実行委員会の発意で一緒にやったらどうかというようなことなのか、その辺の経過は。","respondent":"米田商業・観光課長","answer":"当然その実行委員会というのは、年度が替わった当初からそれぞれ形成されておりますので、特に今年度については実行委員会が結成された当初から、昨年度の経過も踏まえて合同開催できないかということで一種の投げかけを行ったところ、それぞれの団体が新たなつながりを求めたい。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"今回、社会貢献活動しながわのほうだと、スペース的な問題は理解はするのですけれども、１日のみの入れ替えになってしまうということであれば、社会貢献活動のほうの目的としての活動の中の交流というのは半減するのかなと思っているので、ここについてはやってみないとわからないねという当事者の方たちのご意見もいただいているので、まあ、やってみて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"浅野委員","kind":"質問","question":"今回また新しい試みとして、同時開催ということだと思います。それと、今回同じ日に同じ場所でやるということで、来場者数は増えると見込んでいるのかどうか。そこら辺をちょっと、もくろみというのでしょうか、教えていただければと思います。","respondent":"米田商業・観光課長","answer":"消費生活展であったり、あるいは社会貢献活動であったりのイベントものも少し増やしたりしていますので、そういった意味では来場者数は増えるものと考えています。","id":"exchange-003"},{"speaker":"浅野委員","kind":"質問・要望","question":"イベントを通じて団体ブースの情報交換ということですけれども、団体同士ですと、例えば品川区の登録消費者団体また社会貢献活動しながわとか、協力団体とかあるのですけれども、その壁を取っ払った交流を目指しているというふうに聞こえているのですが、実際にこれまでにそういう団体同士がコラボというのでしょうか、そういう形で何かめざましいものとか。","respondent":"米田商業・観光課長","answer":"特に両方の団体とも、どちらかというと年齢層の高い方が多いので、特に社会貢献活動のほうは大学の方とかも結構お見えになったりしているので、そういう若い方々にぜひボランティアとかで力になっていただきたいということでは、ちょっとずれるかもしれませんけれども。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"一つ、このブースで２日間連続のところ、下のほうに水道局とか生活文化局とか、そういう部分で２日あるのですけれども、この議論の中で、２日出したいのだけれども出られませんでしたというようなところとかあるのか、なかなか人材的に難しいので１日でいいですというような、中はどういうふうに、すんなりいっているのか、いろいろと調整が必要だったのか、その辺の実態。","respondent":"米田商業・観光課長","answer":"そういった意味では、出展のご意向調整というのは実行委員会でやっておりますけれども、十分念入りな団体間の調整は図れているものと考えています。","id":"exchange-005"}]},{"id":"topic-02","title":"第１１回品川区新製品・新技術クラスターフェアの開催","agenda":"第１１回品川区新製品・新技術クラスターフェアの開催","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"クラスターフェアというのはもう１１回ということですけれど、毎回どれぐらいの参加者なのかということと、どういう方を対象にこれがされるのか、またこのリーフレットもありますけれど、これはどういうところに、どういう形でＰＲをするのかというところを教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"毎年ほぼ同じご来場者数ですけれども、昨年は５３０名の方が来られています。内訳としますと、４５０名の方々が一般企業の方の来場者、残りの８０名が２３区の産業関連の方々あるいは東京都、国というような行政の関連ということです。","id":"exchange-006"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"本多委員","kind":"意見","question":"どうしても我々日本人がどこか国内でも国外でも行くときエリアマップを参照するように、外国の方もエリアマップを非常に参考にすると思うのですが、そのエリアマップのあり方で、１枚でレストランとかショップとか、カフェとか、挨拶文とか、いろいろな情報が１枚で見られるのは、すごく集約されていて見やすいとは思うのですが、目的別に変えたほうがいいのか、１枚で集約したほうがいいのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"都市型観光ということで、何度も私も質問させていただいたりしているのですけれども、いつのニュースだったか、今日だったかもしれないですけれど、外国人が、１,３４０万人とかって言っていませんでしたっけ。そのぐらいの数の人が来ているというふうに、今日のニュースだったかもしれません、出ていたような気がします。おととしが１,０００万人だったと思うのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問・要望","question":"２０１５年には１,５００万人以上というような予測も出ていたような気がします。ちょっと数字間違えているかもしれませんけれども。中でも、よく私も聞かれるのですけれども、無料の無線ＬＡＮですか、そういうものにも対応していくというのは、品川区としてもやっていかなくてはならないかなと思います。そういう意味では、ＩＴ関係は世界共通でありますので、ぜひとも進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"木村委員","kind":"意見","question":"これから２０２０年には東京オリンピックということで、品川区にもいろいろな競技が来ますけれども、例えば海外の方が来て、立会川のあたり、あの辺は駅を利用して会場に行くということはないのかもしれないですが、帰りにふらりと海外の方々が歩いたりする場合に、例えば立会川の、川沿いというのはお店の裏側が見えるところってありますよね。ちょっとお聞かせ願いたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"木村委員","kind":"意見","question":"それは行政が主導していくということはなかなか難しいことだと思いますけれども、そういうことが可能であるのかどうかという部分、何らかの模索をして、そういうことが主導していけるのかどうか、という可能性があるかどうかということだけでも聞かせてください。","respondent":"米田商業・観光課長","answer":"それともう一つ大事なのは、いかに地域で自分たちのまちを活性化していくかということで、それぞれ発意、発案があって、そのような流れでまちづくりだったり観光における集客、にぎわいをつくっていこうというようなこと、それに対して行政がどこまで支援できるかということは。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"まさに２０２０年以降の都市型観光というのはあると思うのですけれども、その中でも２０２０年のオリンピック・パラリンピックというのは重要で重大な一つだと考えていますが、２０２０年のオリンピック・パラリンピックの担当者として、都市型観光というのはどういうふうに思われて、またどういう形で具体的に考えていらっしゃるのか、大きい意味において伺っておきたいと思いますが、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック推進担当課長","answer":"スポーツの振興ですとか、観光の関係ですとか、ボランティアの関係、さまざまな課題を今洗い出しをして、それぞれ取り組むべきことを精査しながら、検討を進めているところですけれども、特に観光の部分については、やはり品川区にとって絶好のチャンスだと考えておりまして。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/719578?Template=document&Id=2716#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":16097,"voices":50}},{"id":"h27-20150120-7","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"厚生委員会","time":"午後 １時００分～午後 ３時１１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"の（仮称）品川区立障害児者総合支援施設整備運営事業者の公募","agenda":"の（仮称）品川区立障害児者総合支援施設整備運営事業者の公募","exchanges":[{"speaker":"石田（ち）副委員長","kind":"提案","question":"公募していくというところで、今、品川区内で、いろいろ手がけていただいている社会福祉法人にやっていただいているところですけれども、今回、こういうものが出されたり、提案されたりすると、事業所がどうなるかと、うわさで広がったりすることもあるのです。それは、今後、公募するのですけれども、今のところ、区としてここをどうかとか、想定している部分はあるのかどうか。","respondent":"中山障害者福祉課長","answer":"そういうときには、主となる事業者、それから従となる事業者が合わせて、合体した形で責任を持って分担をしながら、それでいて一つの事業所として応募していただく予定になっているところです。","id":"exchange-001"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やはり区が核になってこういった施設を進めていけば、それがほかの福祉法人にも影響をしていくということで、やはり責任を持って進めてほしいという声もどんどん寄せられている状況になっているのです。その辺、改めて区のほうとしてはどのように聞いているのか、どう考えているのかを改めて伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"ただやはり、障害者の支援というところで、専門性も要求されますし、これだけの大きな施設を直営で運営するのは難しいと考えております。ただ、区立の施設ですので、指定管理とはいえ、任せ切りというわけではございません。","id":"exchange-002"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"指定管理者制度が主流となってきてしまっている今の状況で、区が核になってやっていくというのは、今、本当に必要なのではないかと思います。それから、当事者の意見を聞きながら建設していただきたいと思うのですけれども、拠点になっていくわけですから、区内の障害者団体の皆さんの声をどのように反映していこうとしているのか、今現在、どういったことを働きかけているのか、あれば、教えてください。","respondent":"中山障害者福祉課長","answer":"最初の直営のところの話になりますが、区では、自立支援協議会というのを設けまして、区が中心となって支援者であるさまざまな施設の方たちと一緒に、障害者の施策をどういうふうに進めていくか、行っているところです。","id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"事業者が決まり次第、当事者の意見を一緒に聞いていくということですけれども、団体だけでなく、今利用されている方たちにアンケートを取るとか、今どういったことが必要なのか、それは常々取られていると思うのですけれども、改めて、やはり拠点とする施設ができるというところで展開していく考えはないでしょうか。","respondent":"中山障害者福祉課長","answer":"区職員の現場感覚のところですけれども、なかなか窓口だけで難しいところもあるかもしれないのですが、実際にうちの職員につきましても、ご自宅を訪問したり、あるいは施設を訪問したり、そういった中で現場での障害者の方の姿、そうしたものも見ながら、今。","id":"exchange-004"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"次の質問にいきたいのですけれども、３ページの短期入所のところで、体験型居室を準備し、とありますけれども、これはグループホームの体験型としてとらえていいのかどうか、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"できるだけそういった形で、短期入所して生活のリズムをつかみながら、スムーズに自宅からグループホームへの移行ができるような工夫につきましては、今後も、既存のグループホームともお話をしながら進めていきたいと考えております。","id":"exchange-005"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"少し話は変わるのですけれども、１５ページの法人を選定しない場合、水準を満たさないと判断された場合には、法人を選定せず、その旨を公表しますとなっていった場合は、その後はどうなっていくのか教えてください。","respondent":"中山障害者福祉課長","answer":"万が一、水準を満たさないで法人を選定しない場合につきましては、改めて仕切り直しということになろうかと考えています。","id":"exchange-006"},{"speaker":"伊藤委員","kind":"確認","question":"だから、確認したいのが、そういう品川区内での事業の実績はもちろん評価するであろうけれども、あえて全国公募による選定ということになっているのだから、やはり担当課としては、その辺はしっかりとした区別をして、Ａ事業者、Ｂ事業者、区内の事業者をきっちり評価する仕組みをつくっていくべきだと思うのですが、いかがでしょうか、改めてお答えください。","respondent":"中山障害者福祉課長","answer":"ここ最近、人員体制、職員の配置がすごく難しくなってきているというお話もありますので、例えば職員の離職率ですとか、そういったところもしっかりチェックしながら、よりよい、安定して良いケアができる法人の選定を目指していきたいと考えております。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"だから、これからのこの公募については、決して殺到するような状況ではないのかもしれない。ずっとお伺いしながら、厚生委員会の行政視察のことを思い出して、千歳市のワンストップサービスがありましたよね。それから、こういう施設をつくるのであれば、せっかくですから療育ノートを検討していただいて、ずっと大人になる過程の中で活用していけばいいと思うのですが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"年度内に策定するのは少し難しそうなのですけれども、来年度中には、何とかそれをつくって、それを使っていくことで、継続的な支援が続けられるように、そういった視点で頑張っていきたいと考えています。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"拠点は、これでできるでしょうけれども、そこで展開するサービスをどういうふうに具体化していくか、それも今までにない新しい、地域の方々の人材を活用した観点からこの障害者福祉も支えていかないと、やはり行政では限界があるということが目に見えていますので、そのことはぜひ検討してくださいとお願いしておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"たけうち委員","kind":"提案","question":"少し所管が違ってくる部分もあるのですけれども、福祉部門の方たちとしては、ここの事業者の提案が非常に優れていて、ぜひここにやってもらいたいと思ったけれども、経理のほうから見たときに、建築費用等の提案が少し高いのではないかとなった場合には、通常の入札ならば簡単に切れるわけですし、ほかの方式などでも大体金額がポイント化されますけれども。","respondent":"中山障害者福祉課長","answer":"ただ、あまりにも壮大な設計の計画が出てきてしまいますと、そこはやはり区立の建物という視点もありますので、悩ましいところではありますけれども、通常で考えれば、運営面のほうに力を入れて、運営のいい事業者をできるだけ選定していく。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問・要望","question":"趣旨としてはそういうことでプロポーザルなので、価格の面はもちろん安いに越したことはないし、また、あまりにも過大になってしまうと、これは税金ですから、当然なるべく抑えていかなければいけないというのはそうなのですけれども、今はなかなか、建築費等、人件費も非常に月々上がっていくような感じになっている中で、その辺がなかなか折り合わなくて、ただすごくサービス内容がいいなどという場合に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"山元委員","kind":"提案","question":"５ページの３．施設内任意事業ということで、これは提案事業のようなのですけれども、その中に販売や飲食店云々ということが書いてあります。","respondent":"中山障害者福祉課長","answer":"こちらにつきましては、この建設にあたって、いっとき別の場所に出ていただく予定です。ただ、新しい事業者がそういったものを構想していない場合には、それが仮移転ではなくて本移転ということで、別の場所を考えていく必要もあります。","id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"今の障害者福祉課長のお話だと、あまり考えていないということだったのですが、実は、知り合いが子どもをそこに連れていって、そこでお茶をして気分転換しているという方がいらっしゃったものですから、これを見ると、そういうところがなくなってしまうと、そのお母さんにしてみれば、気分転換できるところがないというのはどうなのかなと、そういう意味では。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-02","title":"の生活困窮者自立支援制度","agenda":"の生活困窮者自立支援制度","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"何点か確認させてください。費用負担のところですけれども、いわゆる都の補助はないのでしょうか。つまり、例えば自立支援相談事業等を行う場合、４分の３は国庫負担だけれども、４分の１は品川区負担になるのか、まず確認をお願いします。","respondent":"伊東生活福祉課長","answer":"この制度の、今お話しした費用負担につきましては、都の補助はなくて、国のほうから、先ほど申した４分の３ですとか、３分の２ですとか、２分の１と、そういうようなことになってあります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"確認","question":"わかりました。それで確認したいのが、では、この１,１００名の方々に対して、プラン作成なり、そのほかの住居確保給付金等々、それを具体的にどういうふうに展開していく予定があるのか。それから、より具体的な指導なり、対処が必要となってくるわけであるから、現行の人数でこの責任を果たすことができるのかという確認を、まずお願いします。","respondent":"伊東生活福祉課長","answer":"あわせまして、その７名の中で住居確保給付金の事業も実施していく予定です。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのは、この１,１００名の対象ですけれども、この中でも、多分いろいろな方がいらっしゃると思うのです。そういうふうにしていかないと、これは必須事業ですから、必ずやらなければいけないこととして、貴重な人材とお金を投入して、それらの実績が出にくいのではないかと思うのですが、いかがでしょうか。","respondent":"伊東生活福祉課長","answer":"しかしながら、モデル実施ということで、地方のほうでやっている事例がございまして、それを見ますと、プラン作成に至る前に、他法他施策といいますか、現状である社会資源といいますか制度を活用することによって、ある程度の方々が落ち着いていくということで。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、今でこそ、約１００億円前後投入されている生活福祉に対して、さらに品川区がまた一般財源を投入してこの事業を展開していくということについては、ちょっと矛盾を感じるところがあるのだけれども、その税金でこれだけの制度をやっていただいて、一人でも多くの方々が生活福祉から自立していただくようにお願いするのですけれども、改めて担当課長のお考えを確認させてください。","respondent":"伊東生活福祉課長","answer":"生活福祉のほうでは、窓口は分ける予定ですけれども、今の生活保護と今回始まる生活困窮者自立支援法を一緒にやっていくという中で、それぞれ連携を取りながら、当然、生活保護から脱却していただく方に関しては、必要に応じて、この生活困窮者自立支援法のほうでも。","id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私も何点かお願いしたいのですが、最初に確認ですけれども、２．法律の概要の(1)の必須事業は、これはやるということですけれども、(2)に1)から4)がありますけれども、この任意事業については、品川区としても今年の４月からやるということなのか、それとも、これから検討段階なのかということを教えていただきたい。その４点を教えてください。","respondent":"伊東生活福祉課長","answer":"１点目の品川区のほうで考えている任意事業ですけれども、就労準備支援事業および学習支援事業、そして家計相談支援事業につきましては、やはりメニューがあったほうが支援につながるであろうということで、実施していこうと、現状では考えておるところです。","id":"exchange-018"},{"speaker":"たけうち委員","kind":"確認","question":"確認ですけれども、任意事業のほうは、２の(2)の2)以外は今、品川区でも考えていくということでよろしいですね。おそらくこういうものができた場合には、多分相談にもいろいろな方がきて、その中では当然、実際にはさっき言ったようなさまざまの事情でまだ対象にならないとか、いろいろ出てくると思いますけれども、その辺をまとめて、最後に確認で教えてください。","respondent":"伊東生活福祉課長","answer":"ただ、生活困窮者は結構潜在的にいるのかと考えていますので、その辺、しっかりとしていかなければいけないと思っているところです。","id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"そうすると、必須事業のところですけれども、国のほうで出されているのは、総合相談支援事業で、自治体と民間による協働でワンストップの総合相談窓口を設置、ここから、この以下の事業につなげていくと出ていたのですけれども、この(1)がそれに当たってくるのかどうか。それからこの(1)を実施するとき、委託などはされるのか、それとも区が独自に進めていくのかを聞かせてください。","respondent":"伊東生活福祉課長","answer":"品川区の窓口ということで、生活福祉課の中に新しい制度を担当する相談窓口を置く予定でございまして、それでさまざまな連携を取りながら、ワンストップでいろいろとできるようにしていきたいと思っています。","id":"exchange-020"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"(2)の2)は今後実施していく予定なのか、それともこれをすぐに1)、3)、4)と一緒に実施しない理由は何なのかを伺いたいと思います。それから、4)の学習支援事業というのは子どもたちをどんな形で支援されるのか、もしあればお聞かせください。","respondent":"伊東生活福祉課長","answer":"学習支援事業ですけれども、こちらも、生活困窮の方は、なかなか子どもの学習環境が整っていない状況も見受けられるということで、子どもの家庭環境をよく確認し、子どもと共に親のほうの支援もしていきつつ、子どもの塾代とか、受験の関係でお金が必要なときには。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど１,１００名という数字が出されていて、国のパーセンテージをそのまま品川区にはめ込むとこうなるということで言えば、１,１００名以上かもしれないし、以下かもしれないという状況だと思いますけれども、品川区としてこういうことは把握できないのでしょうか。そこを伺いたいと思います。","respondent":"伊東生活福祉課長","answer":"前段の学習支援事業ですけれども、今、生活保護世帯を対象に子ども家庭支援事業ということでやってありますけれども、その対象者を生活困窮者というところに少し拡大しまして実施していこうと、現状で考えているところです。","id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほどのお話にもありましたけれども、７名ほどの支援相談員で進めていくというところでは、私はもう少し充実させたほうがいいのではないかと思います。先ほど、モデル実施している区があるとおっしゃっていたと思いますけれども、そのモデル実施している自治体はどこかわかるでしょうか。","respondent":"伊東生活福祉課長","answer":"最初の７名態勢ですけれども、実際の相談がどれだけ来所されるかというのは、まだ見えない状況がありますので、とりあえずは７名の態勢でスタートをしてみて、少し様子を見させていただいて、それから必要に応じてしっかり対応していければいいかと考えておるところです。","id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ充実に向けた支援事業にしていただきたいと思います。モデル実施は、２３区ではないということですね。都内であれば、もう少し具体的にわかるかと思ったのですけれども、わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"たけうち委員","kind":"質問・要望","question":"すみません、また細かいところで２点ほどお願いします。まさに今もうそういうところに住んでいないと、簡単に言うとホームレスだという方だけが対象なのかを教えていただきたい。それから、住居確保給付金に有期とありますけれども、これが何ヶ月くらいなのか、わかれば教えてください。","respondent":"伊東生活福祉課長","answer":"仮に住居を失っているということで、生活ができないということであれば、どちらかというと、一時生活支援事業のほうに該当してくるかと考えておるところです。その辺、うまく事業を振り分けて支援をしていければと思っておるところです。","id":"exchange-025"},{"speaker":"たけうち委員","kind":"意見","question":"離職により住宅を失ったという表現になっているけれども、今おっしゃったように、こういう例はあまりないということで、その場合には下の事業になるというお話であれば、これはいわゆる離職により住宅のおそれのあるというふうに書いたほうがいいということですね、わかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"つまり、緊急だということがはっきりわかった場合、例えばさわやか信用金庫が訪問されて、おかしいと、これは２４時間と書いてあるから、例えば夜中の場合、夜中の訪問はないのかもしれないけれども、とにかく品川区の体制がどうなっているのかという確認を、まずお願いします。","respondent":"大串福祉計画課長","answer":"そうした中で、お隣の高齢者福祉課、あるいはケースワーカーといったところに照会をさせていただき、その先、例えば公的なサービスを受けていらっしゃる方であれば、在宅介護支援センターといったところにも記録等々が残っておりますので、そういったところと連携しながら。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問","question":"もちろんそれでいいと思うのですけれども、いろいろな時間帯、例えば品川区の勤務時間外に、もしかしたらこういうところから情報が入ることも当然考えらえるわけで、ではそういうときに、この担当のそれぞれの事業者の方々がどこに連絡をしたらいいのか確実にわかっているのでしょうかということが１点。","respondent":"大串福祉計画課長","answer":"そうしたときには、一義的には我々のほうにご連絡をいただくことになっておりますが、ただ、高齢者福祉課のほうにも、そういった形で緊急対応をしていただける窓口がありますので、そちらのほうにもつなげつつ。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"確認","question":"そこがやっぱり大切ですね。せっかく得た情報を、品川区がきちんと捉えていかないといけないので、その確認をさせていただきました。高齢者はなかなかネットスーパーを使わないのかもしれないけれども、でもこういうものはコストがかからないで的確な情報が上ることからすると、当然いろいろな企業と連携を取っていくべきだと思うのですけれども、そのことについてのお考えをもう一度お聞かせください。","respondent":"大串福祉計画課長","answer":"その中でいろいろ対応させていただいているのですが、正直申し上げまして、企業が顧客と顔の見えるおつき合いをしてるかどうか、それが一番重要なポイントになってまいります。不定期に訪問されるだけでは、その家の状況はわからないわけです。","id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問","question":"そうですよね、逆に企業側の宣伝に使われると困ることもありますよね。この事業をこれから継続的にやっていきたいと、品川区が思っていらっしゃると思うのです。そうであるならば、１０万円、５万円、２万円ということではなくて、どこかの線をしっかり引いて、ぜひ必要経費の中で、こういう見守りネットワークに使ってくださいと言ったほうがいいと思うのですが、いかがですか。","respondent":"大串福祉計画課長","answer":"今、委員からご指摘があったような形での助成金のあり方等々については、今現在、検討しています。近々また予算の審議の場でご提案をさせていただければと考えていますので、その際はよろしくお願いいたします。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"意見","question":"所管が違うといけないのですけれども、子育ても、地域福祉の中で一緒の枠に入っていまして、いろいろそれぞれの対応をされていると思うのですけれども、例えば３．高齢者見守りネットワーク事業なども高齢者になるわけですけれども、また２．支え愛・ほっとステーションも高齢者になっていますけれども、例えば障害者とか、所管が違うのでわかる範囲でいいのですけれども、子育てなども、今後。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ゆくゆくはというか、やはり地域包括ケアの中でも、区のほうは、高齢者を中心に考えていくという、本会議などで会派の質問に対する答弁もありましたので、一定程度理解はしておりますが、この図のあるとおり、やはり地域福祉ですから、理想かもしれませんけれども、例えば富山型のデイサービスとか、そういう垣根を越えた部分とか、また子育ても含めて、副区長がいらっしゃるので、今後ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"向委員","kind":"質問・要望","question":"確認だけさせていただきたいのが、２ページの４．民間企業と連携した高齢者等地域見守りネットワークの構築事業のところで、先ほど伊藤委員からも質問があった内容についてですが、ご協力いただいている各企業は、基本的にはボランティアで支援をしてくださっているのかどうか、一つ確認させていただきたい。その２点をお願いします。","respondent":"大串福祉計画課長","answer":"その辺を見極めつつ、水道局以外の公共事業者といったところに関しても、こういった形の見守りネットワークが形成できるのかどうかについても、引き続き検討はしていきたいと考えています。","id":"exchange-033"},{"speaker":"向委員","kind":"質問","question":"よくわかりました。最後にお伺いしたいのが、こうやって企業側から支援したいということでたくさん手を挙げてくださるのはありがたいお話だと思うのですけれども、企業がこうやって手を挙げたいと思われる理由は何なのでしょうか。今、区として受けられている、企業が手を挙げたがる主な理由にどういう傾向があるのか、それだけ簡単に最後にお聞きできればと思います。","respondent":"大串福祉計画課長","answer":"そうしたところで、企業にとっても、ボランティアということで一定程度負担はかかるけれども、これを結ぶことよってのさまざまな企業側にとってのメリット、そういったものもあるのかというのは担当としてお話をしていく中で感じたところです。","id":"exchange-034"},{"speaker":"向委員","kind":"質問","question":"確かに警察にコンタクトするというのは、気軽に１１０番する方も、迷惑電話も増えているという話も聞きますけれども、本当に大事なときは警察かなと思う反面、やはりそうやってハードルが高いところを区のほうで吸い上げていくというか、それがネットワーク構築に至ることで、私たち区民にも恩恵が返ってくるというのは本当に重要なことだと思うので、さらなる将来的な発展も期待しつつ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"松永委員","kind":"質問","question":"私からは１点だけ、支え愛・ほっとステーション事業の中で、今は品川第二地区と荏原第二地区ですけれども、今後増やす計画はあるのでしょうか。","respondent":"大串福祉計画課長","answer":"そちらの拡大に関してのお話、予算的な措置が伴いますので、それにつきましては、また改めて予算を審議する場にご提案していきたいと思っているところです。今現在のところ、これについては拡大していくということで、基本方針としては持っているところです。","id":"exchange-036"},{"speaker":"山元委員","kind":"質問・要望","question":"私も、まずは支え愛・ほっとステーション事業ですけれども、今、実績を見ると、平成２５年度、平成２６年度の訪問の数を見ると、品川第二地区にしても、荏原第二地区にしても、すごい数だと思うのですけれども、実際に社会福祉士が訪問しているのかということを教えていただきたい。それから、緊急通報というのは、どういうことで通報があったのか、その辺も少し教えていただきたいと思います。","respondent":"大串福祉計画課長","answer":"ステーションということで設置させていただきましたけれども、なかなかまだ馴染みがないといったところもあったかと思いますが、だんだんこういうことをやってくれるということで、皆さんの認識も深まった中で、訪問に来てほしいといったお声もいただくようになり。","id":"exchange-037"},{"speaker":"山元委員","kind":"質問・要望","question":"次に高齢者見守りネットワーク事業について、少しお聞きしたいのですけれども、町会等で、また普及啓発事業の実施ということで、私の感覚では、町会で見守りというイメージがありましたけれども、ここには団体と書いてあるのですが、団体というのは、どういうメンバーというか、どういうことなのでしょうか。","respondent":"大串福祉計画課長","answer":"高齢者見守りネットワーク事業の内容のところで、2)が普及啓発事業の実施、3)が関係機関による連絡会の開催となっておりますけれども、普及啓発事業の実施というのが、昨年でしたら、夏に見守り活動をやっていただいている町会・自治会の皆さんにお集まりいただいて。","id":"exchange-038"},{"speaker":"山元委員","kind":"質問","question":"実際に町会の中でも、いろいろな意味で協力したいという思いがあるのですね。それから、区としては、先ほど、初年度は１０万円助成するとか、いろいろおっしゃっていましたけれども、理想というか、将来的には全町会でというふうにお思いなのでしょうか。","respondent":"大串福祉計画課長","answer":"引き続き、そういった形での周知、啓発に努めていきたいと考えております。","id":"exchange-039"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、少しずつ設置が増えてきているのですけれども、こういったもののさらなる普及の周知をしていくという考えは、どういうふうに進んでいるのか。それから、昨年、緊急通報システムの利用料の軽減の旨の検討をしていくというお話もあったと思うのですけれども、それの進捗状況はどのようになっているのか、お聞かせいただきたいと思います。","respondent":"大串福祉計画課長、永尾高齢者福祉課長","answer":"こちらの緊急通報の設置の件数ですけれども、これはあくまでもステーションが設置されている２カ所での件数となっています。まだ在宅介護支援センターにつながっていないという方が課題になるかとは思いますけれども、そちらにつきましては、今、ご説明申し上げております支え愛・ほっとステーション事業のほうでも受けておりますので。","id":"exchange-040"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"緊急通報システムの利用料の検討は、今どうなっているのか。変わっていなければ、変わっていないでいいのですけれども、お願いします。","respondent":"永尾高齢者福祉課長","answer":"利用料につきましては、現在、検討中でございまして、その負担の金額等につきましては、予算にも関係してきているところですので、今現在ですと、検討中ということでご説明させていただきたいと思います。","id":"exchange-041"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"わかりました。先ほども、見守りネットワークのところでは、当初１０万円、それがどんどん下がっていくというところでは、こういったところにもう少し補助をしていくことも考えたほうがいいのかというところでは、町会・自治会等の意見、常々聞いていらっしゃると思うのですけれども、こういった声をどのように受けとめていて、どう考えているのか、お聞かせください。","respondent":"大串福祉計画課長","answer":"そうした意味では、皆さんのご意見はさまざまあろうかと思いますが、そうしたところを総合的に判断させていただいて、この助成金のありようについては、また改めてご提案をさせていただければと思っているところです。","id":"exchange-042","title":"町会・自治会支援"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"町会等にまだ関わっていない住民の皆さんも多くいると思うのです。そういったときに、どう対処していくのか。先ほど、警察に通報するのも少し敷居が高いという話もありましたけれども、まだ町会と関わりのない住民に対しての見守り等、こういうことがあったときには、こういうふうに対処すると望ましいというような、そういった啓発などはどのようになっていますでしょうか。","respondent":"大串福祉計画課長","answer":"いずれにいたしましても、町会・自治会、それからこういった民間事業者は両輪になろうかと思います。こちらの活動を幅広く支援して、見守りの体制をより一層充実していきたいと考えているところです。","id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"こういうふうにまとまっていると、それぞれこういう事業なのだと、事業別に見ることができてとてもわかりやすいのですけれども、地域に入ってしまうと、何がどうで何なのかというのがわかりづらいので、その辺を地域住民の皆さんにお知らせしていく、周知をしていくということも必要なのではないかと思うのですけれども、その辺はどうお考えでしょうか。","respondent":"大串福祉計画課長","answer":"オーバーラップするというか、重なる場合もありますし、重ならない場合も出てくるといったところで、いずれにいたしましても、こういった町会・自治会、それから民間事業者、いろいろな網の目を編み上げていければと考えているところです。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/866699?Template=document&Id=3406#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":40569,"voices":109}},{"id":"h27-20150120-8","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"建設委員会","time":"午後 １時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","topics":[{"id":"topic-01","title":"の１「報告事項」を聴取いたします。 初めに(1)、東急線ホームドアの設置","agenda":"の１「報告事項」を聴取いたします。 初めに(1)、東急線ホームドアの設置","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"ホームドア設置済みの目黒線は、列車との接触事故が２０１３年度でゼロということですが、その前は大体どのぐらい事故があったということなのですか。","respondent":"中村都市計画課長","answer":"申しわけございません。過去の事故件数については、目黒線についてはちょっと今、情報を把握しておりません。ただ、ここ５年以内で事故ということは聞いておりません。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"本当は、接触事故がゼロですよというなら、その前はどのぐらいありましたというのが書いてあるのが親切ではないかと思います。これに対する費用負担はどうなっているのでしょうか。今後大井町線は、品川区内にほかの駅もありますけれども、これについて品川区は幾らか予算を払うということになっているのでしょうか。その辺をお聞きしたいと思います。","respondent":"中村都市計画課長","answer":"大井町線の大井町駅ですけれども、こちらは事業費としまして総事業費が１億５,２７０万６,０００円です。そしてそのうち区が補助をいたしましたのが５,０９０万円です。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"大変喜ばしいことだと思いますが、先ほどの質問にも関連するのですけれども、事業費としては、国、事業者、地元自治体ということで３分の１ずつになると。地元自治体のほうはそのうちの２分の１ということですけれども、これはバリアフリーの事業、例えばエレベーターの設置ですとか、そういったものについても同じスキームということなのでしょうか。","respondent":"中村都市計画課長","answer":"補助費としては同じ金額ということになります。ただ、上限額も決まっておりまして、今、助成では、品川区としては６,０００万円を上限と定めてあります。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これもちょっと関連になってしまうのですけれども、これは情報提供があったということで、ペーパーも東急のマークが入っているものですけれども、鉄道事業者とよく相談をされるということで、何か我々から質問をしたり、いろいろ要望を出していくとき、そういうご答弁をいただくのですけれども、現状では定期的な連絡協議会というか、そういったものをどのような形で開催されているのか。","respondent":"中村都市計画課長","answer":"今、ホームドアですとかあるいは点字誘導ブロックですとか、こういったものにつきましてはバリアフリー計画を品川区のほうで策定して、その中で協議をしていくということになってありますけれども、このホームドアの設置につきましても。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"働きかけが実ったというのはすばらしいと思います。これに関してだけではなくて、定期的な協議会というのは何か持っているのでしょうか。もしあるのであれば、教えてください。","respondent":"中村都市計画課長","answer":"定期的な協議会というのは特に持っておりません。","id":"exchange-005"}]},{"id":"topic-02","title":"中延二丁目旧同潤会地区にかかる「都市計画原案」","agenda":"中延二丁目旧同潤会地区にかかる「都市計画原案」","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"数字の見方を伺いたいのですけれど、４のその他の近隣住民の関係ですが、２日間で９００軒で、大体こんなものなのか、少ないのか、多いのか、この数字に対する評価というか考えを教えていただきたい。","respondent":"寺嶋木密整備担当課長","answer":"この９００軒ですけれども、この数字につきましては根拠がございまして、こういった説明会を開催するときには、敷地内に建築する建物の高さの２倍に当たる長さを、半径としたエリアを対象とするということが決められております。それで今回は９００軒が対象になったと。","id":"exchange-006"}]},{"id":"topic-03","title":"「木密地域不燃化１０年プロジェクト」不燃化特区の新規地区申請","agenda":"「木密地域不燃化１０年プロジェクト」不燃化特区の新規地区申請","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"資料２のところで、事業計画図のところで赤とピンクで囲ってある、一部欠落というか、切れているところ、ここは入らないということでいいのですか。そういう見方でいいのですね。お願いします。","respondent":"寺嶋木密整備担当課長","answer":"ご指摘のとおり、ちょっと変わった形の指定になっているように、途中が切れていたりとか、これはご参考までにご報告いたしますと、このエリアで都市防災不燃化促進事業という事業を導入することも合わせて予定しておりまして、そちらと地域割りを合わせたということ。","id":"exchange-007"}]},{"id":"topic-04","title":"東品川四丁目地区地区計画","agenda":"東品川四丁目地区地区計画","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"今回はＣ街区というところで居住機能を導入するということで、近くにイオンとか、楽天タワーとか企業がたくさんあって、住宅もＵＲの賃貸とかあるのですけれど、ここはどういうものが入ってくる予定なのか、また計画なのか、具体的なところがわかれば教えてください。","respondent":"溝口都市開発課長","answer":"Ｃ街区の今、開発事業者のほうで計画されている計画でいきますと、約８００戸程度の住宅と下層に店舗等を予定されています。さらに子育て支援施設等の導入を計画されていると聞いています。Ｃ街区としては以上のものを計画されていると聞いております。","id":"exchange-008"}]},{"id":"topic-05","title":"しながわ環境大賞・みどりの顕彰および環境講演会","agenda":"しながわ環境大賞・みどりの顕彰および環境講演会","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"しながわ環境大賞は３団体ということで、どのような取り組みをされているのか、具体的に教えてください。","respondent":"三ツ橋環境課長","answer":"昭和６４年からずっと長い間継続されてあります。山手通りの開発とともにごみのポイ捨てが問題になって、子どもたちの環境教育も含め、夏休みの親子清掃をされているところです。そして山中小学校と山中おやこクラブです。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"花壇の手入れなどいうのはなるほどなと思うのですけれど、親子の清掃活動など聞くと、それも確かに新しいのかな、ずっとそれもやられているということですけれども。これは地球環境基金を利用しての事業なのか、それとも一般事業としてやられているものなのか、ちょっと行財政改革特別委員会でも、基金が議論されているものですから、その辺ちょっと教えてください。","respondent":"三ツ橋環境課長","answer":"今回につきましては、受賞された３団体と６団体以外にも応募されたということで、今年度以降は応募された団体に対しても参加賞という形をとらせていただきまして、いろいろ顕彰について、環境課からありがとうございましたの気持ちを込めて、参加賞も考えております。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"地球温暖化防止、リサイクル活動、環境保全に関することということで目的に最初書いてあって、今のところ清掃であったり、屋上に菜園をつくったり、教育だったりということなのですけれど、これはもともと地球温暖化防止から始まったことだと僕は思うのですが、地球温暖化防止の目的がはっきりした取り組みというのは、近年大分トーンダウンしてしまっているやに感じるのですけれども、そこのところ今。","respondent":"三ツ橋環境課長","answer":"委員おっしゃるように、今この環境大賞というのは、清掃活動や緑を増やしていきましょうというものが多いことは事実上ありますけれども、特にこちらの沖ウィンテックという会社につきましては、電力および温度の見える化を行うなど。","id":"exchange-011"}]},{"id":"topic-06","title":"事業者向け防災ハンドブックの配布","agenda":"事業者向け防災ハンドブックの配布","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"拝見させていただきました。先ほど事業者向けということで企業の情報、ＢＣＰであるとかそういったことも前のほうに載せてあるということでしたけれども、そのほかの部分というのは、区民向けのハンドブックとほぼ変わらないのでしょうか。それが一つと。水害のところで、崖の対策等については何か入っているのでしょうか。","respondent":"鈴木防災課長","answer":"ただ４４ページをご覧いただきますと、区の水害対策の事業の中で、防水板の設置工事の部分で法人に対する助成があったりとか、そういう法人向けの資料、情報も集めまして、各章それから第６章の支援事業の一覧のところに記載しています。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"最後に１点だけ。これはいい内容のものですけれど、区内の事業者、協力団体とかいろいろなところにお配りになると思うのですが、例えば企業でこれを活用して、どういったことを想定されているのか、こちらからこういうものに使ってくださいとか、配りっ放しという言い方はあれですけれども、そこのところを教えてください。どういうふうにお話をされるのか。","respondent":"鈴木防災課長","answer":"今回配布いたしますこのハンドブックは、各事業所でも活用いただいて、従業員や社員の方にしっかりと意識を持って、組織全体で取り組んでいただけるようにというところが主眼ですので、先ほど申し上げましたように区のホームページでも。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/967161?Template=document&Id=4130#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":16371,"voices":70}},{"id":"h27-20150120-9","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"文教委員会","time":"午後 １時００分～午後 ２時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"の平成２７年度新入学の学校選択希望理由調査結果","agenda":"の平成２７年度新入学の学校選択希望理由調査結果","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"目的が、今後の学校運営の改善ということなのですけれども、第１位、小学校の「学校の教育活動に魅力がある」という理由、また、中学校でも第２位に入っておりますが、私としてはこの項目、少し幅広いのではと思うのですけれども、２６年度、２７年度、書いてありますが、まず第一に、何年度からアンケートをやっていらっしゃるのかをお聞きしたいのですけれども、お願いします。","respondent":"野呂瀬学務課長","answer":"方法を例えば、入学説明会でやったりとか、一番の理由に挙げたのはどれですかとかいろいろやっていたのですけれども、結構集計とか、親御さんのほうも迷うという形で、ここ数年は、学校選択の希望調査票を書くときに、一緒にどういう理由で選んだのかと。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。今後、この大きな１つの、今１位になっているところを、保護者の方がご負担にならないような形で、運営の改善という目的に合って、もう少し具体的にどう思われているのかをお聞きできたらいいのかなと思いますが、その辺はどのようにお考えでしょうか。","respondent":"野呂瀬学務課長","answer":"確かに魅力があるといいますと、本当に大ざっぱなことで、数字は、その中でも各学校がどういうことをやっているのかというのはなかなか難しいところなのですけれども、アンケートというのはこのアンケートだけでなくて、いろいろなところでアンケートをしております。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。では、いろいろなところでアンケートをやっているということで、もうちょっと具体的なこともわかっていらっしゃるのかと思いますが、最後に、今後同じように続けていくのかをお伺いしたいと思います。","respondent":"野呂瀬学務課長","answer":"このアンケートにつきましては、やはり毎年希望選択のときに続けていきたいと考えていますし、また、その結果を校長会等を通じて学校のほうにも周知して、今後の学校運営の一助にさせていただきたい、このように考えているところです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"これからこういう希望に対して、校長会等々というのはなかったか、どういうふうに現場のところの具体的な教育活動にフィードバックしていこうとするのか、そのあたりを伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"回答数ですけれども、３割程度というのはご指摘のとおりですけれども、大体３割の方が学校選択は希望していると。逆に言えば、７割の方は、学校選択は希望していないけれども、地元の学校というのですかね、学区域の学校を選んでいただいているという傾向のあらわれだと思います。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"品川区内では考えられないと思うのだけれども、通学時間が１時間以内でという具体的なところまで出てきているという点で、非常に小規模校が幾つか品川区内にも現実にあるわけで、そういう学校を選んでいる保護者もある中で、そういう財務省の考え方について、品川区はそれなりに小規模校も親の選択だというところでつかんでおられる、そこを統廃合していく方針というのはまだまだ明らかにしていないので。","respondent":"野呂瀬学務課長","answer":"結果的に、今、小規模校というか、単学級の学校もありますけれども、それがいわゆる学校の魅力を最大限やって、それは今の時点では、今年はそうだったけれども、来年は複数になるという可能性だって含んでいるわけですので、今現在として。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"小規模校は小規模校なりのよさがあるし、そういうよさを保護者が望んで、子どもさんと十分話し合いをして選択するという、そこのところは大事にしていただきたいということを改めて申し上げたいと思います。そこについて、そういう状況がいつの時点のことを、例えばどういうアンケートなり、その辺の具体的な裏づけの資料というのを紹介しておいていただきたいと。で、終わりたいと思います。","respondent":"野呂瀬学務課長","answer":"先ほど質問したところで、小規模校の支援につきましては、今後も継続してやっていきたいと考えています。それと、保護者アンケートですけれども、これにつきましては、文教委員会でも既にご報告していますけれども、保護者アンケートということで、毎年やっております。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"私がさっき言ったのと趣旨が違うのかなと思ったので確認なのですけれども、私どもがとったアンケートでは、学校選択についての是非というのかしら、是非について賛成、反対、わからないという３つの項目でとったら、３分しているということなのですね。そういうことで紹介をしたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須藤副委員長","kind":"質問","question":"１点だけ。いわゆる許容の範囲というのも当然出てくるのだろうし、パイの大きさによってね。そうすると、今、大体が３割がマックスの状態だよと。できたら、これが１.５割とか２割ぐらいにしていくほうがいいのか、いわゆる選択制をどんどん導入して、今言ったマックスの３割をしっかりとキープするような学校運営というか、そういう教育方針になっていらっしゃるのか、そのあたりを教えてください。","respondent":"野呂瀬学務課長","answer":"ちなみに、学校選択をしていない他の市町村、学校選択をやっていなくても、いわゆる指定校変更制度というのがございまして、「ここの学校に指定されたけれどもそこには行きたくなくてここに行く」というのですと、学校選択をしていなくても。","id":"exchange-008"},{"speaker":"須藤副委員長","kind":"質問","question":"ですから、まず学区内のほうを先にして、あとは抽選ですというやり方になってきてしまうよね。では、一体校は６校しかもう区はつくりません、それ以上大きくはしていかないと思います、そうすると、どうしてもその辺の差というのが、まちの人たちが見てくると、そういうところへ行きたいですよ、流れていきますよというふうになってきてしまう。","respondent":"田村教育次長","answer":"だから、一律３割がいいとか４割がいいとか、率では申し上げられませんけれども、その課題を教育委員会と学校がともに解決するような努力をしながら学校選択を継続するという動きが必要なのかと、そういうふうに考えております。","id":"exchange-009"},{"speaker":"須藤副委員長","kind":"質問","question":"順番が１８から頭になっているので、何でこういう順番に。普通は１から書いてくれるとわかりやすいと思うのだけれども、何でかなというのが１つ。それから、何回も、例えば、荏原平塚学園は３回、ここへ上がってきていますよね。それから、鈴ヶ森小学校も２回上がってきていると。それで、予防をやるよというお話だけれども、学校ではどういうことをやられているのか、教えてください。","respondent":"野呂瀬学務課長","answer":"すみません、この資料の様式は、本当にこちらの統計上のあれで、いわゆる直近が一番わかりやすいというような形でだんだん積み上げていくというものですので、１番からなっています。見づらいのですけれども、逆に、見なれてしまうとこっちのほうが見やすいかなと。","id":"exchange-010"},{"speaker":"須藤副委員長","kind":"質問","question":"順番だけれども、見なれてしまえばこのほうがいいというけれども、保育園のほうは早く来た順に並んでいるので、逆に我々は見やすいと思うので、それは、僕ら素人がぱっと見たときにどっちが見やすいかというのは、僕らが見るものなので、１番から来てどうだよというのが普通の出し方だと思うのだけれども、まずそのあたりのお考えを教えてください。その辺が、クラスが３年１組とか２組とかとなっていて。","respondent":"野呂瀬学務課長","answer":"それと、申し訳ございません、伊藤学園、確かにこういう名称では言われていませんので、これは３年……。ミスプリントだと思います。調べします。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"それで、ずっと期間を見てみると、大体３日から４日の期間なのですけれども、そのあたりというのは校医さんとかあるいは保健の先生等々、関係の方々の意見を付して、そしてこういうふうに日程を設定されるのかなと思うのですが、そのあたりのことを教えていただきたいのと、あと、その日については、例えば、この１９日は発症はしていないけれども。","respondent":"野呂瀬学務課長","answer":"これは目安ですけれども、大体２割がお休みになったら、学級閉鎖も検討する。もちろん学校医の判断とかいうのもあるのですけれども、そうしますと、８名ですので、８名のうちに報告、いわゆるＡ型のインフルエンザだったのが４名いたと。","id":"exchange-012"}]},{"id":"topic-02","title":"の寡婦・寡夫控除のみなし適用","agenda":"の寡婦・寡夫控除のみなし適用","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"２点ありまして、１点目は、我が会派からもこの件については強く要望してきたという経緯があり、非常に歓迎はするのですが、今までなかなか区のほうは、これは行わないというような方針をとっていたと思うのですが、なぜ今回この適用をするようになったのかというのを１点お聞かせいただきたいのと、もう１点は、対象人数が５０人と記載されていて、これは、対象範囲のところで。","respondent":"竹田保育課長","answer":"なぜ今の時期かということなのですが、２点ございまして、１点目が、ちょっとさかのぼりますが、平成２１年に、未婚の母から日本の弁護士会に人権救済の申し出がなされまして、その内容は、未婚の母が寡婦控除を適用されないことによって著しい不利益を受けているというもので。","id":"exchange-013"}]},{"id":"topic-03","title":"の「品川区子ども・子育て計画（素案）」に対するパブリックコメントの実施結果","agenda":"の「品川区子ども・子育て計画（素案）」に対するパブリックコメントの実施結果","exchanges":[{"speaker":"南委員","kind":"質問","question":"全体で意見としては２４件だという話なのですけれども、この数について区としては多いというふうに認識、予想より多かったあるいは少なかった、どういうふうに捉えているのかを伺いたいと思います。そこから伺いたいと思います。よろしくお願いします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"パブリックコメントにつきましては、これまでも区民説明会等でもご説明してきましたので、十分周知がされた上でのことだと考えております。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"３週間とはいっても、周知そのものがもっと事前に行われて、パブリックコメントは１１月１日から始まるにしても、周知はもっと前にやるべきだと思うのですけれども、そういうこともあって少ないのかなと思ったのですけれども、その辺の見解を伺いたいと思います。この３週間と設定したところを、どういうふうな検討結果で３週間になったのか、それを伺いたいと思います。そんな時間はないし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"８番目の、保育の質を確保するための保育士の待遇改善って、そうだというふうに思いますけれども、この意見は意見としてすごく理解できるのだけれども、区の回答として、３行目の冒頭に「送迎バス等」と出ているのだけれども、この方のご意見では、送迎バスということは、そういう言葉がないけれども、これが出ているから、非常に飛んでしまっているのかなと。","respondent":"今井制度改革・待機児童対策担当課長","answer":"３点目の保育の質の確保のところですが、この方のご意見は、目的が確保するためであって、内容として徹底的な調査のもと適切な施設整備計画が必要という後に、地域を限定しない、地域をよく確認した新規施設の開設ですとか、区や都の所有地の活用ですとか。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"特別支援のところについては障害者福祉課のほうにという話なので、必要な問題については全庁的に伝えていくという状況で捉えているというふうに確認できるのかなと思っているので、ぜひそれはそれとして大事なことですから、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-04","title":"の認証保育所の新規開設","agenda":"の認証保育所の新規開設","exchanges":[{"speaker":"南委員","kind":"質問","question":"この認証保育園なのですけれども、例えば、給食だとかはどんな形で提供される、そのあたりを教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"給食設備につきましては、これは小規模とは違いますので、０歳児からですので、離乳食から、認可保育園と同様に提供しています。","id":"exchange-018"},{"speaker":"高橋委員","kind":"意見","question":"設置者について、他にも保育所等の運営といいますか、をしているのかどうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"平成２６年度から台東区で小規模保育施設を行っておりまして、また、私どもでも小規模保育の事業のほうを開設する予定です。ですので、これまで認可保育園や認証保育所の経験、実績はございません。","id":"exchange-019"},{"speaker":"高橋委員","kind":"質問","question":"事業所内と小規模ということですね。区内でも小規模の予定ということは、これは予定ということなので、平成２７年度の予定ということでよろしいでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"１２月１６日の新規開設におきまして、小規模保育施設という形で２施設開設するということでご報告申し上げましたが、南大井に小規模保育施設、１５人として開設するウィズブック保育園大森海岸が同事業者による設置です。","id":"exchange-020"},{"speaker":"須藤副委員長","kind":"意見","question":"１点だけ。内訳が０から２歳が３０人定員、３歳以降が１０人というのだけれども、０、２歳の３０人が年が上がってくると、その先はどうなってしまうのかなという思いがある。上が１０人しかいないというと、そのあたりはどういうふうにしていただけるのかなと。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ご案内のとおり、認証保育所は東京都の独自施策ということで、やはり待機児童が多い０から２歳の開設のところを中心に設置されているものです。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"ウィズブック、これ、０から２歳が３０人なのですが、年齢ごとの人数がもしわかれば教えていただきたいのが１つと、あと、株式会社アイ・エス・シーって、先ほどのご答弁でも、南大井で小規模保育を実施するのですけれども、あそこの場所を地図上で見て、近くだったので何回か通ったりして確認したのですけれども、今準備が進められて、室内の工事が進められているようですけれども、隣が私立の幼稚園で。","respondent":"今井制度改革・待機児童対策担当課長","answer":"０、１、２歳の内訳ですが、今、私ども、認証保育所につきましては、大体見込みですが、現在まだ申請中のところですが、０歳が６人、１歳が１２人、２歳が１２人ということを予定しております。","id":"exchange-022"}]},{"id":"topic-05","title":"の２のその他","agenda":"の２のその他","exchanges":[{"speaker":"南委員","kind":"確認","question":"そういうことで、どういう対策がいいのかはしっかりと教育委員会としても検証して、とっていただけるようにお願いしておきたいと思います。１つ聞きたいのは、５月２４日の５時間目ということなのですが、この事件が発生したのがわかったのは誰からか、どういうルートでなのかというのが、私、聞き漏らしたのかわからないのですけれども、確認をしたいと思います。","respondent":"渋谷指導課長","answer":"これは校長のほうから教育委員会のほうに電話の一報があって、事案が発覚したです。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"そうしたら、先生が何回かＴシャツをつかんだりドアに押しつけたりいろいろやっている最中に、別の子どもさんたちが校長室に飛んでいったという形なのですかね。そこの状況はわかりました。","respondent":"渋谷指導課長","answer":"再三再四、この教員のほうについては、指導方法として、こういった体罰というもの、力を行使することはいけないということを徹底していくことを繰り返し繰り返しやらざるを得ないのかなというところを感じるところです。","id":"exchange-024"},{"speaker":"須藤副委員長","kind":"質問","question":"体罰は当然よくないのだけれども、そうやって入ってはいけないよというところへ入ってしまうような子どもたちに対して、教員はどうすればいいのでしょうか。その子が言う事を聞かないよという場合、どういうことを指導して、どういうふうに育てていくのか。保育園大丈夫なら大丈夫だよと言ってくれればそれでいいし。","respondent":"渋谷指導課長、竹田保育課長","answer":"一般的に、今委員がご指摘になったように、体育会系イコール体罰ということの認識では全くございませんので、ここは訂正してお詫びを申し上げます。そういったことから、そういった事故等はないものと認識しております。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"だから、先ほどの全体の中で、大枠の流れだったのであれだったのですが、校長室に駆け込んでくれた子だとか、また、該当するクラスだとか、学年対応、どんな形で児童に対するケアというのでしょうか、一生懸命、児童・生徒たちは取り組んでいこうということで各学校で工夫をされている中でも、こういう案件というのは非常に悲しい出来事なのかなと思うので、その辺のケア、お伝えできる範疇で結構なので。","respondent":"渋谷指導課長","answer":"これは子どもたちがこのことによってかなりショックを受けたり傷ついたりだとかということもございましたので、スクールカウンセラー等々により一人ひとりのケアをするとともに、クラス全体でそういった暴力はいけないとかということをしっかりと。","id":"exchange-026"},{"speaker":"高橋委員","kind":"意見","question":"今、ケアのことが出たのですけれども、卒業がということなので、今お話があったように、さらに一層、６年生最後の数カ月ですので、児童に対するケアのほうをお願いしたいのと、それからあと、保護者の方々にどのような形で説明がされたのか、それともそういうのは個別対応だったのかということ。仮にこれからだとすると、どうされるのかということをお尋ねしたい。","respondent":"渋谷指導課長","answer":"土曜、日曜、また、冬季休業期間中も実質の期間に含まれますので、実質学校に、授業に来られない期間は１２日間ということで、その間は講師の対応、また、副校長が学級担任として入るということでご理解いただいているところです。","id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"去年の末、１２月２６日までが第１次募集の締め切りだったのですけれども、今年になって、今日は２０日ですから２週間ぐらいたっているので、１２月２６日の締め切りで何人ぐらい申請をしたのか、その実数、そして、昨年度と比べて大体どういう状況になっているのかというあたりを知りたいと思っているのですが、ぜひその辺を教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"昨年の１０月時点での数値というのは新規申し込みではございませんで、継続して毎月毎月申し込んでいる数です。今委員ご質問の件数は、１２月から初めて新規に申し込んだ数ですので、現在書類等の審査をしておりますので、具体的な数は現在のところは申し上げかねるところです。","id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"書類等の審査をするのは当然で、これから行われる審査会にかけるわけですから、そのチェックは今すごく時間をかけて大変な作業があるのだろうなと思うのですけれども、具体的に何人申請されたのか、１次募集で申請した方が何人いるかという実数というのは、一番最後の１桁まで言っていただかなくてもいいのですが、去年と比べてどんな状況だったのかというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"委員長の後ほどというのは、いつごろのことを想定しておっしゃるのですか。私は、だから、例えば、次回の委員会のときにはその数は出してもらえるようにしましょうとか、そういうふうに思っておっしゃるのだったらそれはそれとして伺ってもいいかなと思うのですけれども、この委員会としての責任の問題ですよね。保育園の待機児が出るのか出ないのか。ですから聞きたいし、掌握する必要があると思うのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"それは私の思いであって、この委員会の責任として聞いておきたいという部分があると思うのですよ。ないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"須藤副委員長","kind":"意見","question":"今、正副の副が出たので、今初めて言われたので、担当課長が答弁したように、出せる時期が来たらまた出してもらうということで整理していかないと、いつまでぴったりとかというのはなかなか難しいと思うので、ご意見としては正副でまた話をして、調整をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"副委員長もそういうふうにおっしゃったのだけれども、出せる時期というのは、いつだったら出せるのか、そこは質問したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"こちら、入園の１次の選考の発表というのは２月１９日を予定しておりますので、２月１９日に選考が終わって、結果発表もありますけれども、その時期になれば私どももきちんと、もちろん確定しておりますので、その日以降、またご報告の機会を設けたいと思います。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"それともう一つ、私は別にそんな先にならなくたって、これだけの人が入れましたとか、そういうことを今求めているのではなくて、これだけの方が申請を出しましたという、その数字を知りたいということなので、２月１９日の発表後だったら出せるというところには全然すごく違和感を感じるのですよね。何でそこまでして今出せないのか。なぜ出せないのかということをしっかり説明してください。","respondent":"こんの委員長","answer":"要求できない委員会ではございません。きちんと受けていますので、どうぞこの辺はご理解いただいて、きちんとご報告できる時をつくりますので、よろしくお願いしたいと思います。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひそれはそれとしてやっていただきたいです。委員からの要請があってもしていただきたいと思います。さっきは、中身を具体的に精査しているから出せないとおっしゃったけれども、数字の問題と一人ひとりの要望の中身、申請の中身は全然リンクしないじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"しないです。数字が、何人申し込んだのか最終的な数を今つかんでいないというならともかく、つかんでいないなんていうことはあり得ないのですから、締め切ってから何週間もたっているので。それで出せないというのは理解できません。納得できないから、そこを納得できるようにちゃんと説明してください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"それはなぜかというと、やはり途中で、辞退も含めたそういうふうな数値がきちっとしたものを逆にお出ししていなかったことを私も十分反省しております。ですので、私としましては、きちんと数字が確定した段階でお出しするのが一番的確な情報の開示だと考えています。","id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"書類不備ということも１つの理由に挙げられましたけれども、では、書類不備は受領したことにはならないのですか。申請を受けたことにはならないのですか。そこを改めて知りたいです。","respondent":"今井制度改革・待機児童対策担当課長","answer":"ですので、１次選考の中でも、まだそういう意味では最終的な確定数ではございませんけれども、選考の際の数ということで一定の期限を区切ってお知らせすることができると考えていますので、１次選考の確定の後に数値のほうはご報告させていただきたいと考えています。","id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"答弁が違うのですよね、求めていることと。１２月２６日時点の申請した数を教えてくれと言っているのです。申請したときに、受付窓口のところで職員の方が一人ひとり対応して、そして、このケースについては一人ひとり確認した、書類がそろっていますねと、大抵そういうふうにして受領するわけでしょう。そこを、考え方を教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"南委員","kind":"確認","question":"でも、それはそれなのですよ。１次と２次の申請数、待機児数がこのくらい出るよという数字が紹介されるわけですから、それはそれでしっかりこの委員会でもみんなで確認をしていけるからいいと思っているのだけれども、私が聞いているのはその数字ではなくて、その前の段階のことというのは理解していただけていますよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"個別に聞いているのです。正式に聞けば教えていただけるのかなと思って、その他で質問させていただいたの。聞いているの。１２月２６日時点の数字を教えてくれと言っているのに、１次と２次のがはっきり出てから言いますと。そういう２次のところまで求めていないのですよ。１次の数を求めているのに何で答弁してくれないのですか。何で答弁できないのですか。では、窓口の人たちの仕事が不十分なのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"須藤副委員長","kind":"質問・要望","question":"議事進行について。一応、閉会をしてもらって、今お話があったように、あとは個でやってもらって、委員会としては、先ほど来お願いをしたのは、そのとおりのこともお願いしてありますので、その結果はまたしかるべきときに数字を出してもらうということで終わっています。委員の皆さん、みんなそういうことで、あとは個でやってくれないかということで、議事進行で閉会を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"須藤副委員長","kind":"提案","question":"私、提案した。議事進行、諮ってくれよ。それで終わるんだよ。私、議事進行の提案をしたのだから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"南委員","kind":"提案","question":"おかしいです。しかも副委員長からそんなふうな提案するなんて、冗談じゃないです。区民に責任持てないではないですか。皆さんだって待機児解消、主張しているでしょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"知っていることなのだからいいではないですか。おかしいです、そういう運営は。言っておきます。知らない数字を求めているのではないのだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/111718?Template=document&Id=4846#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":36488,"voices":124}},{"id":"h27-20150120-5","meetingId":"h27-cm01","date":"2015年1月20日","dateIso":"2015-01-20","committee":"総務委員会","time":"午後 １時００分～午後 ４時０５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"１点、国民健康保険のほうでお伺いしたいのですけれども、資格喪失して、多分社会保険になったとかの残債というか、その分を払ってくださいというのを払わないでそのまま債権放棄をする形になったと思うのですけれども、社会保険にかわるときに多分データとかというのはみんなつながっているので、何かしらどこかでエラーとかが出て。","respondent":"久保田会計管理者","answer":"細かくはちょっと説明できないのですけれども、聞いているところによると、社会保険とそれから国民健康保険とこの辺の、はっきり言うと情報の流通というのですか、交換というのが現在はほとんど行われていないという状況らしいです。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"だから、そういうのも、例えば国民健康保険のほうの窓口、どういう周知の仕方かは別にしても、何かしらきちんとした手続をしてくださいというのを仕組みの中でぜひ考えていただいて、全部で４５万円なのか、金額的にどうなのかという話ですけれども、ただ貴重な、多分本来納めるべきお金だと思いますので、しっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと伺いたいのですけれども、まず、債権放棄の報告というのは、条例だったり、どこかの項目だったり、それに基づいて区議会に報告するという性格のものなのか。","respondent":"久保田会計管理者","answer":"なおかつこれ以上回収を投げかけても、おそらくできないだろうというようなことで債権放棄をすると、こういう流れになってあります。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"幾つか質問いたします。多分就労についてなかなかできないというのであれば、就労支援という形で手を打っているのかどうか。もう１点は、放棄した日というふうにありますけれども、債権が発生した日がまちまちで、放棄した日というのは、平成２６年の中で放棄するという形で決められているのですけれども、これは何か決め事があるのでしょうか、教えてください。","respondent":"久保田会計管理者","answer":"これはケース・バイ・ケースですけれども、中にはご病気で今のところ就職できないという方もいらっしゃいますし、それから当然ながら、ご本人以外に連帯保証人を２人つけることが原則ですので、本人に返済能力がなければ当然連帯保証人にその責任は行くわけで。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問・要望","question":"それぞれ状況を確認されているということではあるのですが、貸付をするということは、もともと生活困窮者だと思うのです。今の生活の状況を踏まえて、それに対応していくという形に変更していく一つの大きな理由づけになると思うのですが、その辺の見直し等々についてはいかがでしょうか。","respondent":"久保田会計管理者","answer":"部同士の連携については、それぞれの所管が、例えば生活保護でしたら生活福祉課との連携とか、あるいは若者就職支援ですと生活福祉課もそういうことを手がけている事業がありますし、ものづくり・経営支援課でやっている事業もあります。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういう形の中で一つお伺いしたいのは、今銀行なんかも一つの売りにしているのは、教育ローンとか、あれも５００万円ぐらいまではお金を貸すわけで、最終的にそれが個人に返ってきて、個人が大変だというのもあるわけなのだけれども、そう考えると、奨学金そのものがどこまでこれがどういう扱いをしていったほうがいいのかというのが、私はちょっと意味合いが変わってくるのだろうと思っていて、公立は。","respondent":"久保田会計管理者","answer":"どういう方法が一番いいのかというのは、所管のほうでも随分これから考えて検討することだと思いますので、その点についてご意見があったということは十分伝えていきたいというふうに思います。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"私も今石田委員がおっしゃったとおり、やはり何とかして今の垣根ですか、国民健康保険と社会保険の、それは区役所として訴えていくべきではないか。品川区としても、上のほうに、国のほうに上申してほしいと思います。大変だと思うのですが、またこういう状況なので、助けてやれる人は助けてやっていただきたいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後の動きも伺いたいと思います。それと、もう一つなのですけれども、総務部に危機管理担当部長がつくのと、防災まちづくり部に災害対策担当部長がつくということですけれども、何がどう変わるのか、実際の動きの中でどういうふうな役割として位置づけられるのか、新しい部長なので、ちょっと部と部長の関係がよくわからないので、そこをご説明いただきたい。","respondent":"柏原行財政改革担当課長","answer":"何点かご質問いただきました。課の仕事の中身といいますか、その分担の部分であろうかと思います。最終的にはまだ検討の途中ですが、今詰めの段階で確定させていただきたい。このタイミングで確定させていきたいというものでお示しをさせていただいたものです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"若者のところで、商業・ものづくり課ということですけれども、政府のほうが進めているいわゆる若者関係は内閣府に置いてあって、いわゆる横断的な事業になるので、その意味で内閣府に置いてあるのだと私は伺いました。そこをご説明いただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"何点がご質問いただきました。若者の就業支援の部分です。品川区におきましては、これまでも就業支援ということで、中小企業の支援の一つの形として就業支援というものがその中で出てきたですので、これまでの流れがあります。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問","question":"商業・観光課、ものづくり・経営支援課が今度改正されて、商業・ものづくり課、産業政策調整担当課長という形で振り分けられているように見えるのですけれども、産業政策調整担当課長はもともと現行では経営支援課の部分の業務をという形でよろしいのでしょうか。ちょっと詳細を教えていただけたらと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、商業・ものづくり課という一つの課ということで、全体を総括する課長がおりまして、その中から例えば産業活性化であるとか、就業支援・企業支援、こういったところを主に担うことになるという想定で今考えております。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"教えてください。総務部と防災まちづくり部、これは現在いろいろな課が、あと課長とあるのですが、これは引き続きこの中に入るという認識でよろしいのでしょうか。行財政改革というのは非常に大切な項目だと思うのですが、そこをどういうふうに割り振って、企画というものの中にはいっぱいあるのだろうと思うのですが、改革という意味で言うと、誰がやる、どこがやるのでしょうか。","respondent":"柏原行財政改革担当課長","answer":"総務部と防災まちづくり部の課が、ちょっと表現の仕方がこういう形になってしまって大変申しわけなかったのですが、課の構成は今までと変わらないという状況です。それから危機管理の部分、私の説明がちょっと足りなかったところがありまして申しわけございませんでした。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"それでいいのですか。いろいろなところで改革が必要なので、どこの部署においても改革していかなければいけないというのはありますが、やはり担当課として行財政改革という、担当課長でもいいですけれども、それをきちんとした位置づけにするというのは、品川区の姿勢という中でも示すべきなのではなかろうかと思うのですが、その辺のお考えはいかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"ちょっときちんとしたお答えになっているかどうかあれですが、基本的に行財政改革が後ろ向きではないということだけは、ご理解いただきたいと思います。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"企画調整課、今は一緒だったという部分もあって、当然企画をする上では財政的なものの相談はやりやすかった部分もあると思うのですが、ただやはり改革という名前がつくと、つかないでは、確かに皆様の意識的に言うとかなり前進したという感じなのでしょうけれども、成果があったということは理解するところでもありますし、評価をするところですけれども、これからも改革ですから何年後、先々を見て。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つかお伺いします。だから、それでいいのかどうかという感覚を教えていただきたい。そうなると、企画調整、調整とかいうと、あまりこういうのをつけると、そこまで入るの、それはまた違うでしょう、それは福祉部の話になってしまうでしょうとか、いろいろ話が入り組んできてしまうのではないか、そこら辺の整理はどうやってお考えなのかというのを教えていただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"昔は企画課ということで、企画の体制でおったのですが、それが企画財政課なり、今回企画の調整ということで、先ほどもちょっと議論になりましたけれども、全庁的な調整の部分というのはかなり大きいウエートが出てくるということで。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"それは企画調整という名前があるならば、今度部制にするのであるならば、そこら辺はしっかり把握をする、企画調整は大変だと先ほど言ったように大変なのだろうと思っていて、それが部の私はいいところだと思っているので、事業部とは今度違うわけで、部になったわけですから、私はそこら辺の企画部というところの力量が非常に問われると思っていまして、そこら辺のところはぜひ踏まえて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"いながわ委員","kind":"質問・要望","question":"何点かお伺いしたいのですけれども、まずこの品川区議会議員選挙執行計画というのは、おそらくここに内容が１６項目記されているのは既に決まっている、事前説明のときにこういった内容は全部入っているということでいいのか。","respondent":"工藤選挙管理委員会事務局長","answer":"こちらのほうは、計画では２０日から２４日までという形になってありますけれども、今私どもが予定しておりますのは、１９日（日）午後５時３０分が締め切りです。それで、こちらのほうは締め切りを受けまして、その夜に印刷業者に手渡しするような形になります。","id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"昔はたしか土曜日、前の投票であって、本来は日曜日だけが投票日だったのを、どんどん広げていって期日前投票ということで公示日の次の日から、それがすごくよくなって、それはある意味投票率が上がる部分だと思うのですけれども、でも中には、この人だと決めて行く人もいれば、公報を見て決める人もいるのは確かにいらっしゃると思うので、そういった部分を考えたら、一方では利便性がよくなりつつも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"本当に公報の点だけ。遅い、遅いという話が毎回言われている。宅配なら必ず人数を集めてでも何でも、統一地方選挙だから人数が集まりませんというのかどうかわからないけれども、事前に頼んでおけば、例えば２０日に全部配ってください、今のバイク便ではないけれども、バイク便は手配をされたということだろうから今みたいにバイク便でそこへ届けられますとおっしゃっているのだと思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"私もたまたま通りかかったのですけれども、初めに何の車かと思って近づいたら、選挙管理委員会の車だったと思うぐらい、もうちょっと物には限度というものがありますけれども、そこも工夫が必要なのではないのかと思うのですけれども、いろいろご意見が選挙管理委員会にも上がっていると思うので、いろいろ工夫をしていただきたいと思ったので述べたのですけれども、それぞれいかがでしょうか。","respondent":"工藤選挙管理委員会事務局長","answer":"それで、先ほど石田委員からいろいろなお話、意見をいただいておりますので、やはり１日でも早く届けるというのが基本だろうと考えていますので、この件につきましては、いろいろと検討していきたいというふうに思っておりますけれども。","id":"exchange-019"},{"speaker":"西本委員","kind":"確認","question":"確認です。１０番と１１番、くじを引くということですが、これは選挙管理委員会のほうで決めたのですか、ちょっと忘れてしまったので教えてください。何か方法はありますか。","respondent":"工藤選挙管理委員会事務局長","answer":"２点目の選挙公報についてのマンション等への配布ですけれども、一番今私どもも対応に苦慮していることは、なかなか管理人のほうで、「入れるな」という話がございまして、トラブルになっているケースがあります。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問","question":"非常に難しいと思うのです。公報は当然告知が必要なわけであって、もちろん要らないという人もいらっしゃるかもしれないのですが、やはり見ていただくためには何かしらの方法、かなり、結構強めに言っていいのではないかと思うのですけれども、強めに言って結果があったものとか、効果があるのかないのか、よくご苦労されているのはよくわかるのですけれども、成果なんかはいかがですか。","respondent":"工藤選挙管理委員会事務局長","answer":"ただ、結果的にそれで１００％という形、やはり必ず選挙がありますと二、三のマンションで交渉してもなかなか難しかったということがあることは事実です。","id":"exchange-021"}]},{"id":"topic-02","title":"の２、所管事務調査","agenda":"の２、所管事務調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"何点かお伺いしたいのですけれども、まず１番目の区民から見た品川区の魅力というのは、区民インタビュー、９名の方のお話をこれに、ちょっと聞き漏らしてしまったのですけれども、それでよろしいのかどうなのかという部分は後であれなのですけれども、私は何がショックかというと、私たちの会派、各会派、いろいろな団体から意見交換とか要望を毎年１回お受けしているのですけれども、必ず入ってくるのは。","respondent":"荒井広報広聴課長","answer":"接合点という、確かに非常になじみにくい言葉と先ほど説明の中でも申し上げたところですが、この言葉も含めてコンセプトをどういう言葉として使っていくかというところは検討を進めていくところですので、ぜひご意見をいただけたらというふうに考えているところです。","id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問・要望","question":"八つ、例えば先ほど言った運河の関係、船だまりがあるとかというイメージがもしここから欠落していると、まさにこっち側の８個の魅力的なところからある意味抜け落ちているわけではないですか。この中に水辺というのが１個も入っていないわけです。今後品川区はこういう魅力をつくっていこうと、そういうのも含めてシティプロモーションをつくっていただきたいと思うのですが、どうでしょうか。","respondent":"荒井広報広聴課長","answer":"水辺の事業ですが、今後具体的な事業を進めていくときにはもちろん出てくる事業の一つだというふうに考えているところですが、その魅力の中でどういうふうに読み取るかというのは、少しまた研究させていただきたいと思います。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問","question":"プロが多分、プロというか、広告代理店が入ったとしても、最終的に費用を払うのは品川区側ですから、広告代理店にこういう形で動いてくださいとか、しっかり伝えないと多分広告代理店は品川区に言われたとおりつくりましたで終わってしまうと思うのです。広告代理店は多分発想はすごくあると思うのですけれども、でもその発想と品川区は違うから、ではそれは出さないでおこうという話で終わってしまう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問","question":"私はこれをいただいて、本当にがっかりした１人です。お聞きしたいのは、誰がこれをまずまとめたのか。例えば水族館ならインターネットで見ようが、何しようが、水族館があるから来てみよう、そういう例えば観光の部分がまず訪れてもらえる、それから住んでみたいと思ってもらえる、あとは居住している方、誰が誰のためにこれをつくったのですかというのをまず聞きたい。","respondent":"荒井広報広聴課長","answer":"訪れてよし、住んでよし、働いてよし、学んでよしの品川区をつくっていきたい、そういったような考え方でやっているところです。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"仕掛けというのは、必ず必要だと思っています。これはアンケートでも必ず出ているではないですか。海外へ向かって出すのか、観光客に向かって出すのか、それは住んでみたいと思ってもらう方々に出すのか、住んでみたいと思っている人だったら、交通の利便性を出してみれば、５００ｍ以内に駅がありますとか、事実として出せることというのはいっぱいあるではないですか。何か反対があれば、意見を求めます。","respondent":"桑村副区長","answer":"ただ、このことの打ち出し方というのは非常に難しいということと、これは２３区、ほかの区でも相当そういうことを打ち出せる。","id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問","question":"それを、その方向を一つにしたら、ある程度観光はこうするのだ、住みやすさはこうなのだ、それは変な話、子育てするなら品川区と言われたっていいわけではないですか。それは江戸川区がちょっと失敗したという政策はあるけれども、あれは超有名になったではないですか。それが失敗したという例もあるけれども、イメージづくりとかで成功している例だってあるわけではないですか。私はやり変えるべきだと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"商店街というのは、シャッター通りがどうのこうの、確かに特徴のある商店街はいっぱいあるし、それぞれ頑張っておられるのはわかるのですけれども、今苦しんでいる方がいっぱいいらして、どうするのだということをお話しする中で、だからこそ地域資源だから頑張ろうというふうに捉えるべきなのだろうけれども、これももうちょっと深いところでの分析が必要ではないか。","respondent":"荒井広報広聴課長","answer":"「人と人の接合点」という言葉なのですけれども、先ほどご説明させていただきましたように、幾つかの言葉の中から新たにつくり上げた言葉でございまして、広告代理店の方、委託した事業者が品川区のさまざまな魅力をそれぞれまじわる、あるいは交差点といいますか。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"魅力が全部だということで絞れない。広告代理店が出してきたものは、もうちょっと調べてほしい、品川区の魅力をもっと引き出してもらえるような調査をかけていただきたい。２３区でもいいです。ここはこういう特徴があって、品川区はそれに比べるとこういう特徴がありますというふうに言っていただくと非常にわかりやすいと思いますので、今後の検討の参考にしていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際、現在人口も増えている。これからどうやってつくるのかあれですけれども、どうなるのかあれですけれども、進めた以上やっていただきたいと思います。例えば、我々が審議したら、これはおかしいのではないか、こんなことを考えているのかどうなのかと。今後について、これからまとめていくのは大変だと思うのですが、あせらずにやって、ゆっくりやっていただきたいと思います。意見だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"いながわ委員","kind":"質問・要望","question":"いろいろお伺いしたいのですけれども、先ほど申し上げたことと、今須貝委員が言ったように、これを出すのが早かったのではないかという話がありました。それはわからないですけれども。ましてや、１０万ｔ以上の船は今度青海に新しいふ頭をつくって接岸するわけですから、そうなってくると、人の流れとかまた運河の利用とかというのは、本当に膨らんでくると思うので、海をばっさり切らないでもらいたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"これにかかわって伺いますけれども、品川区の魅力をどこにつなげるのかがなぜ不明確なのか。視察に行ってきてわかりましたけれども、やはりこうしたい、ああしたいというのがまずあって、例えば売りたいでも、訪れてほしいでも、それをどうセッティングしたらいいのか、いろいろなアイデアはあるわけだけれども、品川区の魅力をどこにつなげるのかがなぜ不明確なのか、そこを伺いたいと思います。","respondent":"荒井広報広聴課長","answer":"いろいろなご意見をいただいたところですが、確かに皆様のご意見の中にあったように、非常に総花的になってしまっているというのが一つあるかというふうに感じているところです。品川区の魅力をどこにというのは、少し絞り込んだ形を今後考えていきたいと考えています。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"セッティングの仕方はいろいろアイデア、これは柔軟にやるのは私はいいと思うのです。ということは、都市間競争に勝つ、定住化を図るというのは一体どういう意味なのか、ここを狙いにして、ここにつなげたいと思っているのは一体何なのか、そこを伺いたいと思います。都市間競争に勝つ、定住化を図るというのは一体どういう意味なのか、ここにつなげて何が生まれるのか、そこを伺いたいと思います。","respondent":"桑村副区長","answer":"そういう意味では、本日こういう形でお話を聞けるというのはいいことだと思うし、先ほどの答えとすれば、私とすれば、都市間競争というのは自治体としてあるべき姿を追求するという意味で言っているので、それが目的ですということです。","id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"人のいない自治体はないですから、人が暮らして育んで、商売も子育ても、そういう自治体でなければいけないわけですけれども、一方で、ではどれぐらいの人口がいいのか、これはなかなか私自身もわからないことです。そういう意味では、まずシティプロモーションの取り組む未来やコンセプトからしっかり見直して、必要なことをまず整理するところからではないかと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっといろいろ気づいたところがありまして、お聞かせいただきたいのですけれども、まず一つ目が、「人と人の接合点」というコンセプトが出てきたということだったのですが、ほかにはどのような案が出たのか、ちょっとほかの案も聞かせていただけたらと思います。そちらからお願いいたします。","respondent":"荒井広報広聴課長","answer":"「人と人の接合点」というのが最終的に出された。区と業者の間でこれにしようと決めた案ですので、ほかの案については、検討の過程で削除していったというか、ここにまとめ上げてきたということです。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問","question":"実は、コンセプトですと、キャッチコピーは、多分いろいろな案とか、ブレインストーミングなどそういった過程を踏んでいただいているかと思うのですけれども、そうした中の、それこそ今削っていただいたところから融合したりとか、そこにいい言葉が隠れていたりするのではないかと思ったので、幾つかお聞かせいただけたらという意図がありまして、ちょっと質問させていただいたのですけれども。","respondent":"荒井広報広聴課長","answer":"できるだけ年度内を目指して戦略プランの策定を行うというのが現在のところの考え方です。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"意見","question":"私が先ほど言ったことに対して副区長からお答えはしていただいたので、都市間競争に勝つ、定住化の促進で結構なので、本当に一つは訪れてもらえる人、それから住んでみたいと思ってもらえる人、居住している方へ、これはしっかり見据えて、分けて物事を考えないと、本当に総花になってしまうとポイントがずれてしまうと私は思っていますので、それはぜひ踏まえてやっていただいて、別に戦略プラン。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"塚本副委員長","kind":"質問","question":"最初に、区職員が考える品川区の地域資源で、商店街が１位で、２,４７０名の回答があったということなのですけれども、これは電子アンケートで、なぜ商店街がということで、もし意見をもらっていたりしていることがあれば、どういうことで商店街が品川区の地域資源として各職員が出てきたのか理由を知りたいと思いましたので、これをお伺いしたいと思います。","respondent":"荒井広報広聴課長","answer":"なぜ商店街がいいのかといったようなことは個別には聞いておりませんで、自由記述の中に記載があったかと思います。まじわりがあるとか、そういう形です。マスコミ等に取り上げられて有名であるとか、そういったこともありました。","id":"exchange-038"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"もう一つは、つくる以上は、キャッチコピーというのは今品川区というと「輝く笑顔住み続けたいまちしながわ」というのが基本的にはキャッチフレーズというのですか、いろいろな刊行物などに書いている言葉だと思うのですが、それにかわるぐらいのものをつくっていくべきなのだろうというふうに思うので、そうすると、とりあえず終わりが決まっているのでつくって。","respondent":"荒井広報広聴課長、渡部委員長","answer":"本来ならば、年度内につくって決めてというのが筋だというふうに思っておりますので、努力はするところですが、今皆様方からいろいろな意見をいただいたところですので。これから私たち委員の意見を活かして進めていただければというところでお願いをして終わります。ただいま出ました意見については、今後策定予定のプランに活かしていただきますようお願いをしまして、所管事務調査を終了いたします。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332522?Template=document&Id=2008#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":61232,"voices":90}},{"id":"h27-20150121-14","meetingId":"h27-cm01","date":"2015年1月21日","dateIso":"2015-01-21","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時２６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"の１、特定事件調査","agenda":"の１、特定事件調査","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"今回の具体的検討事項のまとめについては、いろいろとこの１年間議論してきた中で、公有地・跡地活用と区民施設に関すること、この部分だけが入っているわけですけれども、考え方の問題ではあるのですが、例えば、最低制限価格制度などについても、ある程度、議論の中で共通の方向性が出てきた部分、これは活動現況の中での１枚目の下のほうに書いてあるようなことは、わりと異論がなく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問","question":"ここの取りまとめに関しては、公有地・跡地活用と区有施設に関することということでうたっているわけです。そこでまた契約のこととかがあると、また１つのそれはテーマになるわけではないですか。それはいろいろなことを検討してやったのはわかるのですが、今、これに関することということですから、これはこれでいいのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"中塚委員長","kind":"提案","question":"本日の正副（案）についての議論と、今のあべ委員の提案としての私の受けとめとしては、これとは別にもう１本、契約に関することを提言としてまとめるということで、この流れで続くというよりも、３つのテーマ事項の１つでありますので、別に分けるという、そういう趣旨で私としては受けとめておりますので、そういったあべ委員の意見と、また前段。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"あべ委員","kind":"意見","question":"済みません、ちょっと整理しますけれども、この委員会では、１年間に３つのテーマ、３項目でやるということで、本来であれば、３項目全てについてまとめを提出するのであろうけれども、そのうちの基金についてはまとめの段階に至っていないということが合意がなされているので、残りの２つの中で、お互いのいいところは提言をし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須藤委員","kind":"提案","question":"もう少し、普通は議長に出すときに、３つ与えられたテーマに対して、こういう活動やら意見をこうしました。それでこの中の１項目、これについては各委員会で合意に至っているので、行政側に提案をしてもらいたいとかというような表現で議長に提出しているものを、なぜ２つ分けてしまっていると、今、あべ委員の言うように、どういうふうにやるのかということがちょっとわからないので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"あくつ副委員長","kind":"意見","question":"須藤委員からの疑問に対して、私どもが話し合った考え方ですけれども、多分今までの基本的に特別委員会においては、調査事項に関して、基本的にはある程度委員会の中で合意をして区長側に提言をしていくというのがここ数年のスタイルだろうと思うのですけれども、今回、３つの調査事項に関しては、残念ながら議論は深まったまでも合意まで至らなかったというものが基金と、また、契約についても。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須藤委員","kind":"質問","question":"今のは違うと思うのです。ですから、そういうものを１つにして議長に報告して、そして正副委員長が議長にこういうわけでこれがまとまったので、理事者のほうに提言として議会として上げてくださいというような話のルール、形をつくっていかないと、いきなり本委員会から理事者に提出するというような話というのは、議長をすっ飛ばして委員会、こっちへ行ってしまう話になるから、私は違うと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あくつ副委員長","kind":"意見","question":"おっしゃるとおりだと思います。済みません、途中で。一応、活動現況報告を議長のほうにご提出をする、文中で一番後ろに、「今後、公有地・跡地活用と区有施設に関することにつきましては、当委員会における具体的検討事項のまとめして提言を行う予定であります」ということで、順番的には、まず議長のほうにお出しをさせていただいてと、こんな順番で考えているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"須藤委員","kind":"意見","question":"活動状況というものがまとめになるのだから、途中で経過報告だけ出すのだったら経過報告ですという話になってしまうけれども、そういうものはないと思うので、まとめの段階に入るのだから、それは一緒に出すのだから、今後、条件ついた項目だけではなくて、これをここへくっつけているのなら、私は意味がわかると思うけれども、別々に出すというのはちょっと違うと思う。","respondent":"中塚委員長","answer":"先日、議会運営委員会の中で、３月６日までに、特別委員会の活動現況報告を提出してほしいと議長よりお話がありましたので、それから、３月６日までに現在の活動報告がこういう形ですというものを提出するものとして示したものがこの活動現況報告ということと。","id":"exchange-009"},{"speaker":"須藤委員","kind":"意見","question":"活動報告の前にこれも入らなければ、途中経過の中にだってこれが、本日、今議題にしているものが入っていなければおかしいので、３月６日に出しますというのは、活動にしてもそれも全部含めてやっていることだから、それを入れて議長に出すのだから、その中にまとまらない部分もあったけれども、まとまったものがありましたというのを議長に出すのだから、別々にその後にまた出していくというのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"私は、正副でおまとめになったこの具体的検討事項のまとめと、あと、活動現況報告が一対のもので議長に提出されて、そしてこの委員会のまとめ、区長部局のほうに出していただきたいのはこの内容ですという、そういうふうな理解をして読んだし、それから、この委員会にも参加を、本日出席をしてきたのですけれども、これを示していただいて、先ほど須藤委員がおっしゃったように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須藤委員","kind":"意見","question":"だから、こっちの案を先に説明して、それでこっちに入っていくというならいいけれども、こっちを先にやり出すからおかしくなってしまうので、活動状況のこっちのほうを先に説明して、その後にこっちにつながるので、今、南委員が言ったように、これも一緒に出すのですという説明ならいいけれども、こっちだけ先に持ってきてどうなのだと言うから、あべ委員が言ったように。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"提案","question":"よくもう一度、正副で打ち合わせをしたほうがいいと思います。具体的検討事項のまとめというのは区長宛てに出す文書、提言として。だから、意外とそういうことを正副できちんと議論をしていただいて、切り分けた内容で詰めていただいて、再度提案してくれたほうが、恐らく、恐らくですが、本日ここでずっと議論するよりは、非常にまとまってくるのではないでしょうかという提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"それで、本年度も３月６日までにそれを出してというようなお話であったと思うのです。その流れと今回のまとめというものがどういう関係で整理されているのかということが、ちょっと私もわからなくなってきてしまったので、この中で委員長会へ出ていらっしゃる委員の方、どのように解釈されているかというところも含めてお伺いできればと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"確認","question":"今おっしゃった新しい議会の要素が加わっているわけですから、まずは正副委員長、そのことをよくご理解をしていただいた上で、では、行革委員会としては、いつどういうタイミングで何を出せばいいのかということを、お二人でまず確認をしていただいて、ある程度ベースができているわけですから、須藤委員が言うように、そういう中身のことも十分検討しながら、私としては、例えばこれから休憩するなり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤委員","kind":"提案","question":"ちょっと違うのは、基金創設、私のほうで言っているのは、区内スポーツの普及、１番目です、こういったものは時期を逸して、また次、来年に検討してくるというものではなくて、今すぐ行政側に提案していって、もちろんできるできないはまた理事者のほうで判断するのだろうけれども、それはある程度、スポーツ振興、文化振興というのは、この間のこの中では、大体意見的には言っていたと思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"あべ委員","kind":"意見","question":"内容の話に入っているようですので、もし基金についてということであれば、これ、活動現況のほうで言おうと思っていたのですが、基金について、創設の話がメーンになっておりますが、私、議論の間にも何度も繰り返させていただいたのですけれども、基金を増やすことについては慎重であってほしいというふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"私も今のあべ委員のところは、私も理解できると考えています。だから、現況報告ですから、いろいろな意見を出していただけるように、まとめにしましても、いろいろな意見を出していただけるようにしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"ここにある文化・芸術の発展、振興に資する基金については、皆さまの総意がとれれば、ぜひ提言というような前向きに検討してくださいというようなことでやっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"あべ委員","kind":"意見","question":"契約に関することについては、ちょっと繰り返しになりますけれども、いわゆる総合評価の中で、先ほどちょっと言い間違えましたが、総合評価の中で、特に地域貢献ポイントについては、導入して見守っていこうという方向もありますが、基本的には見守るというか、注視していくということを、もし契約のところで書くのであれば、私は一番そこが、どこまで具体的に書くかはお任せするとしても。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"だから、そういうふうなことを理論的にまず正副が理解をしていただいて、万万が一に次の委員会で同じような議論をしたらえらいことになってしまうから、それに対して事前にこれこれこうでこうだからこうなるという理論的な勉強をして、その上で委員会に臨んでいただく、そういうふうにしていかないと、次、１回しかない委員会がまたこういう形になると非常にもったいないし、むだだと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問","question":"まとめのほうで、文言的に、ほかの委員からも指摘があるかもしれませんけれども、この際ですから、４段落目の最後の部分です。おしりから見ると、「今後の区有施設のあり方の根幹をなしていると、当委員会における共通した認識でありました」という日本語の使い方が、ちょっと日本語としてはどういう意味かと。分析し把握、把握と分析の順番が違う。ちょっと細かいですけれども、もうあと１回しかないから。","respondent":"中塚委員長","answer":"３月６日までに議長に提出する活動現況についてですけれども、いわゆるまとめにかかわるところを抜いて、この間の委員会の活動について、議長に報告するものとして、内容を改めさせていただいて、文面については正副にお任せいただきたいと思いますけれども。","id":"exchange-022"},{"speaker":"須藤委員","kind":"意見","question":"まとめということもその中に入れていくべきなのです。まとめだけ取り出してしまってまとめにするのではなくて、活動状況というか、１年間の結果というものを全部整理をしてきて議長に報告する。１年間のまとめとして出せばいいの、全部を。１年間議論したことを報告をすることがまとめなのだから、その中に委員会としてはこういう言葉で提言をしていきますということが最後に出てくればそれでいいことなので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"須藤委員","kind":"意見","question":"だから、その中に活動結果、１年間の活動結果の中にまとまったものがありますと、こういうものは今後ともいきますというような形でその文章が１枚になればいいので、そっちだけまとめて、こっちを出しますと言うから、みんなおかしくなるので、今まで委員会では全部こういう議論をしてきました、この点が整理ができて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"若林委員","kind":"意見","question":"同時に、まとめは区長部局も意識しながらという二本立てで今までずっと多分連綿と特別委員会の出した形式ではなっている記憶があるのですけれども、それを今回は、正副のお考えはどうかわかりませんけれども、それを１つにまとめてしまうというお話なのですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"須藤委員","kind":"意見","question":"そういう意味で、提言としたものが区長部局へ行っているので、まとまったものだけではなくて、理事者のほうにも経過だって、議会で今何をどういう状況で、どういう話になっているのだということを知らしめなければいけない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"若林委員","kind":"質問・要望","question":"いきなり当委員会のまとめはこうです、この部分は提言ですと、しっかり取り組んでいただきたい。だから、私としては、現況は現況で本当にコンパクトにまとめる。区長部局を意識したまとめは、それだけで１つの文章にするという今までの慣例というのか、そういうやり方でいいのだと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"南委員","kind":"意見","question":"それでいいと思うのですけれども、ただ、昨日の説明があって本日こんなふうになってしまったということを、絶対に繰り返すわけにはいかない、もう時間が１回しか残されていないので、正副でまとめていただいたものを、ある程度の余裕をもって各会派に説明なりしていくときに、きちんと進め方も含めて了解を含む、絶対それでなければいけないということではないと思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/668787?Template=document&Id=5982#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":14265,"voices":49}},{"id":"h27-20150122-18","meetingId":"h27-cm01","date":"2015年1月22日","dateIso":"2015-01-22","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 １時４３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"やっぱりこういうものが出れば、周りもスポーツがすごく盛んなのだねということで、区民も非常にそれを周知して、それこそ本当にスポーツ振興の一端を担う部分だと思いますので、本当に小さなもので優勝、それに出場したからといって、それをわざわざ横断幕化するかというのは別としても、できる限り掲げていただきたいと思っているのですが、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、基本的には、そのチームが、例えば連合チームだとかそういうことであるならば、学校のほうで連携をとっていただいてそこに張るというような形をとっています。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"は多分、小さないろいろな試合に出ていて、なかなか全国大会まで行き着かないけれども、それなりの何となくの成績をおさめている子どもたちも多分多くいらっしゃると思うので、どうやってその情報をキャッチするかは別にしても、品川区ではできる限りそういうものを把握していただいて、そのやっている競技が多ければ多いほど、そういうところに力を入れて育成していくというのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"ちょっとお伺いしたいのですけれども、これは公立の品川区の小学校、中学校と、私立の学校も入っているかと思うのですけれども、あと都立の産業技術高等専門学校ということで入っていますけれども、私立の学校とか都立の学校とのコミュニケーションというか、課としての連携というのはどういう形で、学校のほうからの推薦があってということなのか、そのあたりのことをお聞かせください。","respondent":"安藤文化スポーツ振興課長","answer":"私ども、まずこの制度自体を区民の皆さんに浸透して知ってもらうということを第一に考えまして、まず、この制度を広報紙またはホームページ、それから各学校にご案内をさせていただいたり、また私立の学校にもご案内をさせていただいて。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"公立の学校は品川区がこうやってやるというのはよくわかるのですけれども、私立の学校との、ちょっとあれですけれども、お金の出し方というか、全額区でやられているかと思うのですが、そのあたりの連絡というか、コミュニケーションはどうなっていますでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"例えば、７番、８番のところなのですけれども、品川女子学院のところです。これも我々が情報をキャッチしまして、学校の先生にこういう制度がありますと、１本についてはこちらのほうで予算がありますのでぜひということでお話を申し上げまして、掲示をさせていただいているです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この文化スポーツかがやき顕彰という制度そのものとしては、これは横断幕を掲示するという、このことだけという、そういう制度になっているのかということを１点お聞きしたいのと、あと、区民のスポーツ振興ということで、ほかのことについてもということでしたのでちょっとお伺いしたいのですが、ちょっと前にテレビの報道で、ヨーロッパの国々ではかなりスポーツが日常的に国民の中にすごい浸透していて。","respondent":"安藤文化スポーツ振興課長","answer":"ちょっと今、平成２１年３月の区民意識調査ということで、品川区民の２０歳以上の２,０００人を対象に行いました。そこのところで、ほとんど毎日と、週１回から２回の人がやっているパーセンテージですが、この当時、４３.８％です。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"毎日やっている方がどれくらいと、週１回以上という方がどれくらいということがわかったら教えていただきたいのと、そこのやっているスポーツというのは、どんなスポーツをされているかというあたりも、具体的に区民のスポーツが日常的にどういうふうな形でされているのかという辺りがわかったら教えていただきたいのと、そして、そういうスポーツをされている方の要望というか要求というのが。","respondent":"安藤文化スポーツ振興課長","answer":"それからあと、区民のスポーツ種目についても、何をやっていますかという、何をやりたいですかというような質問は、そのときの調査は実施率だけで、そのときは種目まではやってございません。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は今回、せっかくオリンピック・パラリンピックが招致されたというところでは、より多くの方々が、区民がスポーツに親しむことができるという、そういうスポーツ振興というふうなところで図られていくと本当にいいなというふうな思いがしているのですけれども、自分自身を考えてもそうなのですけれども、なかなか日々の仕事がすごい忙しくて、日本人は特に長時間労働の中で。","respondent":"安藤文化スポーツ振興課長","answer":"まさに委員ご指摘の区民の方々がスポーツに親しんでいける、親しむ場所、環境をつくるということは私どもも最重要課題として取り組んでいるところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はやっぱり、このオリンピック・パラリンピックが東京で実施されるということを契機に、ぜひ平成２２年にそのアンケート調査をとったということですので、どんな種目をされているのか、またどれぐらいやっているのか、そしてまた、そういう区民の皆さんがどういうスポーツ振興についての要望があるのかという辺りも、区としてぜひアンケート調査をもう１回やるなどして、ぜひつかんでいただいて。","respondent":"安藤文化スポーツ振興課長","answer":"これからますます２０２０年に向かって皆さんのスポーツの意識も上がってきます。そんな中で我々も生活の中にスポーツということで、区民に対して気軽にできる環境をあらゆる方面から整備をしていきたいというふうに考えています。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ区民の実態もつかんでいただき、要望もつかんでいただきますようにお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"これまで４年間、年々顕彰の実績も増えていってすばらしいことだなと思う中で、具体的事例がもしあれば、区民同士のつながりが深まった事例だとか、地域のにぎわいと活性化を図れたことがある実績、事例があれば教えていただきたいのと、それも含めてこれから、まさに今、オリンピック・パラリンピックを目指してこうした機運をさらに盛り上げていくという事業だと思うのですけれども。","respondent":"安藤文化スポーツ振興課長","answer":"これからもそういうような形で、この事業をますます普及発展させていきたいというように考えてあります。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"その中で区としてやっている事業の中では、やはりまさに会場もある、先ほど言ったようにオリンピック・パラリンピックの実施会場でもあるという中で、先ほど、顕彰については横断幕のということがありましたけれども、例えば、区民同士のつながり、地域のにぎわい、活性化により一層つながるように、例えば選手だとか、お一人お一人の状況にもよると思うのですけれども。","respondent":"安藤文化スポーツ振興課長","answer":"ですから、これから委員ご指摘のとおり、この実績を還元をできるような報告会だとか、何か講習会だとかができますれば、そんなものも考えていきたいというように考えてあります。","id":"exchange-011"},{"speaker":"つる委員","kind":"意見","question":"まさに品川区にとってもそういった方々は、人財といいましょうか、まさに宝だと思いますので、しっかりと品川区でも顕彰もしつつ、また品川区にもご貢献いただくといったことで、ぜひ積極的に検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問・要望","question":"この障害者スポーツの普及・啓発に関することということで、区民の障害者スポーツやパラリンピックへの関心を高める活動を展開と、あと、障害者スポーツ環境の整備により一層努めていく、スポーツ環境の整備ということなので、多分体育館とかをバリアフリーにするとか、そういう部分だとは思うのですが、ここの部分と、裏面のまちづくりに関することの（３）で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つは、区内競技場のあり方のところの（２）なのですけれども、「大井ホッケー競技場が多目的に利用できる構造となるよう、引き続き働きかけていくこと」というのは、野球場としてオリンピックが終わった後も使えるようにということの含みを持たせた言い方ということで、こんな感じになったのかということをお聞かせいただきたいのですけれども、私は野球場として使える。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、区民から要望があったから、それはどんどん積極的に何でもやるべきだということに捉えられるような表現ではない表現にしていただきたい。それからあと、野球場の件は、要望書は出しましたけれども、一応野球場は確保されるということで決着がついたのですか。","respondent":"渡辺委員長","answer":"先ほどの特区のところ、ここの表現は文章全体、その部分だけではなくて、正副でまた再検討させてください。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"今いろいろな意見等を聞いていた中で、やはり私ども、さまざまな中でこの１年間、特別委員会で研究してきた内容が全てまとめられていると思います。今、委員長のほうからもございました。ただ、品川区で今、競技されるというもの、オリンピックに関しましては２競技、もう名前が出ているものですから、そこはもう名前を出していただいたままで個別の競技に向けてというところは構わないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462476?Template=document&Id=6468#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":13013,"voices":42}},{"id":"h27-20150220-3","meetingId":"h27-c-budget","date":"2015年2月20日","dateIso":"2015-02-20","committee":"予算特別委員会","time":"午後 ２時０５分～午後 ２時１２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢副委員長","kind":"意見","question":"就任のご挨拶ということで、委員長とともに不慣れなもので、一生懸命、委員長を手伝っていきますので、何卒、皆さん、効率的で実りの多い委員会運営にご協力をお願いいたします。僕もこの場で皆様の議論を得々と聞かせていただきますので、実りの多い議論、楽しみにしていますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/134650?Template=document&Id=1016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":2142,"voices":16}},{"id":"h27-20150223-6","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"区民委員会","time":"午前１０時００分～午後 ０時０２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"第２０号議案、品川区公共の場所における客引き行為等の防止に関する条例","agenda":"第２０号議案、品川区公共の場所における客引き行為等の防止に関する条例","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"条例制定に向けては、我が会派からも要望しておりましたので、本当に大歓迎です。内容につきまして何点か質問します。施行日なのですが、７月１日ということで、しかも過料については１０月１日ということで、周知期間３カ月という説明があったのですが、その周知期間は必要なのでしょうか。できれば４月１日から施行にしていただければよかったなと思うのですけれども、その点についていかがでしょうか。","respondent":"上垣外生活安全担当課長","answer":"例えば、業者に対する周知、あるいはまちの人に対する周知、こういった準備をするためには、やはり３カ月程度の期間を設けてしっかり知っていただく、こういうことが必要であるというふうに考えております。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"例えば、これ、条例自体は全区を対象としていて、特定地区は五反田ということですけれども、例えば五反田に限って言っても、会社を出た途端から張りつかれて、うちの店に来い、引っ張ったり、もうその方がここのお店に入るよと、入る寸前まで引っ張ってお客さんを連れていってしまうとか、かなり悪質な状況ですから、まちの人たちの周知なんて、本当にすぐに。","respondent":"上垣外生活安全担当課長","answer":"ですので、今後、その他の地区につきましては、これから実施をいたします五反田地区の実施状況、さらにその後のその他の地区の客引きの状況、これを見ながら広めていく必要があるかどうか判断しながら進めていきたいというふうに考えております。","id":"exchange-002"},{"speaker":"本多委員","kind":"意見","question":"今までの状況ですと、執拗な客引きに向けて注意をするお店ですとか地域の方がいた場合に、逆にそれがしつこいぞということで大崎警察等に通報されてしまって、正義感をもって注意したほうが逆に大崎警察から取り調べを受けるような状況が多々あったのですが、これから例えば地元のお店の方や地域の方がそういう執拗で強引な客引きに向けて注意をしたときに、逆手をとられないような対策というか。","respondent":"上垣外生活安全担当課長","answer":"今までは、まちの人が客引きに対して注意するといっても、やはり法令上の根拠はない、事実上注意を促すという形だったと思うのですけれども、この条例ができれば、この条例の裏づけに基づいてきちんと指導する、注意するということが可能になってきますので。","id":"exchange-003"},{"speaker":"本多委員","kind":"意見","question":"そういうトラブルがなくなるように、ぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"この条例ですけれども、五反田の話は私も先日から伺っておりまして、今回こういうような条例化ということで出てきました。この中で何点かお伺いしたいのですけれども、ここはもう公表ということなのですけれども、公表についてなのですが、どのような手段で公表されるのか。一般の方とか、そういう方が知り得るような公表の仕方になるのか、その辺を１つお伺いしたいと思います。","respondent":"上垣外生活安全担当課長","answer":"公表の方法につきましては、最低限、区役所の掲示板に掲示するということは必要だと思われますが、その他、例えば区ホームページに掲載するということも、効果的なものであればそういったものも検討していきたいというふうに考えております。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"もう１つ、これは客引き行為をした場合に対しての罰則ですけれども、そのような客引きをされた人を受け入れる店側の罰則規定というのは、今回は入っていないと思うのですけれども、この点についていかがでしょうか。","respondent":"上垣外生活安全担当課長","answer":"店側の責任といたしましては、例えば、その店がその者を雇って客引きをさせているということであれば、第１５条の両罰規定によって処罰をすることは可能ですし、あるいは、直接指示をしてこういった客引き行為をさせたということであれば。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"これは店側が人を雇ってした場合は確かに両罰規定になるのですけれども、例えば、そういう立場でなくして、勧誘されたというような状況を知りながら、店のほうで受け入れをするということに関しては、罰則規定が今回はないのですけれども、立ち入らせ行為という形でこの条例をつくっているところもあるやに聞いておりますので、そのような形で店側にも注意を促すというのでしょうか。","respondent":"上垣外生活安全担当課長","answer":"おっしゃるとおり、全く店と結びつきがないということであれば、この条例によって直接罰を科することはできないと思いますけれども、やはりこの客引き行為につきましては、罰則がないといたしましても、こういった環境を排除していくために店の協力というのは当然必要ですので。","id":"exchange-007"},{"speaker":"浅野委員","kind":"意見","question":"規定をどうするかという考え方もあると思うのですけれども、やはりお店の側が客引きに対して断固たる決意で営業するというような、そのようなことも推進をしていかなければならないかと私も感じておりますので、この条例が実効性のある形で進めていただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからあとは、そもそも悪質な客引きの状況がどの程度あるのかというのが数字で、どういうふうな数字がそういうふうなもので具体的にあるのかがよくわからないですけれども、１１０番の通報ですとか、区民からの苦情ですとか、ほかの自治体の条例の制定のところを読んでいたら、地域の住民団体のほうからそういう条例をつくってほしいという要望が出されて。","respondent":"上垣外生活安全担当課長","answer":"第１番目の２３区内における客引き防止条例等の制定状況につきましては、私のほうで９区でこの条例が定められているというふうに認識をしております。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"第２条で、客引き行為が、多くの自治体が風適法の対象に加えて、カラオケと居酒屋が風適法では午前０時からしか取り締まりの対象にならないということでつけ加えているというところが多いと思うのですけれども、なぜ品川区が全ての事業者を対象にするのかというところを教えていただきたいのと、それからあとは、そういうところ以外での品川区のほかの業種、全ての業種にしたというその理由とあわせて。","respondent":"上垣外生活安全担当課長","answer":"２つ目の目的として、「区民等の責務」を盛り込んだ理由につきましては、この取組みにつきましては、区だとか警察だけで目的を十分達成することはできないのではないか、やはり区民の方にも積極的なご協力をいただいて、区全体でこういった環境を改善していこう。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この対象地域なのですけれども、特定地区というのは決めていくということなのですけれども、ここの特定地区というのは、とりあえず五反田駅周辺ということになるのでしょうか。だから、区内全域でそういう形での指導がされるということになっていくのか、そういうことであるとしたら、区内全域の対象地域と、それから特定地区との違いというのはどういうところにあるのかということもお聞かせいただきたい。","respondent":"上垣外生活安全担当課長","answer":"第１点目の介護等の役務に従事するためのチラシまき、これが規制の対象になるかどうかということですけれども、ただ単にその場所にとどまって不特定多数人に配っているという状況については、これは対象というふうには考えておりません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この「あらかじめ指定する者」というのはどういう人なのかということと、その人が何を基準に指導するということになっていくのか、そこら辺のところがもうちょっと、区内全域でそういうふうにパトロールみたいなものがされて、そういうふうなところが指導されるというふうなことになっていくのか、そこら辺のところがイメージできるような形で、もうちょっと詳しく教えてください。","respondent":"上垣外生活安全担当課長","answer":"２つ目の「あらかじめ指定する者」につきましては、もちろん指導の基準は条例で示している禁止行為に当たるものについて、それをやめなさいという指導をしていくことになります。この条例が基準です。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当は、私はそういうものを１つ１つこちらが聞かなくても、もうちょっと詳しく、今回初めての条例ですから、初めてこれを施行するわけですから、そこら辺のところがイメージできるまでのもっと詳しい説明をぜひ、１つ１つこうやって聞かないとというのではなくて、説明をしていただきたいなという思いがしているところですけれども、生活安全サポート隊ということで。","respondent":"上垣外生活安全担当課長","answer":"そのために、さらにサポート隊を２名増員させていただいて、計１６名のローテーションでこの取組みを含め、まちの皆様のふだんの生活の見守り、あるいは子どもの見守りを含め、ローテーションで対応する体制を整えていきたいというふうに考えております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、全域で指導はできるということで言われましたよね。この生活安全サポート隊が２名増員になって１６名になって、ローテーションでパトロールをするのですか、そのパトロールをするというのは、五反田地域の指定された特定地区だけをパトロールをして、そこのところで指導、勧告、警告、公表というふうな形になっていく。","respondent":"上垣外生活安全担当課長","answer":"ただ、指導を行うための実際の体制、これについてはやはり優先順位をつけて考えていくべきというふうに考えておりまして、まずは特定地区を優先的に指定をして、その範囲でやっていくべきものと考えております。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、全域で指導は可能だけれども、とりあえずは特定地区だけだと。全域を対象にされるということはないのですか。五反田地域だけで指定するということになると、五反田地域では、どういう人をどれぐらい指定するのか、そこのところをお聞かせいただきたいのと、あとは、今回この条例を実施するにあたっての予算についてもあわせてお聞かせいただきたいと思います。","respondent":"上垣外生活安全担当課長","answer":"２つ目、トラブルの防止につきましては、おっしゃるとおり、区民の方だけで回って注意をしていただくということは避けたいというふうに考えておりまして、必ず生活安全サポート隊が同行する。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう１つは、過料についてなのですけれども、この客引きの現状が私もよくわからないのですけれども、若い人がアルバイトで客引きをしているみたいな状況もあるのではないかという思いがするのですけれども、そういう場合は、その個人に対して公表したり、過料に処するということにしていいのだろうかという思いがするのですけれども、そのアルバイトの若者を雇っている事業主。","respondent":"上垣外生活安全担当課長","answer":"１点目の指導の基準につきましては、実際に運用するための要綱、マニュアルのたぐいは、今後策定していく予定をしております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はそこら辺のところがなかなかよく理解できないところなのですけれども、本当に今、若い人が仕事、雇用の厳しい環境の中で、そういうアルバイトをやっているという人もいるのではないですか。そうすると、どれぐらいの時間帯と回数と体制でやっていくのかということもお聞かせいただきたいと思います。","respondent":"上垣外生活安全担当課長","answer":"時間帯につきましては、夜の８時を中心とした時間帯です、この時間帯を中心に考えております。回数につきましては、月曜日から土曜日まで、基本的には毎日実施したいというふうに考えております。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"長くなってしまってすみません。そこのところで、何が足りなくてこんな状況になっているのか、そこのところをさらに充実をさせるというところではできないのか、区がこういう形で条例をつくらないと、それだけではどうしてもだめだというあたりの、そこの根本的なところをもう１回お聞かせいただきたいと思います。","respondent":"上垣外生活安全担当課長","answer":"そういった状況を踏まえまして、この条例によって、区、区民あるいは警察が連携をしまして、日々継続して指導を行うための法令上の根拠、これを与えるために今回の条例を提案させていただいた次第であります。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その風適法とか迷惑防止条例では、日々そういうふうな形ではできないのですか。罰則ということを目的にしないと、日々そういうふうな形での見回りだとか、指導ということはできないという仕組みになっているということなのですか。","respondent":"上垣外生活安全担当課長","answer":"全くできないという趣旨ではありません。それなりに準備等が必要なので、今この条例が想定しているような毎日毎日見回って指導するというところはできないというのが現状であります。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、そこの条例や法律でもできるけれども、そこまでの体制になっていないために、それを区の条例でカバーするという、そういう形と考えていいのでしょうか。","respondent":"上垣外生活安全担当課長","answer":"体制だけの問題ではありませんで、実際の取り締まりのやり方ですね、これについても一定の限界があるというふうに考えておりますので、やはり区、区民等が継続して行うための根拠が必要であるということで、この条例を提案させていただいているものであります。","id":"exchange-020"},{"speaker":"藤原委員","kind":"提案","question":"この条例、私は賛成をするという意思で質問しますが、課長が警視庁から約２年前に品川区に来てくださったときに、区民のことを思っていろいろな相談をしましたら、たしか一番最初のときに、課長、公の委員会ではなくて個人的に「五反田が今、客引きがひどいよ、だから１回現場を見てください」と、たしかご就任されたときぐらいに私が個人的にご連絡をさせていただいて。","respondent":"上垣外生活安全担当課長","answer":"これは条例第１条の最後のほうに記載をさせていただいていますとおり、区民の安全で安心な地域社会の実現に寄与すること、これが最重要な目的というふうに考えております。","id":"exchange-021"},{"speaker":"藤原委員","kind":"提案","question":"五反田を見てほしい。みんな生きていくためですから、頭いいです。だから、せっかくこういう条例をつくったのですから、何年後かには、もうあの客引きがいなくなる、五反田を一般の方でも、特に本当に気弱と言ったら失礼かもしれないけれども、あまり逆らえないような方でも普通に歩けるまちに戻していただきたいという思いがあって今質問しているのですけれども、その辺についてはいかがでしょうか。","respondent":"上垣外生活安全担当課長","answer":"したがいまして、この罰則を背景に、区、区民、警察等が連携して、日々継続的にまちに出て指導していく、環境改善のために指導していく、こういった取組みを継続していきたいというふうに考えております。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問・要望","question":"なぜ出るかというと、２０２０年にオリンピックでいろいろな方が来る、海外の方もいらっしゃいますよね。オリンピック会場ができます。品川区は２０２０年に向かっている。この辺も含めて、間違いなく２０２０年のオリンピックのときには客引きゼロ、このぐらいの勢いでやらなくてはいけないと思っているのですけれども、どちらの担当が答えてくださっても私はいい、その辺の答弁をいただきたい。","respondent":"上垣外生活安全担当課長","answer":"実際に他区の例を、この客引きの対応のためにパトロールすることによって、客引きが減ったという結果が出ています。さらに、それ以外の刑法犯の減少という効果も実際に見られておりますので、そういったことも視野に入れてしっかり取り組んでいきたいというふうに考えております。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"今、課長から本当に力強いご答弁をいただいて、私もあとどのぐらい議員をできているかわかりませんけれども、本当に品川区、これからすばらしいのだと夢を持ちつつ、今日の質問を終わらせることができました。本当にどうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"井上委員","kind":"質問","question":"何点かお伺いをしたいのですけれども、先ほどの目的のところで、区民等の責務を明らかにするというところでちょっと違和感があるのですけれども、それをお伝えした上で、第４条の区の責務というところの「自主的な活動の支援等必要な施策を実施する」というのは、想定されているものはどんなことなのかということと、第５条の区民等の「等」は、何を想定しているのか。","respondent":"上垣外生活安全担当課長","answer":"特定地区の指定の仕方につきましては、具体的に五反田地区という表現ではなくて、例えば西五反田何丁目という形で丁目を示して特定したいというふうに考えております。","id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"そうすると、ここのところで、区民等が自主的かつ相互に取り組むということは、その辺の人たちに自主的かつ相互に取り組むことを求めているというふうに理解をするのでしょうか。","respondent":"上垣外生活安全担当課長","answer":"第５条の区民等の責務について、自主的かつ相互に取り組むということは、やはり区としてそういうふうに取り組んでいただけるように積極的に働きかけていくということが必要だというふうに考えております。","id":"exchange-026"},{"speaker":"井上委員","kind":"質問","question":"周知をするのはわかったのですが、具体的にどういったことを今は考えていらっしゃるのですか。","respondent":"上垣外生活安全担当課長","answer":"具体的には、この施行日に向けてキャンペーンを開催するだとか、あるいは、広報啓発用のチラシを配布する、こういった方法を考えております。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問・要望","question":"もう１つは、指導のところですけれども、まず非常勤である生活安全サポート隊が午後出勤から２０時を中心にパトロールを展開するということだったのですけれども、その２０時を中心というのが現実的なのかどうなのか、客引きのイメージはもっと遅いのではないでしょうかと思うのと、その辺の勤務体制との関係とかそういうことで、それ以上は行政が行うところではもうできないということなのか。","respondent":"上垣外生活安全担当課長","answer":"指導体制につきましては、サポート隊について、昼過ぎに出勤いたしまして、夜の１０時までの勤務時間を今は考えております。その中で夜の８時前後を中心とした時間帯に現場に行ってパトロールしてもらう、こういうことを想定しています。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"サポート隊はパトロールをして指導して、第２項に、「区長は、あらかじめ指定する者に前項の規定による指導を行わせることができる」ということなので、普通の区民ではないということですか。ある程度何か経験者であると、そういうことですか。","respondent":"上垣外生活安全担当課長","answer":"そのために、ただ単に、あなた、お願いします、あなた、お願いしますという形でお願いするのではなくて、やはりこの指導をするために必要な知識を習得していただくための事前の講習みたいなものは必要だと考えております。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"ここの「あらかじめ指定する者」というのは、何か基準があってこういう人材であるということを取り決めた上で、自薦、他薦とか、そういうレベルのものではなく、こういう要件を満たした人ということをこれから規則でつくるということで考えてよろしいのでしょうか。","respondent":"上垣外生活安全担当課長","answer":"どのような方を指定するかについては、おっしゃるとおり、規則等で要件を定めて指定をするという手続を踏みたいというふうに考えています。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう１回確認なのですけれども、五反田が特定地区ということで指定されるわけですけれども、全域については、条例がどうかかわるのかというところなのですけれども、先ほど、何かそういう区民からの苦情とかがあったときに、生活安全サポート隊の方が指導に入るというくらいで、それ以外のところは、基本的に五反田、特定地区以外のところは。","respondent":"上垣外生活安全担当課長","answer":"２点目の客引き防止に関しては、ほかの多くの地区では区民にとっては関係ないのではないかというご趣旨だと思うのですけれども、ですけれども、やはりこの手のものというのは、その地区に住んでいらっしゃる方だけの取組みだけではなくて。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういう中で指導が可能と言いますけれども、どういうふうに指導の場面が出てくるのか、パトロールは基本的に、この条例についてのパトロールというのは五反田地域に限るということだったと思うのですけれども、どういう形でその指導は可能、可能だけれども、実際はどういうふうにされていくのかというのがちょっと見えないのですけれども。","respondent":"上垣外生活安全担当課長","answer":"やはりこの施策を実効性あるものとしていくためには、優先順位をつけて実施していくのが重要だというふうに考えておりますので、まずは特定地区を中心にやっていくべきものというふうに考えております。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、それで確認なのですけれども、それで先ほどから確認をさせていただいているのですけれども、だから、この条例が全域に適用されるとは言っても、実際のところ指導される場面というのは、ほとんど起こらないということで考えていいのか、また、もしも起こるとしたら、どういうふうに指導の場面というのがつくられるのかというところ、だから。","respondent":"上垣外生活安全担当課長","answer":"実際には、特にそういう実態が出てきた、しつこい客引きがあるということが特定地区以外であれば、例えば生活安全サポート隊がそこへ行って指導するということは可能ですし、そういったことも必要であろうというふうに考えております。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"だから、先ほどからそういうことで確認させていただいたのが、基本的に日常的なパトロールをするのは五反田の特定地区で、それ以外のところは、住民からの苦情だったり、告発だったりというときに生活安全サポート隊が行って指導するという、そういうふうな形で適用されるということでいいのですかということで先ほどから確認させていただいているので、それでよければそれでいいのですけれども。","respondent":"上垣外生活安全担当課長","answer":"そのとおりであります。","id":"exchange-034"},{"speaker":"沢田副委員長","kind":"提案","question":"以前から区民の皆様からもたくさんお話があったこの客引き行為の防止ということで新たな条例が制定されるということは大変すばらしいことだと思いますし、先ほど来、話もありましたけれども、安全で安心な地域社会の実現ということで、この品川区という自治体の中で必要な条例であるということで条例提案がされているわけですから、この委員会の中で審議をしっかりとしていかなくてはいけないと思います。","respondent":"上垣外生活安全担当課長","answer":"２つ目の過料につきましては、これはまずは違反行為に対して指導して、それに違反したら警告をする、警告に違反したら勧告をするという形で、その手続を踏まえて、違反を繰り返した場合に悪質と認めて過料を科すという構造になっています。","id":"exchange-035"},{"speaker":"沢田副委員長","kind":"質問","question":"それで指導しましたと、じゃあやめました、またすぐやりました、また指導しました、またやめましたという、その繰り返しになってしまうのではないかという、そういう思いがあるのですけれども、そうすると、当然、警告とか勧告までいくまでもなくということがあるのではないかということを危惧しているのですけれども、その辺はどう考えていらっしゃるのでしょうか。","respondent":"上垣外生活安全担当課長","answer":"それに違反したら、今度は勧告になるのですけれども、勧告に違反したら、またそれは勧告違反で１回カウントしていく、こういう形で手続としては進んでいくということを想定しています。","id":"exchange-036"},{"speaker":"あべ委員長","kind":"質問・要望","question":"先ほどからの議論でどうしてもわからないのが、この第７条第２項に出てきます「あらかじめ指定する者」、これがサポート隊以外の区民の方で講習を受けていただいてということなのですが、最初にこれを読んだときには、例えば五反田の近隣の商店主の方などに一斉にこういう指定をして、その方々も指導ができますよという形にするのかなと思ったのですけれども、どうもそうではなくて。","respondent":"上垣外生活安全担当課長","answer":"第７条第２項の「あらかじめ指定する者」につきましては、全くの区民、広く一般的に募るという趣旨ではございませんで、この客引き防止のための取組みに積極的に協力いただけるという意思を持った方と、その対応に必要な知識をこちらのほうからあらかじめ指導。","id":"exchange-037"},{"speaker":"井上委員","kind":"提案","question":"先ほど来、各委員から「区民の責務」というところで、ちょっと違和感があるということで、ここのところを委員会修正という形で文言整理をして、できればそれがいいという提案をさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"井上委員","kind":"提案","question":"第４条のところから「区の責務」、第５条「区民等の責務」とありますけれども、第５条の「区民等の責務」については、委員会の中での審議でも触れられたように、「区の責務」、「区民等の責務」というのには違和感があります。ですので、文言は別として、「責務」という表現を修正をすることを提案します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"本多委員","kind":"意見","question":"賛成です。この禁止行為に書いてありますように、他人に公共の場所における客引き行為等をさせること、この辺が本当に課題になっていると思いますので、ぜひ課題克服に向けて条例が制定されることを望み、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"浅野委員","kind":"質問","question":"賛成です。やはり安全安心のまちづくりの大きな推進ということになるかと、そのように思いますので、今後とも引き続きこのような対策というのでしょうか、まちづくりのための方策などを徹底していってもらいたい、そのように思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"ただ、今回の条例は、進め方そのものが今回のこういうふうな議論にもなりましたけれども、私もほかの区の条例の進め方をいろいろと見ましたけれども、多くの区が骨子案を提案をし、そしてパブリックコメントをとって、そしてまた条例を提案するという形で何度も議会で議論もし、そして区民にも意見を聞きながら進めるという、そういう中でこそ区民の啓発にもなるかなというふうに思っていますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"井上委員","kind":"提案","question":"この条例自体は賛成です。しかし、先ほど動議が残念ながら通らなかったのですけれども、やっぱり骨子案という形で委員会に提案をしていただくということが必要だというふうに、区民にかかわる大きな条例ですので、そういったことは今後前向きに検討していただきたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"確認","question":"プレミアム付商品券で、補正予算の審議にもかかわるところにもなるかもしれませんが、答弁の中で、大型店舗も含めて検討していくというような答弁があったかと思います。そこはちょっと定かではありませんので、そのことについて、方針として詳しく改めて確認をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/719578?Template=document&Id=2718#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":32050,"voices":107}},{"id":"h27-20150223-7","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"厚生委員会","time":"午前１０時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件抜き出しています。","topics":[{"id":"topic-01","title":"第２７号議案 品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第２７号議案 品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"何点か、確認で質問させてください。ですけれども、実際に増える人数は６人増、２０人増となっているので、全高齢者となったことについて予想される対象者の拡大と、それにあわせて、ここの資料では６人増、２０人増となっていますけれども、品川区のお考えを合わせてお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"実施した結果、またもう少し必要なことが判明すれば、またそこで変えていくようなことは柔軟にやっていきたいと思っているところです。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"現行はそういう人数なのでしょうけれども、でも全高齢者となったということは、当然対象が増えるわけではないですか。だから、現行は、今のサービスで１１人から１７人だというお話をお伺いしましたけれども、品川区内の高齢者は約４万５,０００人くらいでしたか、その方々が申し込める可能性があって、このサービスを受給できることに理論的にはなるわけですよね、全高齢者対象だから。","respondent":"永尾高齢者福祉課長","answer":"ただ、地域によっても利用しやすい人と、少し遠くて利用しづらい方もいらっしゃいますので、そのあたりの実績を見ながら、柔軟に考えていきたいと考えています。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"確認","question":"これは事業自体としてはいいことなのです。ただ、申し込む方が増えることは、当然想定されるわけですから、そのことについての対応の確認でした、よろしくお願いいたします。なぜ品川区が、今回こういう改定をしたのかという。","respondent":"永尾高齢者福祉課長","answer":"１２月にご説明いたしました第六期介護保険事業計画の骨子案のお話になるかと思います。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"先日の委員会で確かにご説明いただきましたけれども、この動きはこれからどんどん加速されていくわけですね。今回の本会議でも、何人かの議員から２０２５年の問題がありました。","respondent":"永尾高齢者福祉課長","answer":"なかなか保険の制度は難しいところがあるのですけれども、区といたしましても、保険料の冊子も今つくっているところですので、それをもう少しわかりやすく説明するような内容にするとともに、いろいろな機会を捉えて説明していきたいと思っているところです。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"確認","question":"１点確認ですけれども、介護保険料率の改定のほうですが、私の認識が違っていたら申し訳ないのですけれども、第五期の保険料がありますね。それから、第六期なので、ほかの自治体も当然これからなので何とも言えないとは思うのですけれども、その辺で比べてみて、決して高くはないというような認識があるのでしたら、その辺を教えてください。","respondent":"永尾高齢者福祉課長","answer":"保険料については、今、２３区で情報を集めてはいるのですけれども、まだ２３区決定はしていないところです。集めた情報の中では、品川区は下から２番目というふうに受けとめているところです。","id":"exchange-005"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"基金のところですけれども、もう１回確認させていただきたいのですが、この間の本会議では、１１億５,０００万円を基金から取り崩して保険料に充てたということだったのですけれども、そのことでの残額を教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"その後、平成２６年度末の見込みが、今出てきておりまして、その残高が約１７億８,０３７万円という数字が、現在のところでは出てきているところです。","id":"exchange-006"},{"speaker":"石田（ち）副委員長","kind":"提案","question":"今回、質問でもさせていただいたのですけれども、消費税８％の増税分の２５億円を使ったらどうかという提案をしたのですが、使えないものだというような答弁があったのですけれども、ここでもやはり、国が軽減を見送っている状況なので、自治体にやるなというのはおかしいという声が自治体から広がっているということで、法令では禁止はされていないということを厚生労働省は発表しているのですね。","respondent":"永尾高齢者福祉課長","answer":"先日も申し上げましたとおりに、何か災害等が起こったときに、全くお金がない状況で２ヶ月、３ヶ月ということになったときに、介護される方がサービスも受けられなくなるという状況も、最悪の場合に起こったりしますので、品川区は健全財政を目指していますので。","id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"保険料を算定するにあたってですけれども、この間も質問したのですが、事業所に２割、３割引き下げの単価で、結局幾ら引き下げるのかということをお聞きしたときに、算定中です、とお答えいただいたと思うのですけれども、算定しないで保険料を出すことはできないと思うのですけれども、おおよそ見込み額があったということなのでしょうか、それは幾らなのかを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"ただ、この部分について、先日、改定した新しい介護報酬の金額が出てきておりまして、前回、秋に説明したときから、事業者の運営のことも考えながら、少し変更をさせていただいているところです。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、今回の２割、３割単価を引き下げた分は、考慮しないでも大丈夫なくらいの給付費なので、それを入れないで算定したということですか。","respondent":"永尾高齢者福祉課長","answer":"実際に２割、３割というのが、そこまでにはならないという想定で考えています。事業所が今やっているサービスの提供の仕方によって、かなり差がありまして、全部の事業所が２割、３割下がるわけではございません。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"これだけ引き下げるのに、なぜ算定できたのかと少し疑問だったので伺いました。今回もそうですけれども、いつもこういった値上げ改定のときには、パブリックコメントも取られていると思うのですけれども、今回のパブリックコメントの集まり具合はどうだったのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"内容といたしましては、大ざっぱに申し上げますと、２件が、他区の人から、品川区は介護のシステムやサービスが充実していると言われるようにしてほしいということや相談支援の仕組みの充実ということで、３件の方は。","id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"７件というのは、本当に少ない数字だと思います。私たちも、第五期とか第四期の際には、要望を伝える機会ですので、ぜひ皆さんパブリックコメントを出してくださいということを呼びかけてきたのですけれども、今回は私たちもいろいろ忙しくて呼びかけはできなかったのですが、それで７件。ですけれども、その７件の中でも、いろいろ充実を求める声なのだと、今、確認させていただいたのです。","respondent":"永尾高齢者福祉課長","answer":"これからの説明会のお話になるかと思いますけれども、区では、介護保険の事業計画につきましては、概要版をつくることにしておりますので、その概要版を使いまして、介護保険の制度の普及というところで説明をしていきたいと考えています。","id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ぜひ丁寧な説明を、どの分野でもしていただきたいと思います。それから、リハビリの市町村特別給付のところですけれども、この間、２,５００万円ほどが、この市町村特別給付の事業で使われていたのではないかと思うのですけれども、今回、リハビリサービス特別給付の事業が地域支援事業にいくことで、市町村特別給付はどれくらい削減というか、使わずに済むことになるのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"そのかわりにデイサービス等活用型介護予防事業ということで、地域支援事業のほうが１,１２５万２,０００円プラスになるという計算になっております。","id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはり市町村特別給付なので、６５歳以上の方の保険料ですので、市町村特別給付で事業をしていくというのは、本当に保険料にも大きく跳ね返るので、私たちはやめてほしい、使うべきではないということを要望してきていたので、この一つの事業が地域支援事業のほうに移行されたというところでは評価するのですけれども、身近でリハビリと水中運動というのが、品川区の介護保険の中では、要支援１、２の方。","respondent":"白鳥高齢者いきがい課長","answer":"水中トレーニングのほうの一般介護予防のほうですけれども、こちらにつきましても、６５歳以上の要介護認定を受けられていない自立支援高齢者の方と、在宅介護支援センターのスクリーニングで二次予防事業と判定された方が対象ということで行っております。","id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、多様な介護予防事業の地域支援事業のほうでは、基本的に、認定を受けていない方がこちらでやっていると。そして、認定を受けている方で要支援１、２、要介護１、２程度の人が、この市町村特別給付だったほうを使っていたと。そうすると、今回、地域支援事業のほうに移行されるわけですから、要支援１、２、要介護１、２の方もこの事業は使えるということですよね。","respondent":"永尾高齢者福祉課長","answer":"今のご説明のとおり、要支援１、２の方も、要介護１、２の方も使えるということになります。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"両案とも賛成いたします。だから、そういう実績をまず示していただいて、それを今度は高齢者人口増を踏まえて、当然事業が拡大していくわけですから、結果としてこうなりますということを、やはり区民に十分に説明していただくことは、ぜひお願いしたいと思います。それも合わせて、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"向委員","kind":"意見","question":"私たちの会派も賛成します。１点、いろいろ段階を細やかに分けていただいていることで安心はしているのですけれども、要は所得の多い方の部分が、今後増えていくことが予想されるだろうということで、払うべきところはしっかりということで皆さんよく理解はされていると思うのです、そういうご意見も区民からいただくのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"値上げ幅も、先ほど見ましたけれども、基準額では６００円の値上げですけれども、第１段階、第２段階の方でも５０５円の値上げです。ですので、国に対しても、国が出す予算、国費などもさらに上げてほしいという、市長会などでもいろいろ声を出されていると思うのですけれども、これ以上の値上げではなく、値上げ中止を訴えたい、求めたいと思いますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"確認","question":"確認なのですけれども、この条例を改正した目的といいましょうか、理由としては、厚生労働省の省令の改正があって、それに基づいて、つまり全国の自治体が改正しなければならない義務があると思うのですが、そうなのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"区として、今までこういうサービスをやっていなかった内容もありますけれども、そういう部分について、ますます事業者が参入しやすい形になるかと感じているところです。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"意見","question":"おそらく厚生労働省は、先ほどもお話をさせていただいたように、これからどんどんと増えていく高齢者に対する一つの回答としてこれを示してきたと思われるのですけれども、そうすると次のステップとして、これから条例が改正される予定なのだから、これをもとに、例えば必要な新規の事業者を誘導していく施策であるとか、新たなサービスの展開であるとか。","respondent":"永尾高齢者福祉課長","answer":"定期巡回・随時対応型訪問介護看護は、私もいろいろなところで説明をしている中で、区民の皆様の関心がとても強いところです。","id":"exchange-019"},{"speaker":"たけうち委員","kind":"提案","question":"今、サテライト型の話が出ましたけれども、今回の定例会の我が党の代表質問の中で、小規模特別養護老人ホームを今後増やしたらどうかという提案に対して、サテライト型という答弁があったので、そのときに、サテライト型とは何なのだろうと言っていたのですが、今、ご説明があったので、何となくわかったのですけれども、そういう方向も考えるということなのか、その３点を教えてください。","respondent":"永尾高齢者福祉課長、大串福祉計画課長","answer":"やはり看護師がなかなか集まらないという現状がありますので、実態として、その施設に常にいなくても済むような状態もあるということを、国のほうも、社会保障審議会の分科会で有識者の方と検討した中で出た意見を反映して。そういった形でサテライト型の整備ということも柔軟にできるような法改正になっているというところですけれども、ただそうは言っても、さりとて、なかなかそういったものでも。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それからサテライトの話は、今は地域密着型の特別養護老人ホームというのは、杜松特別養護老人ホームしかないわけですよね。そうすると、今後、そういう小規模特別養護老人ホームを増やしていくにあたっては、サテライトにすると、今の運営法人しかその運営に携われないということになってしまうのかと思いますけれども、そういう考え方なのでしょうか。","respondent":"大串福祉計画課長","answer":"要は、そういった形で人材の交流ですとか、あるいは、先ほどあったように、概ね通常の交通手段で２０分以内といったところで、一体的な運営ができるというのがこのサテライト型の特徴になっているといったところです。","id":"exchange-021"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"2)は該当してくるのですよね。そうすると、東京都の指定を受ける第三者機関による評価をなくしていくということが、会議が一つ減るというところでは確かに、事業者だったりその会議に参加する人からすれば緩和されるのかもしれないのですけれども、これは必要だったからあったものなのではないのか、どうなのかを教えてください。","respondent":"永尾高齢者福祉課長","answer":"今まで介護・医療連携推進会議というものは、２ヶ月に１回開催しておりまして、メンバーとしては、地域住民の代表者ということで民生委員協議会だったり、地域の医療関係者ということでクリニックや薬局の方、連携している訪問看護ステーションの方々、区役所の支援の係の担当者。","id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど、看護師が集まらない現状もあるということでしたけれども、介護職員なども、仕事の割に低賃金、重労働、生活が成り立たないというところで、やりたくても、この仕事ではなかなか生活ができないというところで、人員が集まらないというところですが、看護師のところでは、区はどういうふうに見ているのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"実際に、訪問看護ステーションなども、平成２６年度になってかなり数が増えてきているという現状もありますので、こちらは全国的に統一した改正になっておりますので、全国的な流れの中で看護師が集まらない現状というのが出ているのかと考えています。","id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"(5)のサテライト型のところですけれども、地域密着型介護老人福祉施設を追加するということなので、今回これが追加されるのですけれども、追加される前にサテライトというものがどこかであったのかどうか、お聞かせください。","respondent":"大串福祉計画課長","answer":"ただ、先ほど申し上げましたように、今回初めて、小規模な特別養護老人ホームが地域密着型という形に整理されておりますけれども、小規模な特別養護老人ホームでも、いわゆるサテライト型を運営することができるというのが今回の改正になります。","id":"exchange-024"},{"speaker":"伊藤委員","kind":"確認","question":"これが、新のほうは、平成２４年東京都条例第１１１号の規定になっているので、確認したいのは、これも要するに厚生省令から都道府県の条例に変わったということなのでしょうから、それはやはり大きく言うと、都道府県の判断でこの基準そのものを変えることができることになったのでしょうか、もしおわかりになれば教えてください。","respondent":"永尾高齢者福祉課長","answer":"ここの部分についても、地方分権法の関係で、東京都のほうにおりてきておりますので、それを受けて、東京都の条例というふうに変更しています。","id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"２議案とも反対です。よくなる部分もあるとは思うのですけれども、必要だったものをなくしていくというその根拠もよくわからない。事業所は大丈夫だと言っていますと言いますけれども、やはりこれに従ってやっていかなければ運営ができないわけですから、大丈夫ですと言うのは当然ではないかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-02","title":"第３０号議案 品川区指定介護予防支援等の事業の人員および運営ならびに指定介護予防支援等に係る介護予防のための効果的な支援の方法の基準等に関する条例","agenda":"第３０号議案 品川区指定介護予防支援等の事業の人員および運営ならびに指定介護予防支援等に係る介護予防のための効果的な支援の方法の基準等に関する条例","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"現行では、厚生労働省の基準をそのまま横引きするということでしたけれども、よく予防が大切だということをおっしゃっているわけですから、将来的な構想の中で、このまま品川区の条例で対応できるようになるならば、さまざまな予防事業を展開するということも、当然、考えていくべきだと思うのですけれども、その二つをまずお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"介護予防支援ということは、直接サービスをする事業者ではなくて、サービス計画を立てたり、モニタリングをしたり、また計画を変更したり、そういうことをする仕事になります。区では、地域包括支援センターで、現在、それを行っているということになります。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問","question":"せっかくこれを品川区の条例で判断できるということならば、現行では、厚生労働省の判断でいいと思いますけれども、今お話をさせていただきましたように、元気な高齢者の方々には、ある意味、サービスは控えていただくようなことも考えていくこともできるでしょうし、またその逆で、本当に必要な方にはしっかりサポートしていく、そういう計画ができるわけですから、もう一声。","respondent":"永尾高齢者福祉課長","answer":"地域の高齢化率だとか、元気な高齢者のニーズとか、そういうところもきちんとこの介護予防支援の中で把握しながら、適切なサービスにつなげるような体制を整えていきたいと考えています。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"質問・要望","question":"裏面の２番の４行目で、「介護予防サービス等」の「等」のところに下線が引いてあるのですけれども何か聞いてほしいということなのかと思って、そこが気になったので教えていただきたい。その在宅介護支援センターは入らない、いわゆる区の直轄の地域包括支援センターということでいいのかどうか、その確認です。","respondent":"永尾高齢者福祉課長","answer":"地域包括支援センターのほうですけれども、介護予防支援につきましても、地区の在宅介護支援センターで計画等を立てておりますので、品川区の場合は、区の本体の部分と。","id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、いわゆる在宅介護支援センターでもやっているということですか。そうすると、それは品川区として条例化した文章の中には、どういう表現で載っているのか、どの辺に載っているのかも含めて、教えてください。","respondent":"永尾高齢者福祉課長","answer":"この条例の中に、地区の在宅介護支援センターのことまでは掲載されていないです。この条例の中は、地域包括支援センターということで大くくりに制定しています。","id":"exchange-030"},{"speaker":"向委員","kind":"質問・要望","question":"国のときもそうでしたし、今後も区の条例の中でさらに細やかなところが出てくれば、今後は多分丁寧に対応されると思うのですが、基本的にこういった苦情の記録とかは、どの程度保管というか、記録した後、例えば、そのまま物事が大事にならなければ、記録だけで終わるのか、もっと深いところをいろいろ調査するということも書いてありますけれども、こういったものの時間的なスパンは。","respondent":"永尾高齢者福祉課長","answer":"区のほうの介護保険制度推進委員会の部会の一つとして、モニタリング等調査部会というものを設置しておりまして、その中で、第三者も入れた中で、区に寄せられた苦情への対応状況とか、確認、また必要な指導、助言等を説明したうえ、今後。","id":"exchange-031"},{"speaker":"向委員","kind":"確認","question":"わかりました。ということは、何かしら本当に小さな苦情があったとしても、基本的には区に報告をして、その苦情については、事業者だけではなく、二重、三重に一つ一つ対応していくということでよろしいのでしょうか。念のため、それだけ確認させてください。","respondent":"永尾高齢者福祉課長","answer":"やはり苦情を申し立てた方の状況もお聞きし、さらに、サービス事業者のほうの状況もお聞きしながら、どういうことで納得いかないのかということを分析しながら、一つ一つきちんとした対応をしています。","id":"exchange-032"},{"speaker":"山元委員","kind":"質問・要望","question":"実は、特に八潮は、高齢化が区の中では一番進んでいるということで、国が定めるのではなく、区で基準を定めるということになると、全体的に見れば、できれば八潮を中心にというか、高齢化が進んでおりますので、その辺のお考えはどうか、ちょっと教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"現在も、八潮のほうは高齢化率が高くなっておりますけれども、この先も高くなるという見込みが立てられております。やはりそうなると、相談体制がまず第一に大事になってくるかと考えていますので、そのあたりは件数、それから内容なども見ながら検討していきたいと考えています。","id":"exchange-033"},{"speaker":"鈴木（博）委員","kind":"質問","question":"つまらない質問かもしれないのですけれども、参酌と従うべき基準というのは、そのような形でいただいていたのですけれども、一番最後の２２分の２０の上から２番目が、参酌ではなくて参照になっているのですけれども、これは何か理由があるのですか。それから、一番最後の付則が、漢字が変わっているのですけれども、何か理由はありますか。","respondent":"永尾高齢者福祉課長","answer":"「参照」は申し訳ありません、間違えまして「参酌」になりますので、訂正をお願いします。付則の部分ですけれども、区の条例では「附則」ではなく、現在常用漢字で使われている「付則」で統一しているものです。","id":"exchange-034"}]},{"id":"topic-03","title":"第３１号議案 品川区地域包括支援センターの包括的支援事業等の人員の基準等に関する条例","agenda":"第３１号議案 品川区地域包括支援センターの包括的支援事業等の人員の基準等に関する条例","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"ほかの区の状況を聞いてみると、今までの在支をそのまま包括支援センターに移行させたという形で、それで人員配置なども進めたとおっしゃっていたのですけれども、品川区が庁舎に１カ所、包括支援センターというふうにしていることはなぜなのか。どちらが正しいということはないと思うのですけれども、なぜ品川区はそうなのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"やはりバラバラで運営するよりは、１カ所で集中していることが非常にメリットが高くて、例えば、品川区では各地区の在宅介護支援センターで、そのエリアがきちんと決まっていて、その中でワンストップサービスということで、全ての相談の窓口ということで対応しております。","id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１カ所であることで、情報も電算システムで共有し合えているということですけれども、そうすると、保健師、社会福祉士、主任介護支援専門員というのは、各在宅介護支援センターには配置はされていないということですか。","respondent":"永尾高齢者福祉課長","answer":"実は準ずる者という規定がございまして、保健師に準ずる者として、地域ケア、地域保健等に関する経験のある看護師が準ずるものというふうに定められておりまして、この準ずる者に該当するということで、地域包括支援センターの中で２カ所に１名ずつ配置しています。","id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やはり保健師が少ないという意見も、地域や事業所からも寄せられる中で、今、権利擁護や虐待への対応などは、こういった在宅介護支援センターではできないことになっていたかと思うのですけれども、これから高齢者も増えていくということで、こういったことが心配される一つでもあるのではないかと思うのですが、こういうところへの対応などはどのようにされていこうとされているのか、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"権利擁護や虐待につきましては、かなり動き方が非常に難しい部分があります。各在宅介護支援センターで個別に動いてしまうと、逆効果になったりすることもありますので、今は、区のほうで直接対応しております。","id":"exchange-037"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やはりこの人員ですよね、保健師、社会福祉士、主任介護支援専門員という方たちを１名ずつ配置する、だけれども、それが配置されていない分、今の品川区の現状の在支では、この配置するべき人たちの仕事を少し請け負ってしまっている部分もあるのではないかと思うのですけれども、今後をどのように考えているのか、教えてください。","respondent":"永尾高齢者福祉課長","answer":"これから、高齢者が増えていく中で、人を増やすのか、それとも面積的に少し難しいようであれば、また別の場所を増やすのか、その辺は、その状況に応じて、これから必要な検討はしていかなければいけないと考えています。","id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"介護等支援を受ける方々の、利用者の安心・安全が一番大事だと思うので、そのための人員確保、配置すべき職員は、ぜひ進めていっていただきたいと思います、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]},{"id":"topic-04","title":"第３２号議案 品川区立心身障害者福祉会館条例の一部を改正する条例","agenda":"第３２号議案 品川区立心身障害者福祉会館条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"見込まれるので、マッサージ室、パソコン室、ボランティア室の必要がなくなったという判断だと思うのですが、それはどういうことでしょうか、ご説明をお願いいたします。","respondent":"中山障害者福祉課長","answer":"法律が変わる中で、平成１９年には、品川区障害者生活支援センターを、そちらにあわせて開設しておりますことと、平成２１年度には、身体障害者デイサービス事業と知的の通所更正施設を合わせまして自立訓練センター、生活訓練・機能訓練事業ということで。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"確認","question":"同じく確認なのですけれども、そうすると、旧条例で謳われている心身障害者福祉会館の中で行っていたボランティア室、パソコン室、マッサージ室の利用と、その利用されていた方々に対しては、その全てが、今おっしゃったように自立訓練センター等々の中に吸収されたのでしょうかという確認。ですから、利用される方々の不便等はあるのでしょうか。その確認をお願いいたします。","respondent":"中山障害者福祉課長","answer":"あわせまして、平成２１年と平成２４年から、それぞれの部屋の使用を見直しているところなのですが、その理由につきましては、利用いただいている団体の方々とも十分にお話をさせていただいて、ご理解いただいたうえで変更してきたところです。","id":"exchange-041"},{"speaker":"松永委員","kind":"質問・要望","question":"１点お伺いしたいのですが、資料の３分の２のところで、部屋が３分の２に縮小されて、料金が安くなったということをお伺いしたのですけれども、では減った分は何に利用されているのか、ご説明いただきたいと思います。","respondent":"中山障害者福祉課長","answer":"変更前が約１２５m2あったところ、変更後は８１m2となっております。この残りの部分につきましては、地域活動支援センター「逢（あえる）」として、今活用されているところです。","id":"exchange-042"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それぞれ条例の左のほうの書面の上の段の、ボランティア室とパソコン室とマッサージ室がある表で、それぞれ何m2あった部屋なのか、ちょっとお聞きしたいのですけれども、わかりますか。","respondent":"中山障害者福祉課長","answer":"ボランティア室、パソコン室、マッサージ室、すみません、今私のほうはm2数をメモして持ってきていないのですが、マッサージ室はとても狭い部屋になります。多分畳みにして１０畳くらいの部屋かと思います。ボランティア室も同じくらいで、そう広くはない部屋になっております。","id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"ボランティア室は、今は逢（あえる）で使っていると。共同事務室は、７団体と一緒にボランティアの方々が使っている。録音室とパソコン室が……それぞれの今の用途を、もう一度教えていただいていいですか、すみません。","respondent":"中山障害者福祉課長","answer":"パソコン室は、現在は自立訓練として使われております。マッサージ室につきましては、生活支援センターとして、主にピアカウンセリングですとか、個別の相談の場として使われているところです。","id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それをこの記載からなくしていくというのは、今、使っている事業での記載を残すという形にはしないで、廃止という形になるのでしょうか。そちらに移っていってしまうというのは、使いづらかったということなのでしょうか。なぜ減っていってしまったのかを伺いたいです。","respondent":"中山障害者福祉課長","answer":"あるいは、国立リハビリテーションセンターですとか、視覚障害の方に特化した訓練を行っている場になりますので、やはりそういうところで訓練を受けられたほうが、より具体的にその方に合った訓練ができるのではないかと考えているところです。","id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"逢（あえる）が使っているときのボランティア室と、訓練室の３分の１、逢（あえる）の事業は、事務事業概要、品川の福祉でも書いてあったのですけれども、これだけの結構な事業をやっていると、ここを拠点として活動されている団体になってくるのか、在駐しているのか、常にいる団体になっているのでしょうか、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"ここには当然、職員とボランティアが配置になって、通っていらした障害者の方たちの日中活動、趣味活動を支えているといった場になります。特段どこかの団体に貸し出しをして、事業として行っているわけではございません。","id":"exchange-046"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"利用されている方の話を聞くと、活動する場がどんどん狭くなってきているという声も伺いました。先日の本会議でも、少し手狭になっているという質問も、ほかの党からも出ていましたけれども、やはりそれだけの声が出されていると感じるのですが、内装などは、いろいろときれいにされているという話なども伺うのですが、そもそもの会館の耐震化はどのようになっているのか、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"そちらのほうを、障害者団体であれは無料でお使いいただけますので、例えば地域センターの会議室ですとか、文化センターとかを併せてご利用いただくことで、地域に障害者の方が出ることで、より多くの活動の場面が広がっていくと考えています。","id":"exchange-047"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうしたら、チェックということは、耐震診断をされたということで、どういうふうに耐震化がされたのか。内装は変わっているのですけれども、外側はあまり耐震化をしているという感じもないと、地域の方も言っていまして、結構古い建物ですので、旧耐震の時代の建物だと思うのですけれども、耐震診断をして、そこでオーケーが出たということなのでしょうか。","respondent":"中山障害者福祉課長","answer":"そのとおりです。耐震診断をして、その結果、新耐震基準に合致しているです。","id":"exchange-048"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"最初は、４階の部屋でマン・ツー・マンで訓練をしてくれていたのに、今は２階の部屋でグループになって、それは法律上なのか何なのか、私もわからないのですけれども、今まで個別でできていた訓練がグループになって、職員も入れ替わる中で、障害を持たれている本人がとてもストレスを感じる状況が出ていると、そういった声は区のほうには届いていないのでしょうか、私のほうでは聞いているのですけれども。","respondent":"中山障害者福祉課長","answer":"サービスの場としての場所を工夫していくということは一つありますが、貸し館としての場所については、障害者に特化した貸し館を増やしていく予定はございません。","id":"exchange-049"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ほかの区民が使える地域センターだったりというところでは、そこのバリアフリーを進めるというのは大変大事なことだと思うのです。ですので、これ以上狭めるのではなく、さらに広げていく方向で考えていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"反対です。やはり障害者の方たちが安心して使える施設をさらに大きくしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]},{"id":"topic-05","title":"第３３号議案 品川区障害者福祉手当条例の一部を改正する条例","agenda":"第３３号議案 品川区障害者福祉手当条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"これは増額になるのですけれども、品川区で予想する増加する予算の金額はどれくらいなのかということ。それから、改めて対象者がどのくらいいらっしゃるかということ。合わせて聞きますけれども、当然、財源が必要なわけであって、これは品川区の一般財源なのでしょうか。例えば東京都全体だったら財調はあるのでしょうけれども、要するにどこからお金が出ているのかということを、併せてお答えください。","respondent":"中山障害者福祉課長","answer":"今回の条例の改正に伴いまして、平成２７年度予算がどれくらい増えるかですが、３億４,７４６万５,０００円の増になります。対象者についてですけれども、まず、第二種手当のところは、身障手帳３級、知的４度、精神障害が１級、それから戦傷病者になっています。","id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問","question":"難病のほうが少し気になったのですけれども、増えるのは、もちろんいろいろな基準があるのでしょうけれども、これも区の財源なのですか。それから、引き上げの金額は、例えば近隣の大田区、世田谷区ありますけれども、それぞれの区で、各区の判断で決めることなのでしょうか、お答えください。","respondent":"中山障害者福祉課長","answer":"難病の指定自体は、国のほうで指定するのですけれども、この福祉手当につきましては、特に国や都から財源が来るものではありません。それから、近隣の各区につきましても、それぞれ各区の事情に合わせて、全体の障害者施策を考える中でこの手当の額についても決定しています。","id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問・要望","question":"例えば財調算定の項目に上げていくとか、やはりいろいろな手段を使って、できるだけ品川区が単費を使わない方向に、当然、このこと自体は、これから続いていくでしょうから、毎年３億４,７００万円余の新規の増加になったわけですから、やはりそのことについては、さまざま財政部門とも調整をとっていただいて、品川区の負担が少なくなるような対応をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、これは対象者に対して個別に周知をされるのか、周知の方法をどうするのか、教えてください。","respondent":"中山障害者福祉課長","answer":"こちらの手当につきましては、広報やホームページでもお知らせはいたしますが、現在、もう既に受給されている方につきましては、そのお手紙の中で合わせて、このように金額が変わったことをご通知していきたいと考えています。","id":"exchange-055"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この引き上げは、私たちもずっと求めてきていましたので、本当に良かったと思っています。改正理由のところで、障害者一人ひとりに即した日常生活の質を高める支援が求められているというところで、日常生活の質を高める支援というのは具体的にどういったことかお聞かせください。","respondent":"中山障害者福祉課長","answer":"それは本当にお一人おひとり違うと思うのです。趣味活動であったり、社会参加であったり、そういったことも、日常生活の中でその人らしい生活ができるように支援したいです。","id":"exchange-056"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"障害を持たれている方は、社会参加の部分でもなかなか難しかったり、一歩がなかなか難しかったりというところもあると思うのですけれども、そういったところでの手当の支援は本当に大きな支えになると、私も思います。対象も、先ほど言われましたけれども、精神も入るということなのか、少し聞き取れなかったので、もう１回お願いします。","respondent":"中山障害者福祉課長","answer":"この第二種手当の中には、精神障害者１級の方が含まれています。これは、品川区と、ほかには杉並区だけのことです。","id":"exchange-057"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"本当にそこも良かったと思うのですけれども、やはり生活の質を高めるための支援というところでは、品川区だけではなくて、まだまだ全体的に低いと私は思います。ですので、先ほど、国への援助という話もありましたけれども、いろいろな手だてで、障害を持たれた方の生活、そして社会参加を応援していく支援ができるように、区としても働きかけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"たけうち委員","kind":"質問","question":"こういう障害を持っていらっしゃる方、結構生活が大変で、生活保護を受けている方もいると思うのですけれども、生活保護を受けている場合、私も勉強不足で申し訳ないのですけれども、実際に入ってくるのが増えるのか、それともこれは全部その中に含まれて、それ自体は、トータルの金額は変わらないのか、そこだけ教えていただけますか。","respondent":"中山障害者福祉課長","answer":"この障害者福祉手当につきましては、生活保護の収入に認定されませんので、プラスとして考えていただければと考えています。","id":"exchange-059"}]},{"id":"topic-06","title":"第４２号議案 指定管理者の指定","agenda":"第４２号議案 指定管理者の指定","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、この場所については、5)の規定によって公募するのが適当でないと認められたということですよね。そうでないところは、当然、公募されているわけであって、公募をするのが適当であると判断する場合と、適当でないと認められる場合の差は、どういうふうにお考えなのですか。","respondent":"永尾高齢者福祉課長","answer":"一般の品川区の指定管理者制度の選定と、福祉関係は特色がありまして、少し違った順番でやっておりますけれども、結果的にはきちんと公募をして、その中で選んでいるという状況になっております。","id":"exchange-060"},{"speaker":"伊藤委員","kind":"質問","question":"私の質問が少し悪かったかもしれませんけれども、福祉のこういう関係のものについて、公募をすることもありますね。この施設については公募するのが適当でないと認めたわけですよね、大井認知症高齢者グループホームについては。ですから、公募をする基準と、公募をしない基準の差は何なのでしょうかということをお伺いしたので、よろしくお願いいたします。","respondent":"永尾高齢者福祉課長","answer":"運営事業者の公募としては、もう既に建設の段階で公募をして決めておりますけれども、指定管理者としての公募は、二重にやる必要がないため省略をしているということになります。","id":"exchange-061"},{"speaker":"伊藤委員","kind":"確認","question":"すみません、確認ですけれども、この施設を建設するときから、恵愛と何かしらそういうやりとりがあったということなのですか、それを確認したいので、改めて答弁をお願いいたします。","respondent":"大串福祉計画課長","answer":"その３者について審査を行ったうえで、運営事業者、それから設計事業者を決めたといったところで、こちらについては、平成２５年５月に事業者の決定の報告ということで、厚生委員会のほうにはご報告をさせていただいているといった経過になっております。","id":"exchange-062"},{"speaker":"たけうち委員","kind":"質問","question":"４月以降の予算のほうにもかかってしまうといけないのですが、プレス発表などでは、この認知症のグループホーム、事業者のほうが利用料金を下げる場合には、区のほうで２万４,０００円を上限に何かやるというのが、まだ決定はしていないですけれども、出ていますよね。それとも、あくまでそれは決まってから、その事業者に任せるのか、どんな考えなのですか。","respondent":"永尾高齢者福祉課長","answer":"事業者が手を挙げていただかないと、区としてもなかなかできないところがありますので、今、運営しているグループホームについては、全部事業者あてに情報提供をしています。","id":"exchange-063"},{"speaker":"向委員","kind":"質問","question":"ただ今回、５年間の指定が決まると、事業者もそれなりにやはりしっかり頑張っていただかないと、運営が難しい点もあるし、区としての意気込みというか、サポートもそれなりにしていかないと、５年経った後に、この事業者もやはり苦しいとか、ほかにもなかなか手を挙げてくださる方がいないとか、そこまで窮地に陥るとは私も考えているわけではないですが、その辺りをどのようにお考えか。","respondent":"大串福祉計画課長","answer":"今後、運営といったところで、今、予算をご提案していますけれども、家賃の助成等々、こういったところを含めまして、区のほうといたしましても、この法人が健全に運営をしていけるような形でのサポートについては、引き続きやっていきたいと考えているところです。","id":"exchange-064"},{"speaker":"向委員","kind":"確認","question":"一つ確認ですけれども、私の記憶が確かだとすると、基本公募によらないでというところで、もともと品川区内の事業者にお願いするという話でしたよね、それだけ最後に確認させてください。","respondent":"大串福祉計画課長","answer":"平成２５年１月に公募の要領を発表したのですが、そのときに、区内で同種の事業をやっているという形での公募になっていました。逆に言いますと、本社が他の区にあったとしても、品川区内での運営実績があるという形での公募になっていたと記憶しております。","id":"exchange-065"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"株式会社が指定管理者になるというところでは、私たちはやはり、区立の福祉施設なのであれば、区が運営をしていくということが一番望ましいと思っているのです。それがあるなら、それを私たちがどのように知ることができるのか、教えてください。","respondent":"大串福祉計画課長","answer":"今後、こちらの運営状況等々につきましては、当然、指定管理ですので、モニタリングを実施させていただいて、その運営実績、あるいは経営実績等々についてのチェックは、今後ともやっていく考えです。","id":"exchange-066"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そういう面で、人材がなかなか確保できなかったりという問題が生まれてきていると思うので、社会福祉法人もありますけれども、これからも株式会社でさらに広げていくという考えで、福祉の施設をまた同時に進めていくということなのか、株式会社もどんどん入ってきてもらいたいという姿勢なのか伺いたいと思います。","respondent":"大串福祉計画課長","answer":"株式会社であろうと、社会福祉法人であろうと、それが良質なケアをしていただければ、それはそこに入居される方の福祉の向上につながるところですので、そこについて、我々が問題とするのは、どういったケアをしていただいて、どういった福祉の向上を図っていただけるか。","id":"exchange-067"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それがなかなか見えてこないというのが株式会社だと思うのです。賃金実態だったり、全ての株式会社の状況を品川区は把握されて、特段低いようなところがあれば、指導なり、通告なりが何かできる状況にあるのか。そういう把握ができる仕組みがあるのかどうか、伺いたいです。","respondent":"大串福祉計画課長","answer":"そうした中で、例えば賃金上の不利益があって職員が辞めるとなれば、離職率の関係が出てまいりますし、ひいては、そこに入所されている方のケアの質の低下といったところで表われてくるところですので、その辺については、区立という施設の性格上。","id":"exchange-068"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"そうしたら、モニタリングを毎年出されますよね、各社会福祉法人に出している。あの形を株式会社にもやられているということですよね。それをこの場にも出していくということが必要だと思うのですけれども。","respondent":"大串福祉計画課長","answer":"モニタリングの結果については、ご報告をしています。","id":"exchange-069"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やはり全ての品川区内の福祉施設について、しっかりと見ていく必要があると思いますので、株式会社にこれ以上任せていくというスタンスが、これから高齢者が増えていく中で、もうけ優先の株式会社になってきますので、そこは本当にしっかりと、区の施設なのであれば、そして福祉を増進させるのが自治体の本旨なのですから、そこはやはり区が責任を持って進めていくべきだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]},{"id":"topic-07","title":"第４３号議案 指定管理者の指定","agenda":"第４３号議案 指定管理者の指定","exchanges":[{"speaker":"石田（ち）副委員長","kind":"質問","question":"前回、契約したのはつい最近だったと思うのですけれども、そのときには、この変更は知らなかったということですよね。それで、突然出てきたと。中身は変わらないのか、そしてスタッフは変わらないのか、伺いたいと思います。","respondent":"川島健康課長","answer":"実は、約１年前に契約更新をさせていただいたときには、予測できない事業の移管だったということです。","id":"exchange-071"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"名前が変わっただけというところでも、構成員が変更されているわけですから、代表取締役社長なども変わってきているわけですよね。そういう中で、突然変わるというのが、株式会社だと思うのです。それを予測できないというのが株式会社の指定管理だと思うのです。では、何も変わりないということで、もう１回確認させていただきたいと思います。","respondent":"川島健康課長","answer":"事業の構成員に変わりがないです。","id":"exchange-072"}]},{"id":"topic-08","title":"平成２７年請願第５号 介護保険料の値上げ中止と特養ホーム増設等を求める請願","agenda":"平成２７年請願第５号 介護保険料の値上げ中止と特養ホーム増設等を求める請願","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"何点か確認させていただきたいのですけれども、まず請願の大きな項目であります介護保険料の値上げ中止と特養ホームの増設等を求める、という表現になっているのですけれども、特別養護老人ホームの増設をするためには、当然、財源が必要であって、この財源には、いわゆる一般財源の投入は認められていないというわけです。そういう認識でよろしいのでしょうかという確認を、まずお願いいたします。","respondent":"永尾高齢者福祉課長","answer":"保険料の算定にはさまざまな要素が入ってきますけれども、特別養護老人ホームを建設することによって、当然、それにかかるサービスの経費については、介護保険財政のほうの財源を使いますので、影響は出てくると考えております。","id":"exchange-073"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、この表題自体が、特別養護老人ホームの増設を求める請願と同時に、値上げ中止となっているわけだから、そうすると、これは保険という制度を冷静に考えていくと、ある意味、できないわけではないですか。これは特別養護老人ホームの増設を求める請願で、そういう状況になってもし増設する場合、どこからお金を持ってくるのかと思うと、何か道があるのかという確認を、まずお願いします。","respondent":"永尾高齢者福祉課長","answer":"先ほど申し上げましたとおり、一般財源からは入れてはいけないとなっておりますので、そうすると、あと残されたところは介護給付費等準備基金という、そこの基金しかないと認識しています。","id":"exchange-074"},{"speaker":"伊藤委員","kind":"質問・要望","question":"つまり、財布が限られているわけではないですか、このことについては。私たちも当然、福祉は増進させていきたいし、こういう施設をつくっていきたいと要望させていただいてはいるのだけれども、だけれどもやはり、品川区の中で土地を買って建物を建てて運営していくのは大変なお金がかかるわけであって、おいそれと、はいわかりましたと言えないところがあることを、まず指摘させていただきたいということ。","respondent":"永尾高齢者福祉課長","answer":"その財源を、どこからどういうふうに充当して、どういうふうに配分していくかというところが一番重要なところであって、そのときに、今現在のことを考えるのではなくて、１０年後にどんどん高齢者が増えていくということが、現状わかっていることも考えますと。","id":"exchange-075"},{"speaker":"伊藤委員","kind":"意見","question":"対象者が増えていく、お金は増えていく、サービスは増やしていかなければいけない。品川区はもっとそういうＰＲをしてほしいのですよ、介護保険事業としては、こんなことをやっていますよ、これだけのことをやって、これだけの費用が必要なのだと。あわせて、来年、再来年、１０年後、３０年後、こうなっていくから、必要事業が増えていくと。","respondent":"永尾高齢者福祉課長","answer":"皆さんに理解していただいて、皆さんで力を合わせて維持していくという仕組みになっておりますので、区といたしましても、今までもやっておりますけれども、もう少しさらにわかりやすい説明を行うように心がけてまいります。","id":"exchange-076"},{"speaker":"伊藤委員","kind":"質問","question":"説明が欲しいと思うのです。品川区民の方々の今から１０年後、２０年後を見据えたうえで、今の介護保険料を設定したということから始まっていって、金額はこれくらいですと、それに対してできるだけ低減するために基金をこれだけ使いましたと、それでもなお足りないので、これだけお願いしますというような、そういうわかりやすい説明をしていただきますようにお願いしますが、最後に答弁をお願いします。","respondent":"永尾高齢者福祉課長","answer":"やはり結果だけを最初に説明しまうと、なかなか納得いかないことだと思います。これからのこと、将来のことや、今現状置かれている状況、そういうところもきちんと丁寧に説明をしていきたいと考えています。","id":"exchange-077"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"一つ目が、介護保険料の基準額値上げ中止と住民税非課税者に引き下げを、ということで、私は、先ほどの条例でも値上げは中止してほしいということで反対させていただきましたけれども、介護保険の骨子案のところでの段階別の人数を教えていただけないでしょうか。ですので、そこの立場で見解を伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"一度、一般財源を投入してしまうと、今、非常に問題になっている国保会計のようなことにもなりかねないので、やはりそういうところは慎重に考えていかないといけないと思っているところです。","id":"exchange-078"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"先ほども言わせていただいたのですけれども、基金はたくさんありますよね、品川区は。ですので、本当に今は緊急事態だと思うのです。そのときに備えると言っていますけれども、今使っていくべきときなのではないかと思うのです。そして、あなたはチェックリストですよ、あなたは認定ですよというふうに割り振っていく基準は何なのか、お聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"基金の残額につきましては、現状、国の段階よりも率を下げるというところで、今回、かなり投入しています。その結果、残額が６億２,６００万円程度になるというところで、やはり今後のことを考えると、これ以上投入するのは危険だと考えているところです。","id":"exchange-079"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"サービスは提供されるとおっしゃるのですけれども、やはり専門家によるサービスが取り上げられていくと。要支援者の支援のサービスというのをどう考えているのかと、本当に疑問に思うのです。専門家によるわずかな支援で、長期間自宅での自立生活を続けている人はたくさんいます、要支援の中で。こういった方々からサービスを奪うという、この区が考えるサービスというのはどういった考えなのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"生活援助の部分につきましては、その内容にもよるのですけれども、専門家ではなくても済むものについては、専門家にまでいかないような方、ヘルパーの資格がない方でもいけるような、そういうようなサービスへ動かしていくというところで、実際に、基本チェックリスト。","id":"exchange-080"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そういった形で、品川区も要支援のサービスをしていくということなのでしょうか。ですので、あなたは認定ではなくて、チェックリストなのだというふうに促していくという、ここがケアマネジャーの腕の見せ所なのだというような、そういった実態も出されているのですけれども、こういった状況をどうお考えでしょうか。","respondent":"永尾高齢者福祉課長","answer":"もしそういうケアマネジャーがいたとすれば、やはりそれは少し認識が違いますので、区のほうでしっかり指導していかなければいけないと考えています。生活支援の関係ですけれども、現在、生活機能向上支援事業というのを、今もうやっております。","id":"exchange-081"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"受け皿のところですけれども、さわやかサービスだったり、ほかにもあるのでしょうか。少しそこら辺を、どういったところを受け皿として考えているのか伺わせていただきたい。それから、やはりそこの人材の確保が、今現在どういうふうになっているのかを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"ただ、現時点では、まだ支援者の確保が不十分だというところもありますので、この辺については、平成２７年度中に実際の担い手等ともお話をしながらつくり上げていく予定になっております。ですので、４月１日から移行するのは、訪問介護と訪問型サービスＡの部分だけです。","id":"exchange-082"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"この間、品川区は整備率が１％未満ですので、これが１.５倍の補助になって、７億５,０００万円入ってくると思うのです。ですので、２０億円程度の特別養護老人ホームだったら、１２億５,０００万円で、ここに財調も加わってくると、さらに負担は少なくて済むのではないかと思うのですけれども、この間の八潮や杜松小学校跡の特別養護老人ホームに財調はどのくらい入れられたのか、わかるでしょうか。","respondent":"大串福祉計画課長","answer":"広町のところの再開発事業地のお話です。あそこはあくまでも再開発事業用地ということで、区が所有しています。先般の本会議でもお答えしましたように、あくまでも保育園については暫定地活用といったところで整備を検討されていると伺っております。","id":"exchange-083"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"広町の区有地を、開発ではなく特別養護老人ホームに、福祉施設にと求めますけれども、ここはいかがでしょうか。それから、介護報酬減額の中止を求めています。それでも親の介護に巨額のお金がかかっていくというところでは、介護心中なども出ていますので、介護報酬の減額は中止して、やはり増やす方向で国に求めてほしいというのが、この請願でもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"はい、まとめます。それで、こういった補助も入るわけですから、全てが品川区独自のというわけではありませんので、そこにしっかりと税金を出していくということが必要だと思います。改めて、広町の暫定地域を、開発ではなくて特別養護老人ホームにと求めます。それから、介護報酬減額ではなくて中止こそ国に、増やすよう求めていただきたいと思いますけれども、改めていかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ですので、思いは一緒なのではないかと思うのですけれども、各委員の皆さんも、これ以上の介護難民を出すというこの状況、こういった北区の例は決して北区だけの状況ではないと思いますので、こういった状況を見て、特別養護老人ホームは高いから建てられない、我慢してくださいと言うのかと思うのですけれども、委員の皆さんの意見を聞かせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"たけうち委員","kind":"質問","question":"公明党と名指しで言われたので少しお話しますけれども、我々もこの間の代表質問でもそうですけれども、例えば小規模特別養護老人ホームを増やしていくべきだとか、特別養護老人ホームを建てたいという気持ちは、ここにいる委員みんな同じなのですよ。そういうことは、何で共産党は言わないのですか。そういうところにうちの党のことを言われたくないです、申し訳ないですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"私は思いが同じだと思って、２０２５年までに倍増させると書いてあったので、この１０年間でどうやって倍増させるのか、そして増やしていくのかと思ったのです。２３区で下から２番目と言われていますけれども、それ以上にサービスは受けられない。そして、サービスは２３区トップで外される、こういった状況があるもとで、介護報酬も減額されれば、事業所も成り立たないという状況なのです。","respondent":"永尾高齢者福祉課長","answer":"きちんとしたケアマネジメント、どこの区よりも丁寧な相談事業、相談支援をやっていると自負しておりまして、そこの中で、ご家族の状況やご本人の状況も聞いたうえでサービス計画を立てております。ですので、より丁寧な対応というふうに認識していただきたいと思っています。","id":"exchange-088"},{"speaker":"向委員","kind":"質問・要望","question":"それはほかの委員も同じだと思います。この４年間も、しっかり基金についての考えとか、高齢者福祉に対してとか、本当にご努力とかも伺ってきました。できれば重ねての質問はしたくないのですけれども、午前中も、災害時に基金を全部使ってしまったときとか、いろいろな不安を、理事者からもたくさん説明をいただきました。それ以外の面でも、よくご説明をいただいていますが、改めてお伺いします。","respondent":"永尾高齢者福祉課長","answer":"ただその基金をただずっと貯めているわけではなくて、やはり今回なども、国のほうの軽減が少し遅く延びたというところで、その分をさらに投入いたしまして、結果的に約６億３千万円ほどの残になりますけれども、対応をしています。","id":"exchange-089"},{"speaker":"向委員","kind":"意見","question":"基金については、使わないといけないときには、本当に使わなければいけないと、私も思っています。もちろん私たちも将来に向けて不安も多いので、このあたりは引き続きのご努力を重ねてお願いしつつ、以上で終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これは誰が何と言ってもお金が必要なわけですから、それを税金で担保するのか、国からのお金で担保するのか、さまざまな議論があるのだけれども、でも、これから高齢者はしばらく増え続けていくわけであって、今から１０年後、２０年後、３０年後の品川区も支えなければいけない。この請願については、本日結論を出していただきたいと思いますし、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"たけうち委員","kind":"意見","question":"午前中、この議案についても、我々は賛成しておりますし、そういう面では、今さら中止というわけにはいかないということと、特別養護老人ホームについても、増設は願っておりますけれども、まだあてがない中で、計画だけ、ただ数だけ机上で示すのは、逆にそれができないときに、待ち望んでいた方にとっては非常につらい思いになるのかという部分では、やはり責任を持ってやるには。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"向委員","kind":"意見","question":"私も先ほど意見を申し述べたので、簡潔に申し上げます。本日結論を出すということで、会派としても申し上げます。理由としては、午前中の第２７号議案のとおりですが、どのように区がこれまで努力をして、今回も基金を取り崩せる分は取り崩して、介護保険料が今後変わる部分、変更を行うために力を注ごうとしているか、よく理解できております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"今日結論を出して、採択を主張したいと思います。基金の問題も、８億円残ると言っていたものが１７億円になるわけです。ですので、基金は潤沢にあると、私は思います。ですので、住民の暮らし、福祉を支えていく、その力を発揮するための４カ所目の適地、当然４カ所目が欲しいと選定しているというところの具体化を求めて、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"鈴木（博）委員","kind":"質問","question":"私は４年間、厚生委員会にずっと出ていまして、一連の議論は聞いてきました。品川区の福祉政策に関しては、非常によくやられていると高く評価いたします。結論を出す、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/866699?Template=document&Id=3408#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":73001,"voices":284}},{"id":"h27-20150223-8","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"建設委員会","time":"午前１０時００分～午後 ３時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を83件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"していないね。シャッター音については、格別の留意をしていただきたいと、これはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"の１「議案審査」を行います。 初めに、(1)の第３４号議案、品川区手数料条例の一部を改正する条例","agenda":"の１「議案審査」を行います。 初めに、(1)の第３４号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"2)のところの許容応力度等計算（ルート２）、赤い字で書かれていますが、このルート２に変更をされると、判定基準は従前と比較してどうなるのか、建築主事が確認審査を行うということでは、資格は取りましたよということなのですが、内容的に緩くなるのではないかなと思うのですが、その辺、チェックする中身の基準とかがどうなるのか、教えていただきたいのが二つ目です。ここまでお伺いします。","respondent":"鈴木建築課長","answer":"質問の２点目、ルート２に変更になるとどうなるのかですが、この資料２の下段、建物規模、高さ等々に応じて、あるいは構造計算、構造設計者の判断によりまして、この計算ルート、どのルートを選定するかというのは、基本的にはその建築主の判断ということになりますけれども。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"誰が、一体どう判断をしてこのエリアを決めて、この特定施設が大事であると、どういう基準でその辺は決めていくのか、ちょっと疑問が残るので、そこを教えてほしいのと、特定という言葉自体が、この特定というのはどういうことを意味するのか教えていただきたいのと、あと特定用途誘導地区は、ここにエリアが指定されて、誘導施設が誘導されて、容積率がアップをされていくのですが。","respondent":"鈴木建築課長","answer":"構造計算のルート２の審査内容につきましては、従前と内容については全く変わらない内容になっております。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"意見","question":"特定というのはどういう意味なのかというのを改めて聞きたい。","respondent":"鈴木建築課長","answer":"すみません、説明が漏れておりました。特定用途としましては、生活に必要な施設というところで、医療ですとか福祉あるいは商業といったところが定められているところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"続けてお伺いをします。２の長期優良住宅の認定事務というところなのですけれども、登録住宅性能評価機関等の技術審査による適合証から評価書に変わるということなのですけれども、この中身がよくわからないのですね。違いがどこにあるのか、審査の内容に違いがあるのかどうかと、あとやはり区がどう関与していくのかという中身を教えてください。","respondent":"鈴木建築課長","answer":"中身についてですが、適合証、そのほか、住宅性能表示制度の評価書という中身ですが、中身については構造躯体の劣化対策ですとか、耐震性、高齢者等対策、省エネルギー対策等々、建物を長期に使っていただくための措置がどうとられているかといった中身で、この認定を受ければ。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５分の４ということで、残りの５分の１の意思が反対であっても、強硬に売却をされて、税制優遇によってその敷地がディベロッパーによって買い取られて、上に高いものを建てていかれるというところにおいては、本当に従前居住者がそこで耐震性がそぐわない建物でも修理補修をして長く住み続けたいという方向にいかなくなってしまうと理解をしているのですけれども、この点はいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"５番目の高度管理医療機器販売業・貸与業の許可等にかかわる、そこのところなのですけれども、許可等にかかわる権限が東京都から特別区に移譲されるということなのですけれども、許可の内容に変化があるのかどうか。その１点と、あと手数料に変化があるのか、区民にとってどこか変わるところがあるのかどうかを教えてください。","respondent":"高山生活衛生課長","answer":"手数料につきましては、先般区への移譲に当たりまして検討した結果、当初においては、東京都において現行定めている手数料と同じ金額で、改めて積算をし直したのですが、同じ金額において当初はスタートするというふうに考えているところです。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"１番の建築基準法のところで、施行期日が1)2)は平成２７年６月１日、3)は平成２７年４月１日、このタイムラグというのは２か月間です。その事情を教えていただきたいのが一つ。それと、この手数料条例が、先ほど権限移譲というお話がありましたけれども、手数料条例が区に移譲されることによって、大体区は手数料の増収をどれぐらい見込まれているのか教えてください。","respondent":"鈴木建築課長","answer":"この施行に伴って手数料を準備したところでございまして、構造計算のところにつきましては、おおむね規模にもよりますけれども、来年度２件あるいは１件程度見込んでいると、制度スタートですので、その程度今のところ見込んです。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"確認","question":"一つだけ教えてください。現場はちょっと私もわからないものですから、これによってどう合理化が図られるのか、スピード化が図られるのか教えてください。","respondent":"鈴木建築課長","answer":"民間につきましては、区のほうで今１８機関ございまして、これまでですと、そこと区のほうで、民間機関と年間契約を結んで、バランスよく区のほうで送っていたです。それが申請者みずからが申請機関を選択できるというところが改正の一つであります。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"最初のほうの説明はわかりました。では、区が指定するのですかね、１８民間機関の中から建築主が選べるということですね。わかりました。結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"先ほど一つ、長期優良住宅の認定事務のところで、適合証と評価書に違いがないということだったのですが、区の関与がどうなのか再度お聞きしたいのですが、その点を答えてください。","respondent":"鈴木建築課長","answer":"関与につきましては、認定申請の内容を審査するですので、従前と変わらないです。","id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"今日は手数料のところなのですけれども、大きく言ってしまうと、各セクションでかなり勉強することがいっぱいあろうかと思うので、私は何を言いたいかといえば、区民サービスに関して支障が出ないように、新規のことですので、そこをうまく円滑に運んでいただきたいので、もう一回セクションごとに、これに関しての考えだけ。","respondent":"鈴木建築課長、矢木住宅担当課長、高山生活衛生課長","answer":"専門的な大分踏み込んだ内容、改正が行われておりますので、変更等につきまして、事務所協会、特にルート２、品川区でも受けられるようになりますので。私の所管する事務に関しましては、住宅ですので、関係諸機関の動向を見つつ、また管理組合のご希望も丁寧に聞きつつ、相談も含め。新たな歳入確保という点においても、先ほどご答弁申し上げませんでしたが、区の歳入見込みとしては。","id":"exchange-012"},{"speaker":"原委員","kind":"質問","question":"これは質問ではなくて、お願いごとなので。民間以上に、逆に区に持っていきたいなと思うように、その辺を優しく指導を、というのは、多分わからない、逆に言うとわからない方もかなり多く出てしまうと思うので、その辺のところを皆さんもおっしゃっているように丁寧によろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"意見","question":"特定用途誘導地区のところは、理由づけが明確ではありません。理由づけをしたら、いろいろな部分に拡大をされてしまうのではないか、そういった中身をはらんでいると思います。５番目の高度管理医療機器販売業、この問題については、東京都から品川区に、特別区に移ってきたということで、特に問題はないと考えていますので、この問題については賛成です。総じて反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-03","title":"の第３５号議案、品川区立区民住宅条例の一部を改正する条例","agenda":"の第３５号議案、品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"今度かかった五つの区民住宅なのですけれども、実際に現在どのくらい埋まって、ここに戸数が書いてあるのですけれども、どのくらい利用されているのか、空き室がどのくらいなのかというのを一つ知りたいのと、区がこの間、区民住宅が契約任期満了すると延長しないということなのですが、延長しない理由、あと家主からの意見とか要望が出ているのかどうか、その点を教えてください。","respondent":"矢木住宅担当課長","answer":"家主からの要望といたしましては、現時点で少しずつ返還後の対応についてですとか、円滑な返還に向けまして、例えばクリーニングをしてほしいということですとか、募集の方法についてアドバイスをしてほしいとか、そういったことがご要望として出てくるところでございまして。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"結構空室があるのですけれども、せっかくの区民住宅なので、やはりより本当に活用していただきたいなと思っているのですが、募集についての相談とかがあるということなのですけれども、この辺というのは何が足りなくてというか、何が問題となって空き室が多いと考えているのかお聞かせください。","respondent":"矢木住宅担当課長","answer":"空き室が多い理由ですが、一つには家賃が、以前はスライド制ということで、安くもあったのですが、２０年近く経過しまして、施設の老朽化に比しまして、家賃がちょっと相対的に言って高いというご評価なのかなというふうに考えております。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区民住宅は公の施設としての役割を一定持っているので、家賃が高いというあたりでは、区民の皆さんがより安い、低廉な住宅を求めているというところにおいては、任期満了なので廃止はいたし方ないとは思いますけれども、やはり住宅のところにおいては、代替の対策とかが今後必要ではないかなという思いがありますので、意見として述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、桃李邦が１９戸の戸数のうち１１戸が空き室ということでしたけれども、たしか以前のやりとりで空き室率が５０％を超えた場合に家賃を下げるというようなことも考慮に入れていくという話もあった。これは任期満了ということで大分近づいているとは思うのですが、そのほかの特に借上型区民住宅において、現在そのような対象になるようなところがあるのかどうか、これについて教えていただきたいと思います。","respondent":"矢木住宅担当課長","answer":"現時点におきまして、次年度返還するものを除いては空き室率が５０％を超えたものはございません。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回の件に限って、今回たまたまというか、期限が来てしまうところが５０％以上になっているということなのですけれども、以前から区民住宅、特に借上型については、賃料のことはさまざまなご意見を区民の方からもいただいておりますので、５０％というところにこだわることなく、賃料の検討はしていただきたい。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-04","title":"の第３６号議案、品川区建築審査会条例の一部を改正する条例","agenda":"の第３６号議案、品川区建築審査会条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"改正の資料のところに図が書かれていますけれども、建築審査会にて同意ということなのですが、この建築審査会での同意、先ほど支障がない場合において同意というご説明だったのですが、同意の基準は一体どういうものなのか教えていただきたいのと、同意を経て建設とあるのですが、許可の基準、特定行政庁、特定行政庁というのは区と理解していいと思うのですが。","respondent":"中村都市計画課長","answer":"審査会の同意の基準ですけれども、これは審議の内容によってさまざまなケースがあります。例えば、一つは、建築基準法では、建築する際の敷地が２ｍ以上道路に接しなければならないというものがあります。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"議事録はどうなのか、公開なのか、非公開なのか教えていただきたいのですが、この審議会のメンバーの中で決まったことをもって許可をするというところにおいて、特定行政庁の働きというか、チェックというのは、ただ本当に同意に同意をするような理解をされても仕方がないのではないかなと思うのですが、その辺、審査会の中身というところにおいて、この流れから見ると議決は行われるのでしょうか。","respondent":"中村都市計画課長","answer":"もう一つの形としましては、例えば品川区の基準で、接道などが１.８ｍ以上あるものが必要という基準ではありますが、ただそれが１.８ｍ確保できないので、１.５ｍしか接道がないといったものについては例えば避難経路をさらに二つ、あるいは多くなればなるほど。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"意見","question":"意見を添えて反対します。建築基準法以外にマンション建て替え等にかかわる法律によって、新たな容積率緩和、緩やかな中身になって、私はここの流れにいくと、より企業が仕事をしやすい品川区になっていくという中身の流れになりますので、悪法のもとの一定の流れの中での規制緩和なので反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"第４４号議案のほうからお伺いします。第４４号議案のほうで、収入がどのくらいの方なのかということと、暮らし向きというのは、こういう結果になる前にどのくらいわかるものなのか、その辺、先ほども何回も対応しているのですけれども、どの辺でそういう暮らし向き、かなりいろいろな問題をはらんでいると思うのですが、つかめるのかなというところをちょっと教えてください。","respondent":"矢木住宅担当課長","answer":"ただし、その収入申告で、例えばこれがパーセンテージ的に２０％を超えるので使用料が高いから出ませんかとか、そういうのは当然のことながらそれぞれの暮らし向きがありますので、申し上げられないので、実際上は滞納が発生してから、生活状況をお聞きする中で判明したものです。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"第４４号議案と第４５号議案、いろいろな事情がおありだと思うのですけれども、区民住宅全体のところで、滞納の基準がちょっとよくわからないのですが、滞納状況というのはどのくらいあるのでしょうか。","respondent":"矢木住宅担当課長","answer":"こちらにつきましては、７月から６か月連続上回っている。わずかながらではありますが、早期着手ということで、効果が出ているものと認識しております。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと専決処分について、ちょっと基本的なことを教えていただきたいのですが、議会を招集する時間的余裕がないことが明らかになって専決処分をしましたということなのですが、この議会との日程的な絡みで、基本的なルールが、決まりがどういうところにあるのか、基本的なところを教えていただけたらと思います。","respondent":"矢木住宅担当課長","answer":"こちらにつきましては、使用許可を取り消した段階で訴訟の準備をするわけですが、これにつきまして、ちょっといろいろ住民票を取得したりとか、案件によっていろいろありますので、大体１か月から２か月程度の準備期間を設けておりまして、その前に専決をするということの中で。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"このファミーユ西五反田東館というところですけれども、今２件出てきましたが、実は滞納が進んでいて、今後もこういうことが出てくるのか、巨大な物件でありますので、そういったことが今あるのかどうか、お答えができる範囲で教えていただければと思います。","respondent":"矢木住宅担当課長","answer":"お忘れではないですかということで納付書をお渡しするということで対応はしております。","id":"exchange-026"},{"speaker":"大沢委員","kind":"確認","question":"第４５号議案で、ちょっとすみません、確認を、契約された方が外国籍の人だとちょっと伺ったのですが、そこの確認をさせてください。","respondent":"矢木住宅担当課長","answer":"失礼いたしました。外国籍ではなくて、現在は帰化しておられる方で、平成１７年に帰化された方です。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"同じ駅とはとても思えない。南口の商店の方にも伺いましたけれども、一番の願いは、最寄りの駅にしてほしいとおっしゃっていました。この言っている意味、わかるでしょうか。都バスで品川駅まで行くとか、隣の青物横丁の駅を利用するなど、本来この駅を使うべき人が避けているといった状況で、ぜひ最寄りの駅になるようにしてほしいということで、地域の人が当たり前に使える駅にしてほしい。","respondent":"中村都市計画課長","answer":"京急の働きかけにつきましては、まず区民の皆様からご意見をいただいたときはもとより、また京浜急行につきましては、それ以外にもさまざまな打ち合わせの席がいろいろあります。そういった機会を利用して声かけを行って、お願いしますということを継続して行っております。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"区民の声があったとき、打ち合わせの席、結構あるのでしょうか。継続してと言っていますが、この請願にあるようなエレベーターの設置の指導というか、話し合いは実際何回ぐらい行われているのでしょうか。","respondent":"中村都市計画課長","answer":"私の知るところでは、昨年の４月以降ですけれども、区民の方からお問い合わせいただきましたのが３件、それからあと、打ち合わせにつきましては、少なくとも七、八回程度は区役所において行われております。そういった機会を利用して、会うたびごとにお願いをしているです。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"同一の駅で、京急はいろいろ言っていますが、２か所目でも、都は拒まずに補助金を出して支援しますよと言っているにもかかわらず、京急はこういった幾つもさっき、５点ですかね、課長が読み上げられた設置に対する考えを出しているということで、住民の方は、京急が住民の意見を聞く気になれば、設置は十分可能であると、こう言っていらっしゃるのですけれども、やはりこの状況を打開するためには。","respondent":"中村都市計画課長","answer":"しかしながら、私ども区においては、区民の皆様からの利便性への要望につきましても声が届いておりますので、やはり少しでも優先順位を上げていただくように引き続きお願いをしていくということを今後も続けていくというところが大切なのかなというふうに考えてあります。","id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"ここの新馬場駅は、もともと北馬場と南馬場という二つの駅があったところを統合して一つにして、その二つの駅の真ん中にホームをつくったものですから、それぞれ上がってから相当歩かなければいけないと昔から言われているところであります。私たちは、この指導という意味、働きかけと相当違うように感じるのですけれども、理事者は指導というのをどういうふうに捉えているのでしょうか。","respondent":"中村都市計画課長","answer":"この新馬場駅につきましては、この施設はバリアフリー法において、鉄道の駅としましては、バリアフリー化の経路を１以上確保することということで、法律では適合しているというところから考えますと、この指導というのは、ちょっと慎重を期すべきものというふうに考えております。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問・要望","question":"私たちとしては、働きかけていただく、これは今お話を伺いましたけれども、区民の方から意見をいただくたびに働きかけていますよ、また昨年４月以降七、八回打ち合わせして、そのたびにお願いをしていますよ、働きかけていますよと、これを私たち区民の声として後押しするのだということで請願が出されたのかなということで、働きかけていただきたいというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この問題については、今起こったことではなくて、私どもも数年前から何度もこれについては区民の方からご要望を頂戴しておりまして、議事録をさかのぼれば、平成１５年から会派の、今は亡き嶋邦子議員が要望の質問をしております。その後、会派の山元けい子議員、そして山路良成議員、そして私も含めて計７回ほど一般質問、予算特別委員会、また決算特別委員会においてもこれは求めてきたものであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面では、バリアフリーの精神が本当に欠けている南口であるなという認識をまず持っていただいて、やはり南口を利用しようが、北口を利用しようが、安心して誰もが使える駅にしていただきたいという強い願いであると私は受けとめていますので、行政指導を強力にしてほしいということではなく、区が進めているマスタープランに書かれている。","respondent":"中村都市計画課長","answer":"指導かお願いかですけれども、やはり行政指導そのものは確かに難しいかもしれませんけれども、お願いのほうは、強いお願いとして引き続きお願いをしてまいります。","id":"exchange-034"},{"speaker":"原委員","kind":"質問","question":"私は、請願第１号と請願第８号、全体的には本当に同じような受けとめ方をしました。ですから、やはり働きかけというのが妥当なのではないかなと。ですから、なるべく行政の方には民間にわかる言葉でお伝えを願いたいのですけれども、これに関しましては、賛成と趣旨かなぐらいの、ちょっとここは大事なところなのですけれども、賛成、趣旨という感覚を私は持っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"大倉副委員長","kind":"質問・要望","question":"まさにこれから東京オリンピック・パラリンピックを目指して発展のために、また利便性の向上のためにもぜひ設置に向けて働きかけていただきたいと考えています。やっぱりそこで、この指導ですが、先ほど課長の答弁でも行政側としては慎重な表現でしていかなければいけないだろうというお話もありましたので、その辺を考えながら、採択に向けていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"松澤委員","kind":"質問・要望","question":"結論を出していただきたいと思います。２本の請願を読み比べてみました。その中で、二つの請願の中で、今紹介議員のあくつ委員から伺いましたけれども、私たちの議員が賛成して署名していて、あつく委員が署名しているほうは、周りの町会長だという話を伺いました。やはり地域が望んでいるということ、私たちはこちらの請願第１号のほうは、採択というふうにとっていただきたいと思います。趣旨を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"請願第１号に関しては、先ほど意見を述べさせていただいたとおり採択をしたいと思います。請願第８号につきましては、思いは本当に同じだと思いますが、先ほど原委員からもありました。ですから、ちょっと指導ということが、行政指導というふうにやはり、読むなと言われても、これは指導ですから、非常に難しいものがありますので、先ほど慎重にというご答弁もありましたが、趣旨採択ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"大倉副委員長","kind":"質問・要望","question":"私たちも両方の趣旨というのは非常に理解するところでもあり、推し進めていっていただきたいものでもあると考えております。そのため、こちらの「働きかけていただきたく」のほうは採択をさせていただいて、こちらの「強い指導」というほうでは、この思いも非常に理解できるところでありますので、趣旨でお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"共産党としては、請願第１号も請願第８号も区民の皆さんから一刻も早くバリアフリー化を進めてほしい、区に本当に働きかけを強めていただきたいという区民の願いのあらわれであると思っています。今日結論を出していただきたいのですが、請願第１号に対して採択、請願第８号に対しても同じく採択をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"請願第１号のほうは皆さん一致をしているのですが、請願第８号に対して趣旨と、うちは採決を主張していたのですが、趣旨採択で一致をするならば、趣旨採択で一致させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-05","title":"平成２７年請願第２号、補助２８・２９号、放射２号線の事業計画の白紙撤回及び家屋の倒壊、火災予防中心の防災推進を求める請願","agenda":"平成２７年請願第２号、補助２８・２９号、放射２号線の事業計画の白紙撤回及び家屋の倒壊、火災予防中心の防災推進を求める請願","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"冒頭、委員長からご説明いただいたのですが、意見陳述の取扱い、もう一回、私としてはぜひ地域の皆さんの意見をしっかり聞いていらっしゃる皆さんだし、不服審査請求も出されている方々からの意見陳述なので、冒頭にご意見を聞いていただいて審査をしたほうがより中身が深まると思うので、その辺の取扱いについてお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"審査の後ですね。これは変えることはできないのですか。委員長のご判断ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問","question":"そうですか。ぜひ、私は事前に諮っていただいて、意見陳述の後審査をしたほうが、より中身が深まると思うのですが、皆さんにちょっとご意見を聞いていただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私はここに書かれている今日の請願趣旨、請願項目、どれ一つをとっても本当に地域の皆さんの切実な声、願いであると受けとめて納得をしているところなのですが、２００２年、この補助２９号線、廃止を求める意見書が全会一致で決議、２９号線の計画廃止を強く要望したわけですけれども、ぜひこの立場に各議員の皆さんに立っていただきたいという切実な項目がこの２点目なのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちなみに、私は２００２年のときには、まだ議席をいただいていなかったので、その場にはおりませんので、そこのところを教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"その後、ご存じのように予算やさまざまな体制に取り組みまして、防災を進めてきましたので、その当時の区議会の考え方については、私から申し上げるものではございませんが。","id":"exchange-046"},{"speaker":"大沢委員","kind":"意見","question":"今言った２００２年当時、２０１１年当時、行政が防災に対する取り組み、あるいは取り組みに付随する事業について、さまざまな議会、行政を含めた部分で意識が変わってきたと私は今課長からの説明を聞いて思ったのですが、そのような捉え方でいいわけですよね。","respondent":"鈴木防災課長","answer":"委員のお尋ねのとおり区としてもそれ以前にも増して防災に力を入れる、特に平成２４年４月に東京都から首都直下地震の具体的な被害想定が出されました。そのことで、より具体的な対策の方向性が出ましたので、かなり防災対策に関しても充実をさせてきたです。","id":"exchange-047"},{"speaker":"大沢委員","kind":"意見","question":"議員側についても、２００２年当時の全会一致という部分と、２０１１年を境に現時点での防災に対する考え方は違ってきていると思いますので、これをもって２００２年を根拠にしながらこの話を進めるというのはいささか乱暴な気がします。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問","question":"請願の趣旨、項目のところで、項目で言うと４番、1)と3)住宅の耐震化と初期消火の成功率向上、この件については、区は一生懸命取り組まれていることは私も承知をしているのですが、2)の通電火災を防止するための感震ブレーカーというお話があるのですけれども、助成制度云々というよりも、この通電火災の防止について、区のほうで何か取り組まれていることがあるのか。","respondent":"鈴木防災課長","answer":"区としましては、家庭内の防災の備えですので、個人の財産、もしくは賃貸の建物についてのブレーカーですので、直接区のほうでやるものではなくて、自助で取り組んでいただくべきものだというふうに考えていることもございまして。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よって、計画を廃止してほしい。火災によっての死者は１割です。倒れて圧死をしない、それを防ぐための対策がまず大事だということを念頭に、一番に置いてほしい。それが今日の請願の中にも書かれているので、やはり２００２年の阪神・淡路の震災に教訓を学んで意見書を当時つけられたわけですから、ここに学ぶべきであると思っています。この点を１点聞かせていただきたいと思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"星薬科大学が今どうされているのかというところにおいては、この道路、放射２号線をつくるメリットは一体何なのか、文章で説明をしてほしいと、この間東京都に対して要求をしているけれども、全くなしのつぶてで何も返事が来ていないということを星薬科大学は言っていますけれども、大事な品川区内にある大学なのですけれども、区としてこの辺をどう捉えているのか、ぜひ一つお聞かせいただきたいのと。","respondent":"中村都市計画課長","answer":"星薬科大学との交渉につきましては、区としてもやはり区内にある歴史のある大学ですので、やはり丁寧な説明とあるいは今後の再建策につきまして、話し合いが進めばいいというふうに考えてあります。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"丁寧な説明がということで、話し合いが区として行われているのでしょうか。その点をお伺いしたい。丁寧な説明が必要というのはわかったのですけれども、どのくらい説明に行ったり、大学の意向を聞けているのか、そこをぜひ具体的に教えていただきたい。","respondent":"中村都市計画課長","answer":"星薬科大学につきましては、東京都のほうからは特に情報は入ってきておりません。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の答弁だと、都から情報は入っていないし、区も情報がないということでしょうか。それもこの間同じ説明ばかり繰り返して進めている。この姿勢でいいのでしょうか。私はぜひこの大学の考えを取り入れたら、本当に放射２号線の建設と相いれないと思うのですけれども、この辺、このままでいいのでしょうか。私は都と区でごり押しをするのは絶対やめていただきたいと思うのですが、いかがでしょうか。","respondent":"中村都市計画課長、藤田都市環境事業部長","answer":"この特定整備路線の整備につきましては、区としましては東京都と連携して進めていく立場ですが、ただ個々の地権者と事業主の交渉の中において、やはりそういったところで区が入っていくということになりますと。これらを総合的に勘案しながら品川区としては防災に強いまちづくりを東京都と連携していきたいというふうに考えてあります。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"たくさんの声が発信されていて、今国土交通省に不服審査を出しているではないですか。認可がおろされていますけれども、国土交通省の要請行動の中で、道路計画が旧都市計画法のもとの７０年前に決定をされたということで、東京都自身が当時の計画の原図や原簿の存在を確認できていないということ、これがこの間の要請行動の中で明らかになって、法的な瑕疵があるのではないかと言われている状況です。","respondent":"中村都市計画課長","answer":"ただ、私ども区としましては、やはり現在までに進めてきた計画道路につきましては、継続して進めていく必要があろうかというふうに考えてあります。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"請願、この間続けて出ています。請願者の皆さんは、ぜひ区民の代表である議員の皆さんのご意見を聞きたいと思っています。まして、請願者はこの道路計画白紙撤回を求めていますが、立場の上で推進をされる立場に立っていらっしゃる方のご意見もぜひお聞きしたいと思っています。ぜひ、ご発言をお願いしたいと思いますが、再度いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"原委員","kind":"質問","question":"ですから、この放射２号線に対して反対をしているという形ではないのです。推定です。それが私の今の意見ですから、これは文部科学省の問題、国単位でもやっているでしょうけれども、文部科学省、国土交通省、かなり大きい問題なのかもわかりませんけれども、どうも全面的に撤回だよということではないというふうに私個人としては解釈しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひこういう機会に、議員の皆さんにも、行政の皆さんにもぜひ聞いていただきたい。先ほども言いましたけれども、地域の意見をよく聞いていらっしゃる方々、不服審査請求も出していらっしゃる方々なのでしっかりと受けとめたいと思いますので、ぜひ意見陳述を聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問・要望","question":"結論を出していただきたいと思います。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問・要望","question":"結論を出す、不採択です。一言意見を添えさせていただければ、先ほど今回の請願の内容は、白紙撤回および家屋の倒壊、火災予防中心の防災推進を求める請願。白紙撤回と火災予防中心の防災推進、二つを求める請願。感震ブレーカーですけれども、結構テレビとかでやったものですから、かなり区民から私のほうに問い合わせがありました。これはぜひ研究を続けていっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"意見","question":"国も都も区も、住民の意見を真摯に受けて事業計画の白紙撤回、そして阪神・淡路大震災の教訓を活かした耐震化の促進、通電火災防止、初期消火体制強化など、道路ではなく、こちらに転換をすることを主張されているこの請願を応援し、採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問","question":"ご説明は主に騒音対策、落下物もございましたけれども、騒音についてが主だったのですけれども、一般質問の中で、大井町駅上空１,０００フィート、３０５ｍのところで８０デシベル、南に行くほど、飛行場に近づくにつれ、騒音が高くなって、北に行くほど弱まっていくということだったのですけれども、沖合に移転したときと比べると、どのくらい違うのですかね。やはり、なくさないといけないですよね。","respondent":"三ツ橋環境課長","answer":"しかしながら、現在のところ、飛行機の性能が大分上がったというふうに国土交通省も言っておりますので、今のところ、１,０００フィートのところでは８０デシベルということが想定されております。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大井町で８０デシベル、騒音計を借りてはかったのですが、８０デシベルというのは大変な音だし、それがしばらく続く、瞬間的なものではありませんよね。しばらく続くという意味では、本当に耐えがたい。説明はきちんとしてくださると思うのですが、この辺をどう考えているのか、その不安を取り除いていくために何が必要なのかというあたりをご説明いただきたいと思います。","respondent":"三ツ橋環境課長","answer":"区民の不安を取り除くためにまず何をしなければならないのかですが、まずは国からの説明をしっかりしてもらいたいと、こちらはまず区からの要望も出しておりますけれども、国が区民に対してしっかり丁寧な説明をしていくということが大事だと考えています。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問","question":"すごくシンプルなお答えだったのですけれども、丁寧にということにおいては、具体的には国に説明してもらいますというのは何回もお伺いしているのですが、こういう場がどういうところで、どのように行われていくのか、あと言ってみれば説明の内容ですよね。内容によって不安が取り除かれるか、除かれないかというところなので、してもらうというところだけですか。","respondent":"三ツ橋環境課長","answer":"説明に関して、もう少し詳しくお伝えいたします。説明のプロセスやタイミングについては、国からは今後議論を進め、地域への説明についてはより多くの方々のご理解を得て、取りまとめていくことが肝要と考えているです。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"関係団体の意見を聞くと。関係団体のところが、先ほども説明はしていただいたのですけれども、騒音のところはかなり書かれているのですが、落下物と墜落の危険性、この回避をする部分に対しては、区はどのような見解をお持ちなのでしょうか。","respondent":"三ツ橋環境課長、藤田都市環境事業部長","answer":"そのため、飛行機に対する国土交通省からの指導やまた飛行機自体の検査などを徹底してほしいと考えています。飛行機のほうですけれども、担当課長が申しているとおりまずはあってはならないことなので、それが起きないためのことをいろいろやらなければいけないと考えています。","id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろな対策をとっていただきたい。そこはそうだと思うのですね。命を守っていくという立場で、やはり何らかの歯どめというのですかね、守っていく手だてが必要だと思うのですよ。飛べないのね。そういったところの追求もぜひしていただきたい。国が、東京都がといって済む問題ではないので、ぜひそういった手だてもやっていかなければいけないと思うのですが、この点はいかがでしょうか。","respondent":"三ツ橋環境課長","answer":"国に対して言っていくという部分、市街地上空を飛んではいけないという法律はございませんけれども、そちらの件に関しては、今後研究させていただきたいと考えています。","id":"exchange-065"},{"speaker":"大沢委員","kind":"質問・要望","question":"今まで質問されましたけれども、議会のほうでも１２月２５日付で意見書を出しております。要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区から８月に国に対する要望を東京都を経由し提出とあるのですけれども、先ほど環境課長から国としては説明をこれから検討していくというご回答があったのですが、それはこれに対する回答と言ってもいいのかということと、目標年次、２０２０年を見直しする予定はあるのかという問いかけに関しての何か返答というのはあったのでしょうか。","respondent":"三ツ橋環境課長","answer":"こちらの２０２０年の目標年次見直しということについては、やはり先ほど資料にもございましたように、３ページですけれども、オリンピック・パラリンピックまでに実現し得る主な方策ということで、こちらの年度の見直しというものは。","id":"exchange-067"},{"speaker":"あくつ委員","kind":"質問・要望","question":"わかりました。先ほどほかの委員からもありましたけれども、基本的には不安があることは間違いないので、国のほうにしっかりとした安全を求めていくというスタンスで私も理解しておりますし、また議会としてもこれについては既に対応しているところだと思います。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"松澤委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"大倉副委員長","kind":"質問・要望","question":"一言だけ、以前空港における騒音対策を求める意見書も提出をさせていただきました。区民の方々にできるだけご理解していただけるような説明を求めて、取り組んでいただきたいと思います。八潮の方に負担が以前多かったということですけれども、八潮だけではなく、品川区全体の問題ですので、多くの方にちゃんと説明していただいて、不安が取り除けるように国に求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"提案","question":"これから説明を十分したり、あと品川区が国に対しても改善策の提案など、地元の納得するような案を要望していくと、こういった一文があるのですけれども、この間、騒音問題についてはかなり具体化していますが、落下物そして墜落の危険性、これは命にかかわる問題なので、一歩踏み込んで改善策、納得のいく案に対して、やはりルート変更も含めて市街地上空を飛ぶ問題について。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"}]},{"id":"topic-06","title":"の３「報告事項」を聴取いたします。 初めに(1)専決処分の報告について（報告第１号）","agenda":"の３「報告事項」を聴取いたします。 初めに(1)専決処分の報告について（報告第１号）","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１点だけです。損害賠償額が３万７,０００円で、電卓というのはこんなに高いのかなという疑問が出た人がいたので、何と何を購入されたのか、内訳を教えてください。ただ、それだけです。","respondent":"小林品川区清掃事務所長","answer":"この３万７,０００円の内容ですけれども、２点、入っていましたかばんと中の電卓です。","id":"exchange-072"}]},{"id":"topic-07","title":"の戸越公園駅周辺まちづくりビジョンの策定","agenda":"の戸越公園駅周辺まちづくりビジョンの策定","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ご説明いただきました戸越公園駅周辺まちづくりビジョン、品川区の名前で出ていますので、これは品川区が責任を持つ内容であるということなのですけれども、Ａ４のところの経過の経緯のところなのですが、平成１９年に協議会が設立されたということ、まず、設立当時のメンバー、どういう人たちで構成をされていたかということと、この間、８町会、３商店街。","respondent":"中村都市計画課長","answer":"メンバーにつきましては、基本的にはそういったメンバーです。それから、素案の説明会ですけれども、こちらのほうは、各回、大体２５名から３０名ぐらい町会の皆様が出席をして、その中で意見交換をさせていただき、また後日いろいろ意見が届いたりということがございました。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日お手元にいただいたビジョンはこのようにまとまっているのですが、多分もっといっぱいいろいろな資料をそれぞれつくりながら、ここにまとめ上げたと思うのですけれども、ビジョンをつくるに当たって、どこが責任を持って作成をしてきているのか、あと区とのかかわり、区が全部やっているわけではないと思うので、コンサルとかがいっぱいかかわっていると思うのですが。","respondent":"中村都市計画課長","answer":"委託料としては、大体７００万円ほどかかっております。これは説明会ですとか、あるいは資料の説明会に要する作成費ですとか事務経費などが含まれてあります。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資料に基づいて見てみますと、２ページのところに、今までの商店街と補助２９号線が重なっている、連続性が遮断されている箇所が、小豆色っぽいところが２か所ありますけれども、商店街の連続性をこうやって阻害されているわけですけれども、どう考えて、どうこれからも保っていくのか、残った商店街というか、大きい道と外れたところが、またどういうふうにしていきたいというか。","respondent":"中村都市計画課長","answer":"そういったところで、やはり道路として整備する側につきましては、今後共同建て替え、個別建て替えなどの建て替えの支援などを行って、またどのようにまちづくりを進めていくか、お店の配置ですとか、そういった細かいところにつきましても。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問・要望","question":"駅自体が道路になっているので、ここはかなり直さないと駅も削られてしまうという大変な状況にあると思うので、その辺はかなり困難を抱えているけれども、乗り越えないと大変なまちの弊害に、遮断帯になってしまうというか、にぎわいの遮断になってしまったりするので、そこをどう考えているのかというところ、あと６か所の踏切をどうするのですかというのが率直な地元の疑問なのでお答えください。","respondent":"中村都市計画課長","answer":"かねてから東京都に対してこの踏切の解消については要望してきたところですけれども、このまちづくりビジョンを定め、この中に踏切６か所について課題として解消したいというふうに取り上げてありますので、引き続き東京都に要望してまいりたいというふうに考えてあります。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほどのご説明にもありましたように、最初からやはり６か所もある踏切で、かなり遮断されているというところの解消というのは、本当に地元の要望であると思いますけれども、都に要望を引き続き課題としていきます程度しか今日は答えられない、まだそんなところなのですか。何かめちゃくちゃになってしまう。","respondent":"藤田都市環境事業部長、中村都市計画課長","answer":"東京都のほうとしては、放射２９号線の話も含めて何とか円滑化も含めて図るべきということで考えておりますが、なかなか踏切対策基本方針に位置づけられているものがありますので。これは今後まちづくりを、まちの地域の皆様が考えていく中で、どういった方法で自分たちがやりたいのか、またどういった方法が一番いいのか、今後検討がなされて。","id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問","question":"踏切の問題ですが、長年の地域の皆さんの願いなので、本当に早く立体化して、地域の利便性を高めてほしいと思いますが、でも、だからといって、補助２９号線とセットで進めるというのは、私は何かちょっとひきょうなやり方だなと思います。立体交差事業は立体交差事業でやはり進める、これを機会にといって一気に進めるというのは、私はちょっとフェアではないなと思っていますので、意見は言っておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"}]},{"id":"topic-08","title":"の大井町駅周辺地区バリアフリー計画の策定","agenda":"の大井町駅周辺地区バリアフリー計画の策定","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"これも随分私たちも要望してきたことなのですけれども、せっかく来年度におふろがついても、使用するときに、非常に転倒のリスクがあるとなると、すごく遠回りをしないと入れないということがあるものですから、そこのところをもし今おわかりになれば、考え方としてどうなのか、この２点、先ほどのヤマダ電機のことと南品川シルバーセンター、個別で申しわけないのですけれども、わかる範囲で教えてください。","respondent":"中村都市計画課長","answer":"この実施予定時期につきましては、目標として長期ということになってありますけれども、これもシルバーセンターの所管のほうで継続して取り組んでいきたいというところもあって、時期については、もし早く私道部分の権利者などの了解が得られれば。","id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問","question":"両方とも進めていただけるというご答弁でありました。ちょっと、今トイレの関係とかさまざまあるのですけれども、またこれは予算特別委員会で詳細についてはお聞きしますが、全体としてはすばらしい内容だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"}]},{"id":"topic-09","title":"の特定整備路線沿道における都市計画変更素案に関する説明会について（補助２９号線 大崎地区）","agenda":"の特定整備路線沿道における都市計画変更素案に関する説明会について（補助２９号線 大崎地区）","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"Ａ４の説明会の資料のところの１番目、都市計画変更の内容というところに、居住継続支援という文字と新たなにぎわいの創出に資するという、新たなにぎわいの創出、これを目的とした都市計画の見直しを行うという、この居住継続支援ということはどういうことなのか。３０ｍ、沿道の住民の方々にとって、この計画変更のメリットとデメリット、両方あわせて教えてください。","respondent":"中村都市計画課長","answer":"居住継続支援や新たなにぎわいということで、居住継続支援ですけれども、こちらにつきましては、この計画道路の沿道で新たな計画線にかかっている建物につきまして、建て替えの際に一定程度のボリュームの容積率のアップが図られるというところで。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"課長、デメリットはないのでしょうか。地域の方は補助２９号線建設反対、中止を求めているわけですけれども、東京都内で実際に中止になった場所があるわけですけれども、道路を大前提として沿道の計画の変更なのですが、道路が中止になったときに、この沿道の部分はどうなるのかという疑問が一つ出ています。補助２９号線、この部分の進捗状況がわかったら教えてください。","respondent":"中村都市計画課長","answer":"この高さですけれども、今回容積率のアップの比率が、商業系は変更がないということで、それ以外のところでは、１５０％から２００％、そして２００％が３００％というところで、この容積率につきましては、商業系以外の部分が住宅系で２００％、３００％と申しますと。","id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問","question":"最後にしますけれども、これはこれから説明を受けるわけですけれども、いつから実施をされるのか、時期を教えてください。","respondent":"中村都市計画課長","answer":"実施の時期ですけれども、法的な手続があります。説明会を行います。","id":"exchange-083"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/967161?Template=document&Id=4132#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":82374,"voices":281}},{"id":"h27-20150223-9","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"文教委員会","time":"午前１０時００分～午後 ０時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","topics":[{"id":"topic-01","title":"の第２１号議案、品川区青少年問題協議会条例の一部を改正する条例","agenda":"の第２１号議案、品川区青少年問題協議会条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"今の説明では、今現在は教育委員会委員からとなっていて、そこでいろいろ検討した結果、教育長となっているわけですよね。改正された後は、教育長と職を指定するとなるわけですよね。違いが出てくる、教育委員たちの意見がちょっと入っていかないような気がするのですけれども、その辺はどうなのでしょうか。","respondent":"福島青少年育成課長","answer":"今までと変わらずに、当然ながら教育委員会は、これを主宰するのは教育長ですので、教育委員の意見も教育委員会の意見も、当然ながら反映されたものとなりますので、今までどおりと変わらないものと考えています。","id":"exchange-001"},{"speaker":"南委員","kind":"意見","question":"変わらないとおっしゃったけれども、私は違うのではないかと思います。けれども、教育長というのは区長が直接任命するわけですよね。今までもそれは任命はしていて、議会の承認というような形になっていたのですけれども、今までの教育長と、法律改正された後の教育長の位置付け、それが私は違ってくると思うのですけれども、そのあたりについてはどういう見解を持っているのか。","respondent":"福島青少年育成課長","answer":"こちらの青少年問題協議会条例につきましては、今までと同様と考えています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"だから非常に心配して、検討もしたし質問もして、その辺をしっかり確認したいと思っているわけですけれども、今までの仕組みとは全然変わるわけですよ。では、なぜ教育委員から出そうというふうにしていかないのか。その辺について、どういう検討でそうなったのかということを改めて伺いたいと思います。委員長、発言は手を挙げてやっていただきたいということをちょっと整理していただきたいと思います。","respondent":"福島青少年育成課長","answer":"あくまでも今回ご提案させていただきましたのは、青少年問題協議会の条例を一部改正する条例という中で、今まで教育委員会の中で代表している教育長に出ていただいたのを、今回さらに明確化して、教育長という形に、教育委員会を主宰する方に出ていただくという位置付けですので。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"教育委員会のほうに質問というか伺いたいと思うのですけれども、地方教育行政の組織及び運営に関する法律が変わったことで、教育長の位置付けというか、そこのあたりは全く同じなのか、それともどういう変化が、あったとしたならばどういうことなのかをちょっと伺いたいと思います。","respondent":"品川庶務課長","answer":"これが、新たに教育委員長と今の旧教育長を一緒にした形で、新教育長という形で変えていますので、ここが大きな変更点かと思います。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"そういう大きな変更点があるということですよね。それで、教育長という指定をするということではなくて、やはり私は教育委員会、教育委員を代表するという立場で、青少年問題協議会構成も図るべきだと思うわけです。そういう点で、教育長と明記するということではなくて、やはり教育委員会のこの教育委員という位置付けでなぜしようとしないのかというところを、ちょっともう一度伺いたいと思います。","respondent":"田村教育次長","answer":"法律の考え方に沿って説明しているので、南委員の思いはわかるのですけれども、法律を理解してもらいたいのですね。なぜかというと、法律は背景があって、先ほど庶務課長が言ったみたいに、今は教育委員長と教育長。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"しかし、法律によっての改正だから仕方がないではなくて、やはり私としては、教育委員会を形骸化しようという狙いの中でこの法律が改正されていったという、そこのところを見たときに、子どもたちの、青少年の問題をいろいろな関係機関も含んで、庁内のいろいろな役職の方たちも一緒にこの協議会に参加をして議論をする場に、やはり子どもたちの状況を一番よく知っている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"それが委員会なんですから、委員長、そういうふうにちょっと仕切っていただきたいと思います。私はそういうふうに思いますので、この点については非常に理解はできにくい。こういうふうに意見、態度を表明しておきたいと思います。それでね、やはり堂々と反対の意見を反対で堂々と言えばいいんです。〔「反対じゃない。理解してるんだから。理解して黙って聞いているの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"だから、理解しているということで言えばいいだけでしょう。何を言ってるんですか。手を挙げてくださいよ。〔「待ってます、順番を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、自分の意に沿わない意見を言う人もお互いにいるでしょう。委員同士の意見交換だっていいわけですよ。必ずしも理事者のほうに質問しなくてもいいわけです。ですから、自分の意に沿わないような発言があったときも、別にそのことに対して発言をしにくくするような行動は、私はずっとしていません。ぜひ受けとめていただきたいと、発言された方はよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"私は先ほど質問したような趣旨で、賛成はできません。心配な点があるということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"そのあたりのことをちょっと伺いたい。先ほどは年間大体１件程度だというお話だったので、それはそれとしてわかりましたけれども、この間、何かいろいろな齟齬というかいろいろな状況が出てきて、改めてこういう義務付けとなったのかなと思うのですけれども、そのあたりのことも伺えればと思います。","respondent":"福島青少年育成課長","answer":"この間、先ほど言いましたように年１件あるいは２件程度ですので、広く周知してというよりは、こういうことが改正されました程度のことで、実際に周知文のところでは第三者の行為によるものがあった場合には連絡くださいぐらいにおさめておいて、実際に起こったときには。","id":"exchange-011"},{"speaker":"南委員","kind":"確認","question":"最終的に確認したいと思っているのですけれども、では、事故に遭って通院を始めたと。そのときに、直後ではなくて何日か、あるいは何週間か経過して、その後に当然通知が行くわけで、そのときに区が掌握をして、それでこういう場合は届出義務ということになりましたので、区のほうで対応することになりますよというふうに、被害者の保護者にはそういう旨をお知らせをするということでいいわけですね。","respondent":"福島青少年育成課長","answer":"まさにそのとおりです。","id":"exchange-012"},{"speaker":"南委員","kind":"確認","question":"今回の措置というのは、期限というのは設けているのでしょうか。それとも、以前のときに所得税をベースにして保育料が設定されているのだけれども、それが変わっていくような、住民税ベースにとなっていくのか、当面はこのままでいくと聞いたような覚えがあるのですけれども、その関係で、この措置は期限があるのかどうかというのを確認しておきたいと思います。","respondent":"竹田保育課長","answer":"今回、子ども・子育て支援法に基づきまして、保育料の算定根拠を所得税から住民税にするということが打ち出されておりますが、所得税と住民税の算定根拠が大きく違いまして、また国の保育料の上限額等々提示が非常におくれたことによりまして、４月から算定根拠を変えることは。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"そうしますと、第２子、第３子以降の子どもについての減免だとか、また８時間保育が８割だとか、そういう今回のこの条例に盛られた内容は、これはこのままでいくと。保育料の額が変わっていくということで理解していいのですか。","respondent":"竹田保育課長","answer":"ただ、今回、子ども・子育て支援法の実施に伴いまして、必要最低限度の条例改正が必要と考えておりますので、その部分について今回ご提案させていただいているものです。","id":"exchange-014"},{"speaker":"南委員","kind":"確認","question":"８時間保育、保育短時間認定の子どもの保育料の関係で、では延長保育料金というのは、具体的に保育時間がどういうふうに延長したら、どこからどこまで延長したら延長保育料金を徴収する対象になるのかどうか、そのあたりを保育時間との関係で確認しておきたいと思いますので、お願いします。","respondent":"竹田保育課長","answer":"今回新たに設定されました保育短時間につきましては、この時間内の８時間について、ご利用、お預かりするという制度です。したがいまして、この開所時間内でありましても、８時間を越えた部分については時間外保育料として徴収するものです。","id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"そうすると、その保育短時間認定の８時間の方は、８割の保育料プラス延長料金というふうになるわけですよね。いわゆる開所時間内、７時半から６時半の間であれば、８時間保育を若干オーバーしても、延長料金は徴収しないという自治体があるやに聞いているのですけれども、その辺の情報というのはどうなのしょうか。","respondent":"竹田保育課長","answer":"今回設定させていただいた基本開園時間内での８時間ということですが、国あるいは私立の保育所ではもうその８時間を限定して、ここからここまでという形で固定されている保育所もあると聞いておりますが、品川区では一歩進んで、より柔軟にその８時間をご利用いただけるように。","id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"最後に確認します。勤務ですから交通機関を利用する方もあるだろうし、徒歩の方も自転車の方もいろいろあると思います。そういう中で、交通事情だとかいろいろな状況で、例えば８時間よりちょっとはみ出しちゃったと。その辺というのは延長料金徴収との関係で、どのくらい厳密にするのかしないのかというあたりをちょっと確認しておきたいと考えています。","respondent":"竹田保育課長","answer":"原則は８時間というご契約ですので、８時間をはみ出した部分は徴収しますが、もろもろの天災等ご事情がありますので、その場合はケース・バイ・ケースで対応していきたいと考えております。","id":"exchange-017"}]},{"id":"topic-02","title":"の第２６号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例","agenda":"の第２６号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例","exchanges":[{"speaker":"南委員","kind":"確認","question":"先ほどの議案第２４号、議案第２５号のときには言わなかったのですけれども、やはり保育料を所得税から住民税に変えるときに、引き上がっていく可能性もないわけではないと思うし、その点についてできるだけ負担をあまり大きく変えさせないということは当然のことだと思うので、改めてこの条例の制定そのものについてはちょっと違う質問をしてしまって申し訳ないのですけれども。","respondent":"竹田保育課長","answer":"保育園につきましては、３０階層に分かれまして非常に影響が大きいことがシミュレーションされましたので、周知期間もないことから、平成２７年度は現行どおりとして、その後については今後検討するということとしております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"こういう経済状況の中ですし、２年先ではあっても消費税も増税されるとか、また生活に大きな影響が出てくることが予想される状況もある中で、やはり保育料と消費税は別だよということではなく、生活全体を見たときに、やはりきちんと生活を支えていくという点で、考え方としてきちんと持っていただきたいと思いますので、激変にならないように。","respondent":"竹田保育課長","answer":"今回ご提案させていただいたのは、平成２７年度の保育料についてです。それ以後の平成２８年度以降につきましては、今後社会情勢等いろいろ勘案しまして、適正な保育料をご提案させていただきたいと考えております。","id":"exchange-019"}]},{"id":"topic-03","title":"の第３７号議案、品川区教育に関する事務の職務権限の特例に関する条例の一部を改正する条例","agenda":"の第３７号議案、品川区教育に関する事務の職務権限の特例に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"ものすごく基本的なことで、ちょっと聞くのも恥ずかしいかなと思うのですけれども、これは区長が管理し執行するスポーツと文化に関することという事務についてなのですけれども、これが教育委員会部局、教育委員会サイドでの条例になっているということがちょっとよくわからないのですけれども、その辺を教えてください。","respondent":"品川庶務課長","answer":"こちらは教育委員会の中の職務として位置付けるものとしまして、文化、それからスポーツに関することを位置付けているという意味です。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"この条例が制定されたのが平成２０年１２月８日ですよね。それ以前はどういうふうになっていたのですか。この文化、スポーツに関することの扱いというのはどういうふうになっていたのでしょうか。","respondent":"田村教育次長","answer":"平成１９年度に地方教育行政の組織及び運営に関する法律が大きく変わりました。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"それと、ちょっと議案から外れてしまうのですけれども、この条例そのものについては、そういう点ではあまり問題点というのは、規定を整理するということなので了解かなと思っているのですけれども、私はこの条例を検討するにあたって、教育大綱の関係がなかなかこの文教委員会に示されてこないので、教育大綱そのものは区長の権限で決めていくので。","respondent":"品川庶務課長","answer":"教育大綱につきましては、来年度、総合教育会議というのを始めていく予定です。この総合教育会議の中で教育大綱の部分を決めていくということになっていますので、来年度、総合教育会議の中でどのようにやっていくかというところを議論していくという形になるかと思います。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"そうすると行政部局のほうの話になってしまうかもしれないのだけれども、法の施行は４月１日からですよね。そこの時点で、教育大綱だとか総合教育会議というのは設定されていなくていいのかなというのがちょっとあったので、そういう質問をしたかったのですけれども、それはどうなのでしょうか。","respondent":"品川庶務課長","answer":"法の施行は４月１日以降ですので、総合教育会議も当然４月１日以降という形になります。その中で教育大綱を決めていくという形になりますので、当然４月１日以降やっていくということになるかと思います。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"そういうことで、４月以降の準備というか検討が始まるというということなのだと思うのですけれども、かといってそんなに長期間つくりますよという状況を長期間続けていっていいとはならないのかなと思うので、大体どのようなめどなのかなというのを含めて。","respondent":"田村教育次長","answer":"総合教育会議を招集するのも区長、それと教育大綱を策定するのも首長の権限なので、作業は総務部門でしていると思うのですけれども、ちょっとこの場でこうだと思います、ああだと思いますという話には、申し訳ないですがならないかなと思います。","id":"exchange-024"}]},{"id":"topic-04","title":"の品川区立幼稚園条例の一部を改正する条例","agenda":"の品川区立幼稚園条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"確認","question":"確認だけですけれども、これは区立幼稚園ということなのですが、当然、子ども・子育て支援新制度の法律の中に、私立の幼稚園ではそういう枠に入らないというか、１号認定という意味は、ちょっとその辺整理されていないのですけれども、幼稚園は子ども・子育て支援新制度との関係で、私立と区立とどういうふうに仕分けされているのかどうか、その辺を確認をしたいと思います。","respondent":"竹田保育課長","answer":"区立については、先ほどご説明したとおりの保育料を定めております。多子減額の考え方につきましては、区立・私立ともに小学校３年生までから第１子、第２子、第３子と数えまして、第２子は半額、第３子については免除と今回するものです。","id":"exchange-025"},{"speaker":"南委員","kind":"確認","question":"その多子減額の部分なのですけれども、小学校３年生までの子どもがいる場合は、そこから数えて第２子とか第３子とかなるということなのかなと理解してはいるのですけれども、戸籍上の第２子、第３子というのと違いがあるのか、あるいは同じで考えていいのか、そのあたりをこの間もいろいろ条例で出てはきているところですけれども、最終的に確認したいと思います。","respondent":"竹田保育課長","answer":"第２子、第３子の数え方ですが、基本的には確認のできる書類をもって第２子、第３子と数えていきたいと考えております。","id":"exchange-026"},{"speaker":"南委員","kind":"確認","question":"その場合は、戸籍上は第３子、あるいは第４子となるかもしれないけれども、２番目の子どもさんが５割減額で、３番目は無料になると捉えていいのか、あるいは戸籍上の第２子、第３子という捉え方なのか、そのあたりを確認したかったのですけれども。","respondent":"竹田保育課長","answer":"今回の制度の数え方につきましては小学校３年生までを対象にとしておりますので、仮に小学校１年生から３年生までに第１子がいた場合は第１子、幼稚園部門に２番目のお子さん、３番目のお子さんがいらっしゃった場合は第２子、第３子という数え方です。","id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"１番目の地域手当の割合の変更なのですけれども、これに伴って月額給料を同程度引き下げると付随されて出てきているわけですけれども、月額の給料がやはり例えば退職金だとか、その後の年金だとか、あるいは途中退職した後のいろいろな問題に非常にベースになる数値だと思うので、これの引き下げというのはちょっと異議ありというか問題があるなと私は思っているのですけれども、その辺の認識と。","respondent":"渋谷指導課長","answer":"制度全体については総務委員会のほうで、今、私のほうでわかりかねる部分もありますが、基本的に全体の給料のこの変更については、国との制度上の均衡を図るために行っているものですので、区固有教員、幼稚園教員だけ特別に変更をということはできないと。","id":"exchange-028"},{"speaker":"南委員","kind":"意見","question":"労使のところは把握していないとおっしゃったのですけれども、話し合いの結果、妥結をしたと了解、認識をして、中身的には先ほども指摘したように、月額給料が１.７％とはいっても下がる。だから賛成です。反対はしません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"南委員","kind":"確認","question":"先ほど改めて申請者数と内定者数の数字を説明、紹介していただきましたけれども、本会議でも同種の質問をしたときに、一次選考で内定が出なかった、不承諾通知をもらった人は１,２５６人という数字が示されたのですけれども、今の説明ではなかったのですが、それは同じ数字ということで確認していいのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"本会議で答弁申し上げましたのは発送予定数ということで、一次選考で内定が出なかった数、１,２５６人という数字を紹介させていただきました。","id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"１,１８８人ということにしましても、二次募集で受け入れる枠というのは何人ぐらいになると予定されているのでしょうか。ホームページを見ますと、たしか認可保育園で６人、そしてその他の保育ママ、小規模保育事業で１１人だったかな。１７人の枠しかないのかなとちょっと思って、大変な事態だなと私は思っているのですけれども、どういう状況なのかを教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"地域型保育事業の家庭的保育、小規模保育では０歳から２歳児の受け入れですので、そちらが１１人という形になりまして、合計１４８人の入園枠を予定しております。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"ここのところで見たときにも、では、ここの１,１８８人の年齢の内訳というのはどうなっているのかというのを伺っておきたいと思います。辞退がどれくらい出るかわかりませんけれども、その数を加えてみたときにも、１,１８８人の中の８割だろうと想定される０歳から２歳の子どもがどれだけ入園できるのかというのをはっきり確認をしたいと思いますので、区としてはどういうふうに見ていらっしゃるのか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"先ほど１,１８８人というところで申し上げましたけれども、転園というお話もさせていただきましたけれども、現在転園や、既に保育ママまたは認証保育所、そして私立幼稚園等に在籍された人数につきましては、この１,１８８人の中に含まれておりますので、実際今後。","id":"exchange-032"},{"speaker":"南委員","kind":"確認","question":"一番最初に確認しておきたかったのですけれども１,２５６人のうちに書類未提出の方もいるという、その方についての扱いは、申請の対象にならないと考えているということなのかどうか、そこを確認したいと思います。それが１点です。それから、０歳から２歳は何人ぐらい。","respondent":"今井制度改革・待機児童対策担当課長","answer":"２点目ですけれども、全体の不承諾、いわゆる利用不可通知の中の０歳から２歳の枠につきましては、例年どおりこちらのほうがほとんど多い数を占めていくということで認識しております。１,１８８人の内訳等はお持ちしておりません。","id":"exchange-033"},{"speaker":"南委員","kind":"確認","question":"ありがとうございました。それで、この保育園に入りたいと二次申請をする方たちへの対応をどういうふうにしていこうと考えているのか、そこが大事なところだとだと思うし、この２つの請願者の方たちもそこが一番大事だと主張しているところだと理解しますので、改めてその対策についてどういうふうに考えていこうとしているのか、そこを伺いたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今、入園の窓口につきましても、今、委員にご説明したとおり、入園の可能数のところはたとえゼロであっても、内定の辞退等の可能性があるので、ご希望の申請の変更などもあわせてお伺いしています。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"小規模保育事業所等々もこれからも整備をしていく中で対応していきたいというお話なのですけれども、それはそれとしてぜひやっていただきたいと思うのですけれども、４月１日に入園したい、その子どもたちへの対応はどうしようと考えているのか、そこが私は一番聞きたかったのです。そこについて、説明してください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私ども総合対策をとっている中では、今、ご案内のとおり入園窓口で認可保育園、そして小規模保育など、区が利用調整をしたもの以外に、ホームページ等でも認証保育所でまだお申し込みいただける申込可能な認証保育所の情報提供をするなど、さまざまな情報提供を通して４月の入園。","id":"exchange-035"},{"speaker":"南委員","kind":"確認","question":"そうなると、認証保育所の情報も出していきたいということで、認証保育所もいっぱいできるようになりましたけれども、そういう情報を出すことで、１,１８８人、あるいは１,２５６人、あるいはその８割という数が解消できると考えているということですか。そこをまず確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私としましては、今回待機児童という形で、昨年最終の確定値が１２８人という形でございました。昨年度よりも申込数等、今、不承諾数のほうが増えている中ではありますので、開設は進めておりますけれども、待機児童数は残念ながら増加すると見込んでおります。","id":"exchange-036"},{"speaker":"南委員","kind":"提案","question":"そういう角度で、だから待機児童解消をということで、私たちの会派、共産党としては２月３日に緊急提案をしてまいりました。この１,２５６人に対する責任を品川区はどういうふうに考えているのでしょうか。増設をしなくても、これからつくっていくからとか、認証保育所の情報を出すからということでよしと考えているのかどうか、そこを伺いたいと思うのです。その点についてはどうですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"現時点でも、やはり待機児童が増えるという見込みの中で、年度途中なるべく早期に開設できるよう、事業者、そして私どもも開設の計画を早めるということを、今、念頭に置いて努力しています。","id":"exchange-037"},{"speaker":"南委員","kind":"質問","question":"早期にというのはいつのことですか。私は４月１日のことを言っているのですけれども、その早期にと、今、おっしゃった、開設できるように努力したいとおっしゃった、そこは本当に期待したいと思っているのですけれども、その早期という時期がいつなのか。区民の皆さんは４月１日と言っていらっしゃる。そこについて、どういうふうに応えようとしているのですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"先ほどご説明しましたとおり、予算プレスでもございましたとおり、私どもの早期というのは、まず確定している内容は７月です。さらに小規模保育等を含めて開設が早められないか、今、努力をしておりますが、まだこちらのほうはご案内する時期には来ておりません。","id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"７月だったら、４月、５月、６月の３カ月はどうするのですか。その間リストラされてしまうかもしれないじゃないですか。子どもを４月の時点で入れたい。７月、３カ月たったら１歳児になる子どももいるかもしれない。だから、今、開設をしていってくださいよ、緊急対策をとってくださいよと言っているのですけれども、そういう姿勢はないと見ていいのですか。私はぜひやっていただきたいと思っています。","respondent":"金子子ども未来事業部長","answer":"説明は制度改革・待機児童対策担当課長が申し上げたとおりなのですけれども、私どももここ数年、待機児童が５０人、６０人台から、昨年４月には１２８人。依然として申込者数が増えている。","id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"もう繰り返しになるのでそろそろ終わりにしたいとは思っているのですが、しかし、ちょっとやはりしっかりと確認しておかなくてはいけないと思いますので、ぜひ許していただきたいと思います。だから、私は繰り返し質問させていただいたわけですけれども、そういう人をつくってしまうということに対して保育の実施責任という点でどう見ているのか、その辺を最後に聞いておきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これまでどおり、総合的な待機児童対策の中で、品川区が住民の方から求められる保育の実施について、今後も引き続き努力してまいります。やってまいります。","id":"exchange-040"},{"speaker":"渡辺委員","kind":"質問・要望","question":"内容は説明等、今の理事者の説明あるいは質疑と重複するので質疑はしませんでしたが、肝心な項目のところで、園庭のある認可保育園ということで、これも質問の一つでありますが、これだけではないという、これまで私どもも待機児解消に向けて自民党としても強く要望し、行政といろいろな折衝をしているまさに今もさなかですが、やはりその中で課題があるのは承知ですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"つる委員","kind":"質問・要望","question":"こうしたさまざまな課題の中で、今、懸命に全庁的にもさまざまな課題がある中で、待機児童対策を一生懸命とられているなということは理解していることなので、そうした中でこの保育を求める方々の心に全力で応えていくということは、これまでも公明党としても力強く要望させていただいて、その中で進めていただいていると理解しておりますが、現実のこうした課題に対してはよりきめ細かい対応。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"石田（し）委員","kind":"意見","question":"今日、結論を出す。請願の中でやはりこの園庭のある認可保育園、我々としては認可保育園のみではなくさまざまな支援、また対策を講じて待機児ゼロに向け取り組んでもらいたいという思いでおりますので、この請願に関しては不採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"南委員","kind":"提案","question":"なぜなら、やはりその方のその家庭の今後の生活がかかっている。絶対そんなこと考えられないじゃないですか。やるのは当然ですから、実施責任は区にあるわけですから。あらゆる努力をしていないじゃないですか。私たちが提案したことをどこまで検討されたのか、そういう表明もありませんでしたけれども、やはりあまりにも無責任というか、住民の切実な願いに真摯に応えていくことが求められると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"高橋委員","kind":"意見","question":"結論を出すということで、請願の趣旨に沿い難いということで。こういう事態になったということを重く受けとめて、先ほど話があったように平成２７年度の計画を早期に努力されるということですので、そちらへの対応も行われるということで、私はこちらの請願の趣旨には沿い難いと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"渡辺委員","kind":"意見","question":"結論を出すということであります。この第９号は意見として不採択。先ほどと重複の部分は省略しまして、同趣旨のこと、あるいはもうこれまで取組みがなされているという点と、あと項目のところで今後の制度変更の中でも保護者の保育料負担軽減、対応がなされている、考慮がされているということから、不採択ということです。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"つる委員","kind":"提案","question":"請願第６号についても請願第９号についてもですが、先ほども申し上げましたけれども、待機児童対策、解消に向けたことを公明党としても求めてきたということも含めて、また直接的なこうした施設建設だけではなく、あらゆる形でその待機児が解消される、そうした社会の仕組みについては国政においてもさまざまな取組みがなされる中で、この区議会にあって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"石田（し）委員","kind":"意見","question":"今回の請願項目で、先ほどもありましたけれども、保護者の保育料負担の軽減等々、また認証保育所等の支援についても区も対応をされている中でありますし、保育園増設、我々はそれのみではなく、さまざまな支援策、在宅支援も含めて、そういった支援策によって待機児の解消に努めてほしいという思いの中で、この請願においても不採択ということでお願いしたいと思います。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"それで、先ほどの質疑のところで質問しなかったのですけれども、意見として申し上げたいと思いますが、この認可外保育施設への支援というところについては、基準を満たすところについて支援していきたいという担当課長の説明が最初にあったのですけれども、ぜひそういう支援の方向で、全ての品川区内で開設している認可外保育施設については一刻も早く調査をしていただきたいと。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"高橋委員","kind":"質問・要望","question":"私もそういったさまざまな対策で待機児の解消を求めてきましたし、これから区のほうの対応に、現状の対応を、先ほどお話ししたように早期にということで、対策がなされていると思います。それから、２のほうの項目では、先ほどもお話ししましたけれども、増設以外にも補助や支援で対策を行っているという点においても、請願趣旨に添い難いということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/111718?Template=document&Id=4848#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":38798,"voices":268}},{"id":"h27-20150223-5","meetingId":"h27-cm02","date":"2015年2月23日","dateIso":"2015-02-23","committee":"総務委員会","time":"午前１０時００分～午後 ０時０４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"の第９号議案 品川区の組織改正に伴う関係条例の整理に関する条例","agenda":"の第９号議案 品川区の組織改正に伴う関係条例の整理に関する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"下線が引いてあったり、９号議案と書いてあったり、その次の１０号議案は１０号議案となかったり、全体に統一感を持ってもらえると、渡された資料を見るときにこんがらがらないというのでしょうか、特にこうやって並ぶときにはすごくそれを感じるので、これはどこがどういうふうに統一性を持って行うのかわかりませんけれども、これは要望だけにとどめますので。","respondent":"柏原行財政改革担当課長","answer":"こういったところを迅速かつ的確に対応していきたいといったところがあります。そういったこともございまして、事業部を部という形にいたしまして進めていきたいといった内容のところから、今回、組織改正ということで、部の形も含めてやらせていただいたといったところです。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"今までもたくさん議論しているので、中身というよりは、この条例の内容で、いろいろな第２条の関係の附属機関なのですが、どこの附属機関がどこに所属しているのかというのは、条例の中にはそういう指示をするところがあるのでしょうか。これがどこに入っているということがわかりにくいので、それがはっきりしていただけばというふうに思ったのですけれども。","respondent":"柏原行財政改革担当課長","answer":"会議をどうやって進めていくかといったところもありますので、その課に所管してもらうということで、そういった意味も含めて組織改正を子ども未来部のほうでしていますので、そういった観点でこちらのほうに移ったといったものです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"附属機関のほうが、要は、これら一覧のいろいろありますけれども、どこの部署に入っているのかというのがわかりやすく条例の中で明記はあるのでしょうか。例えば、わかりやすいようにするのであれば、附属機関のところの一覧をつけるかなにかわかりませんけれども、何々部といって、それぞれの機関を列記すれば、これはここの機関にあるというふうに理解しやすいと思うのです。いかがでしょうか。","respondent":"柏原行財政改革担当課長","answer":"私の説明がちょっとあれだったので、こちらは、条例のほうにはこういった形で、今回の報酬および費用弁償に関する条例というのは、どういう費用弁償を、どのぐらいの費用で、どういうふうに払うかというようなところを決めたものが、一括してまとめたものがこの条例です。","id":"exchange-003"},{"speaker":"西本委員","kind":"提案","question":"だけど、これを見たら疑問に思います。今回の説明の中で、これは組織改正がなかったのでという話から説明が入っているので、そうすると、この附属機関は一体どこに附属していたのかということがかなりわかりやすいように、資料添付も必要なのでしょうけれども、条例を見たときにわかりやすいような工夫もできるのではないかという提案なので、今後の検討という形でお願いしたいと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私も大変不勉強で、これを委員に向かって言うのか、区民に向かって言うのか、そうすると、別にこれ、行政順がどうでも、我々はどこの所管かということがわからなくてもいいと思っているときもあるわけです。だから、どこの所管で、どこの、例えばこういう審議会があってということを、まさにこれ、内部的なことというのだったら、我々は何も言うことはないわけではないですか。資料として。行政順であれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"の第１０号議案 品川区情報公開・個人情報保護条例の一部を改正する条例","agenda":"の第１０号議案 品川区情報公開・個人情報保護条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"引用条項の変更というのは必要だと思うのですけれども、教えていただきたい点だけなのですけれども、この独立行政法人が３法人に分類され、そのうち国家公務員の身分がここだと、正直この変更の意味が私はわからなくて、もともとの法律の改正の趣旨に当たるのかとは思うのですけれども、ここだけ少し解説していただけますでしょうか。","respondent":"荒井広報広聴課長","answer":"特定独立行政法人が３つの法人に分離されました。中期目標管理法人と、国立研究開発法人と、行政執行法人です。このうちの行政執行法人のみに国家公務員の身分が付与されることになりました。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"よくわからないので教えていただきたいのですけれども、この第８条そのものが公開の義務を規定しているものでありますので、公開の義務を例えば緩めたり狭めたり、そういうものになるのか、ならないのであれば、そこを中心にもう１回ご説明いただけますでしょうか。","respondent":"荒井広報広聴課長","answer":"失礼いたしました。公開の義務を定めているもので、この(2)については、公開の義務を定めている個人情報の中に入っているものとして今挙げたものがあるわけですが、それについては以前と変わりはありません。","id":"exchange-007"}]},{"id":"topic-03","title":"の第１１号議案 品川区行政手続条例の一部を改正する条例","agenda":"の第１１号議案 品川区行政手続条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１つ、行政手続法の改正に伴って区の条例の権利利益の保護の充実というご説明ですけれども、この行政手続法の改正であったり、区の規定の改正であったり、例えば念頭に置いている事業だったり、要するに、区民と行政、また区民と業者というのでしょうか、この条例そのものにはそういう部分はない、実際、区民生活の中でいろいろ問題があるからこういう改正がされて、区条例も改正ということなので、例えば。","respondent":"江部総務課長","answer":"それにつきまして、特にうちのほうでもどういうことで回答しないとか、内容に不備が求められるものではなくて、これまでも責任の根拠を明確にしなければいけないということはありましたが、それにつきまして、少し具体的にどの条文で、どの条項で。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"そのときにされて、区が受理をして審査をして、応答の義務がないというふうになれば、この権利義務の保護の充実にどうしてそれでなるのかと思うのです。もちろんいろいろな案件、ケースはありますけれども、やはり申出者に対してしっかり経過や処理の中身を報告するということは当然進めていくべきではないのかと思うのですけれども、その点はいかがですか。","respondent":"江部総務課長","answer":"申し出につきまして、各所管の状況の中できちんと調査をして対応していくということになるのだと思いますけれども、特に問題がないと思った場合に、何もしないかという部分につきましては、運用の中でこれを考えていくことになろうかとは思います。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"いわゆる初めの第３３条第２項関係の行政指導の方式のところ、要するに、行政の説明責任をしっかり果たしましょうという趣旨だと思いますので、そういう意味でも、やはり申し出があったときに、その結果がどうなのかということも説明責任をしっかり果たすというスタンスをしっかり持っていかなければいけないと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしますが、今回、改正の内容ということで出ていますけれども、こういうことは今まで、こういう条例をつくらなくても、実際やっているわけですよね。というのは、そこで摩擦が起きてしまったら大変なので、ただそれを今回、条文としてきちんと明記するということなのですか。それだけ教えてください。","respondent":"江部総務課長","answer":"委員おっしゃるとおり、例えば第３３条のところの新旧で見ていただきたいのですけれども、旧の中にも、行政指導に携わる者については、相手方に対して、指導の趣旨、内容、責任者を明確にしなければならない、これもそのまま横引きで第１項であるのですけれども。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問としては、教育委員会定例会に諮って合意を得ているものなのか、それとも、こういう条例というのは教育委員会と区長部局とのそれぞれの独立した関係で、そういうふうに扱っているものなのか、そこを伺いたいと思います。","respondent":"江部総務課長","answer":"今回の条例改正につきましては、基本となります地教行法が改正されたことで、教育長が特別職に変わったという法の変更による形式的な整理ということになろうかと思います。","id":"exchange-012"},{"speaker":"中塚委員","kind":"提案","question":"法律の改正に伴うものなので、教育委員会に情報提供はしているけれども、審議をするものではないというところですけれども、私が伺ったのは、それぞれの教育委員会の施策の決定と、教育長だったり、教育委員だったり、出席に伴う費用弁償だったり、そういう身分の保証、これは教育委員会に諮らなくても、いわゆる区長部局の判断で行うべきものなのか。","respondent":"江部総務課長","answer":"今、委員のご指摘のとおり、基本的には、執行自体は教育委員会なわけなのですけれども、予算提案権は区長にあるですので、金額ですとか、その辺については、十分教育委員会と協議しながら、最終的には区長部局で決めるですので、実際の執行は教育委員会でやっているということは。","id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"今回の改正そのものは、法律の改正に伴って、新しいポストができるということで、そこに必要な規定の改定だという範囲では必要なことだとは私も思いますけれども、この地方教育行政の改正に伴って区長部局から教育委員会への権限介入というのは慎むべきだというふうに申し述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"今回もいろいろ法改正があったということなのですが、そもそも教育長、今の教育長の給料額というのは、どういう規定になっていたのでしょうか。それから、第３条のところに、「１５人以内」という、これ、「以内」というふうにしたのは何か理由があるのでしょうか。お聞きします。","respondent":"江部総務課長","answer":"実際、一覧表の中では、教育長職も入っておりまして、２３区の中での位置づけみたいなものも資料としては出ておりますが、形式的には、審議対象ではありません。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"逆に言うと、自由度がなくなったという部分もあるので、その辺をどうお考えになっているのかということ。１５人いなくてもというのだったら何人がいいのですかという話になります。今まで１５人いなかったのに、なぜ１５人という数字にこだわるのかと、実際、現実的にないのであれば、それに現実的に合った数値を入れてもいいのではないかと思うのですが、いかがでしょうか。","respondent":"中山総務部長","answer":"もちろんその範囲が全く青天井ということではなくて、１５とある限りは、基本的には１５人を目指すということだけれども、若干の幅が出ることについて、条例上きちんとその範囲を保っているという形をとろうということでやっているものです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"最後に１つ、現行と教育長の給料上に違いというのは大きく出て来るのか、来ないのかということだけお聞きしたいと思います。","respondent":"江部総務課長","answer":"実態は今までも審議会の対象ではないのですけれども、それを区長等の給与を横引きしているということはきちんとやってきたということになりますので、特に変わってくるものではないかと思います。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そのときに、この改正は、議員たる者、議会もしっかりそういうことは学んでいって、物を申していくところは申していくということを議員各個人がしっかりやれるようになったのだから、その勉強会では、そこはよく理解をしてくれというようなハッパをかけられた我々もいたわけなのですけれども、ここで今、法律の一部が改正されたということで、お聞きしたいのは、今の第１２条、第１３条、第１４条。","respondent":"江部総務課長","answer":"それを受けてというのは、その区の事情によって変わってくると思うのですけれども、特別職の報酬のこれまでの審議の仕方であったり、それから、第１４号議案につきましては、職務専念義務という扱いにつきましても。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうすると、第１２号議案の、例えば特別職の身分を有することになったから、ここは改正しますと。だけど、特別職の報酬等審議会があるかどうかという、一部ないかもしれないからそれはわからない。だけど、１４とか１６については、結構いろいろな教育委員会のやり方は、他の自治体あるので、額は品川区が今までやってきたことを踏襲しながら、それに見合った改正をしてきているという理解でいいのかどうか。","respondent":"江部総務課長","answer":"特別職の報酬につきましては、恐らく２３区なども全体調査をかけられるということは、報酬等審議会はそれぞれお持ちだと思いますので、同じような扱いになっています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"意見","question":"意見だけ言わせていただきます。今回は教育長が特別職になったということで条例改正ということですが、教育委員会の教育長職務代理者および委員の報酬も今回載っておりますが、やはり全国の自治体の中では、だんだんに変わっているという、進んでいく方向性を考えると、品川区の報酬等審議会でも、その辺はしっかり議論してほしいと思います。それだけ意見を言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"済みません、ちょっと確認というか、よくわからないので教えていただきたいのですけれども、今回、教育委員長がなくなって、委員長の職務代理者というのが教育長職務代理者になりますけれども、この教育長の職務代理者は、教育委員会の中から恐らく選定されるかと思うのですけれども、今までの旧の場合でいくと、教育長という方がもし職務を遂行できなくなった場合、その代理というのは。","respondent":"江部総務課長","answer":"役割はそれぞれ違うというふうに認識しております。","id":"exchange-021"},{"speaker":"塚本副委員長","kind":"確認","question":"そういうことがきっと起こるのだろうと思っていて確認させていただいて、正直言って、代理が務まるのかということを、もう少しわかりやすく言うと、教育委員の中で教育長が今まで持っていたような職務を果たすということが果たして大丈夫なのでしょうかというところがちょっと心配、懸念があるので、その辺はどのようにお考えでしょうか。","respondent":"江部総務課長","answer":"その職責がどのように変わって、それに対応できる方がどういう方がということは、まさに今、意見が交わされているところであるというふうに聞いております。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"提案","question":"提案を我々議会にしてくるときに、そこら辺のところの説明も必要になってくるのだろう、非常にそこら辺の重みが変わってくるのだろうということの意識を我々も持っておかないと、我々、レクチャーを受けた中で我々の責任も問われますという話が大分あったのは事実で、だから、そこら辺のところだけは、今みたいにただ聞いているというだけの話ではなくなってくるということだけは、そのときに出てきた例は。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]},{"id":"topic-04","title":"の第１７号議案 品川区職員定数条例の一部を改正する条例","agenda":"の第１７号議案 品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"保育士がプラス１８ということで、この間進めている区立認可保育園の新設という、４歳児、５歳児クラスの追加というのでしょうか、こういうところは必要な手立てだし、区民にも求められていると思いますので、今後もぜひ進めていただきたいと思います。例えば、今、念頭に置いている定数減や定数増や、そういう今後の見通しや考え方をどう考えているのか、そこだけ１点伺いたいと思います。","respondent":"堀越人事課長","answer":"委員ご紹介ありましたように、保育士等増員を図る一方、工夫を図りながら減員を進めていくということですので、必要なところにはしっかりと配置をして、区政運営をしっかりと対応していくというのが考え方です。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"用務員が７人減るということなのですが、保育園を増設したりとかしている関係で、用務員は非常に大切な役割を担っているのではないかと思うのです。これ、４０とか、５０とか、７０とかありますけれども、この数値はどこから来ている数値、何か法則があって７０とかにするというのがあるのでしょうか。実態も含めて、これがどう反映されていて、運用に使われているのかということも含めてお伺いします。","respondent":"堀越人事課長","answer":"７０の内訳といたしましては、新規の保育士の採用が大体約５０名で、それから、若い職員の採用が増えていますので、育児休業の代替という形の職員が２０数名ぐらいの予定をしておりますので、そういった形であわせて弾力的に対応していくために一定数。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"確かに効率を上げるためにというのはわからないではないし、当然、行財政改革ですから無駄のないような形で仕事をしていくというのは当然だと思うのです。それを保育士ができるからというふうに安易に考えないでほしいとは思うのですが、そのノウハウとか、それについてはどういうふうにしていって、こういう７という減を決められたのかということをもう一度お聞きしたいと思います。","respondent":"堀越人事課長","answer":"清掃等もそうですし、いろいろな消耗品の管理なども、今、いろいろなインターネット関係等もかなり進んでまいりまして、特に在庫をそれほど持たなくても迅速に発注ができるというふうな状況にもなってありますので、そういう中で保育士としてのいろいろな。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"職員定数と考えたときに、これからいろいろな事業展開をする中で、本当に必要な人材、人数はどうなのかというのは、当然、人材育成にもかかわってくる部分ではあると思うのですけれども、それを含めながら改革のほうは進めていくなり、増やすところについてはしっかりと増やしていただきたいということで意見を言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"須貝委員","kind":"確認","question":"現在、区民の人口が増えてきている中で、この２３区、とりわけ品川区でもこれから高齢化がますます加速すると思うのです。区民の人数が減っている中、高齢化も進まないような、さまざまな事業も品川区は結構一生懸命やっていると思うのですが、これは大丈夫なのですよねというのをちょっと確認だけお願いいたします。","respondent":"堀越人事課長","answer":"４ページの表を見ていただきますと、今までの推移が出てきておりますけれども、やはりいろいろな課題等、保育園の増設等もございまして、見直しの人数的にもここ最近の変化は見てとれると思いますので、これは必要なところにはしっかりと配置をして。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問","question":"必ずいつもこういう時期にはこれが出てきて、話を今みたいに必要なところは必要な手当てをしてという話が出るのだけれども、１つだけ先にお聞きしたいのは、これは品川区も一地方自治体で、必ず人件費比率というのは出てくるわけで、人件費比率をどう捉えていらっしゃるのかという部分をまずお聞きしたいのと、この間、ずっと減ってきている部分については、民間の力を活用してよりよい区民サービスが。","respondent":"堀越人事課長","answer":"その結果、人件費比率等が数字となってあらわれているというふうに思ってありますが、いろいろ工夫を図りながら最小限の人数でしっかりと対応していくということが、これも繰り返しで、全部繰り返しで申しわけないのですが、そのような考え方です。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは今までもそうされてきたと思っています。では、それを全部大所帯を移動できるぐらいの政策判断があるかどうかというのは、これは議論が必要だと思いますし、それは区長判断もあるでしょうから、ここで皆さまがどうということではないでしょうけれども、それは検討していただきたいと思います。余裕がないと我々はすごく思う。","respondent":"中山総務部長","answer":"職員、直営と言っていいかもしれませんけれども、民間の力の活用、そういう中で区政をどうやっていくかみたいなところの設定ですけれども、１つは、これはサービスの低下を招かないといいますか、さらに言えば、今回の図書館の指定管理などでも、単純に業務に関して。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問","question":"１つだけ、こんな質問していいのか。変な質問で悪いけれども。","respondent":"中山総務部長","answer":"職員の全てを語るだけの立場ではありませんけれども、よく品川区の行政運営において、我々は、区長がいろいろな場面で言われるのですけれども、不断の行政改革というふうなものについては、１つＤＮＡとして同じやり方を踏襲するのではなく、工夫がないのか、あるいは。","id":"exchange-031"},{"speaker":"中塚委員","kind":"意見","question":"一言意見表明したいと思います。図書館の指定管理者制度はやめるべきだと思います。民間の活用というお話が繰り返されていましたけれども、実態は自治体自身が生活できないワーキングプアをつくるものだと私は思います。住民福祉を削る行革には反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-05","title":"の第１８号議案 職員の給与に関する条例の一部を改正する条例","agenda":"の第１８号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"給料表が１.７％下がるということになると、退職金等々もこれに準じて下がるわけですね。実際は、この計算でいうと、とんとんという形、プラスマイナスゼロみたいな感じになるのですけれども、実はそうではなくて、職員の方々の退職金を含めた形で考えると、大分下がるのではないかと思うのですけれども、それはどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"そうですね。では、それは次にします。済みません。では、次の質問、もう１つあるのですが、(2)の単身赴任手当のところですけれども、こういう該当する方は品川区にいるのか、多分被災者支援で行かれている方などは、定期的に帰られていると思うのですけれども、その方たちが該当するようになるのか、そこら辺を教えてください。","respondent":"堀越人事課長","answer":"単身赴任手当ですけれども、今現在は、宮古市被災地支援派遣で行っている職員が７名おりますけれども、そのうちの２名が単身赴任手当の該当になっているというものです。","id":"exchange-034"}]},{"id":"topic-06","title":"の第１９号議案 職員の退職手当に関する条例の一部を改正する条例","agenda":"の第１９号議案 職員の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"西本委員","kind":"質問","question":"いろいろと退職金関係で改正になるということなのですが、かなりポイント制になって上がるというふうな感覚にはなるのですけれども、実際どうなのでしょうか。かなり改善されたというふうに受け取っていいのだろうかということなのですが。この適用区分の中に、保育園の園長先生はどの辺に入るのかと思っているのですが、それを教えてください。","respondent":"堀越人事課長","answer":"そのほか職層が下に行くに従いまして、少しそれが減ってくるというふうな形になってございまして、全体としては、支給水準は変わらないのですけれども、より職層に応じた形でポイントを増やしていますので、その分、反映されているというふうに考えてあります。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332522?Template=document&Id=2010#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":39946,"voices":182}}]);
